(window.GAMES = window.GAMES || {})[2017] = [{"t":".hack//G.U. Last Recode","p":["Windows","PlayStation 4"],"g":"Action RPG","r":"November 3","l":"https://en.wikipedia.org/wiki/.hack//G.U._Last_Recode"},{"t":"1-2-Switch","p":["Nintendo Switch"],"g":"Party","r":"March 3","l":"https://en.wikipedia.org/wiki/1-2-Switch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21q3.jpg","s":"1-2-Switch is a party game for everyone! Throw an impromptu party anywhere with anyone thanks to a new play style in which players look at each other—not the screen! Bring the action and fun into the real world as you face off in wild-west duels, cow-milking competitions, and more. While the action unfolds off-screen, the audience watches the players themselves instead of the screen."},{"t":"10 Second Run Returns","p":["Nintendo Switch"],"g":"Platform, Racing","l":"https://en.wikipedia.org/wiki/10_Second_Run_Returns","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gsm.jpg","s":"Reach the finish line in 10 seconds!\n\nThe legendary action game, \"10 Second Run\" is back! The rules (and controls) are simple: \"Move Sideways\" and \"Jump & Dash\" to get to the finish line in under 10 seconds! Unlock different types of stick figures as you clear the stages! Run solo or race against others in multiplayer mode! Any time, any where, with anyone, simply run, run, run! You'll be surprised how much excitement is packed in 10 seconds- and how long 10 seconds can be!"},{"t":"100ft Robot Golf","p":["Windows"],"g":"Sports","r":"March 16","l":"https://en.wikipedia.org/wiki/100ft_Robot_Golf"},{"t":"2000:1: A Space Felony","p":["Windows"],"d":"National Insecurities","u":"Humble Games","g":"Adventure","r":"July 2017","l":"https://en.wikipedia.org/wiki/2000:1:_A_Space_Felony","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22jb.jpg","s":"2000:1 - A Space Felony is a murder mystery courtroom drama set aboard the USS Endowment, an interplanetary Spacecraft that has lost communication with Earth.\n\nUtilising your camera and demonstrating your keen detective skills, you must document your findings, and piece together the crew's final hours from the aftermath. This photographic evidence is then applied in a cross-examination of the crime's prime suspect; MAL, the ship's on-board AI system.\n\nIf MAL is guilty, it is your responsibility to deactivate him.\n\nA follow-up(ish) to 2016's critically acclaimed(ish) \"Disorient On The Murder Express\", National Insecurities returns with a much more ambitious investigation that walks the line between science and fiction, resulting in some kind of combination of the two."},{"t":"2Dark","p":["Windows","PlayStation 4","Xbox One"],"d":"Gloomywood","u":"Bigben Interactive","g":"Adventure, Stealth, Survival horror","r":"March 10, 2017","l":"https://en.wikipedia.org/wiki/2Dark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22je.jpg","s":"From Frédérick Raynal, the creator of Alone in the Dark and pioneer of survival-horror, 2Dark is a grim journey of stealth and courage into the heart of corruption. Plagued by a string of child abductions, darkness hangs over the once-picturesque city of Gloomywood like a curse. As former detective Mr. Smith, use your cunning to infiltrate six bastions of cruelty. Uncover the secrets of the deranged psychopaths within, seek retribution for their crimes, and bring the children to safety."},{"t":"88 Heroes: 98 Heroes Edition","p":["Nintendo Switch"],"r":"October 10"},{"t":"9-Nine","p":[],"l":"https://en.wikipedia.org/wiki/9-Nine"},{"t":"911 Operator","p":["Windows","PlayStation 4","Xbox One","Android","Nintendo Switch","macOS","iOS"],"d":"Jutsu Games","u":"PlayWay, Code Horizon, SONKA","g":"Simulation","r":"February 24, 2017","l":"https://en.wikipedia.org/wiki/911_Operator_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gjv.jpg","s":"911 Operator is a game about the difficult work of people that manage emergency lines and services. Main task is to answer incoming calls and to react properly - give first aid instructions, advise, dispatch correct number of firemen / police / ambulances, or sometimes just ignore the call."},{"t":"A Demon's Game - Episode 1","p":["Windows"],"r":"February 17","l":"https://en.wikipedia.org/wiki/A_Demon%27s_Game_-_Episode_1"},{"t":"A Duel Hand Disaster: Trackher","p":["Windows","PlayStation 4","Xbox One"],"d":"Ask An Enemy Studios","u":"Ask An Enemy Studios","g":"Action","r":"August 29, 2017","l":"https://en.wikipedia.org/wiki/A_Duel_Hand_Disaster:_Trackher","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1i67.jpg","s":"Split-screen single player twin stick risk 'em up. Your score is meaningless unless you exist. Playing till death will leave you scoreless and will also wipe your previous position from the leaderboard. Don't lose sight of your mission. Trackher."},{"t":"A Hat in Time","p":["Windows","macOS","PlayStation 4","Xbox One"],"g":"Platformer, Action-adventure","r":"October 5","l":"https://en.wikipedia.org/wiki/A_Hat_in_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob1uc.jpg","s":"A Hat in Time is a cute-as-heck 3D platformer featuring a little girl who stitches hats for wicked powers! Freely explore giant worlds and recover Time Pieces to travel to new heights!"},{"t":"A Hole New World","p":["Windows","macOS","Linux"],"r":"May 19"},{"t":"A House of Many Doors","p":["Windows","macOS"],"r":"February 3"},{"t":"A Mortician's Tale","p":["Windows","macOS"],"r":"October 18","l":"https://en.wikipedia.org/wiki/A_Mortician%27s_Tale"},{"t":"A Normal Lost Phone","p":["Windows","macOS","Linux","Android","iOS"],"d":"Accidental Queens","u":"Playdius, Plug In Digital","g":"Puzzle","r":"January 26, 2017","l":"https://en.wikipedia.org/wiki/A_Normal_Lost_Phone","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kfs.jpg","s":"A Normal Lost Phone is a game about exploring the intimacy of an unknown person whose phone was found by the player."},{"t":"A Rose in the Twilight","p":["Windows","PlayStation Vita"],"g":"Adventure, Strategy","r":"April 11","l":"https://en.wikipedia.org/wiki/A_Rose_in_the_Twilight"},{"t":"A3!","p":[],"l":"https://en.wikipedia.org/wiki/A3!"},{"t":"Aaero","p":["Windows","PlayStation 4","Xbox One"],"g":"Action, Rhythm","r":"April 11","l":"https://en.wikipedia.org/wiki/Aaero"},{"t":"Absolver","p":["Windows","PlayStation 4"],"g":"Action RPG","r":"August 29","l":"https://en.wikipedia.org/wiki/Absolver","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45wq.jpg","s":"Absolver is an online multiplayer combat RPG where players are placed behind the mask of a Prospect under control of the Guides, the new rulers of the fallen Adal Empire, who have placed you here to determine your worth in joining their elite corps of Absolvers."},{"t":"Accel World VS. Sword Art Online","p":["PlayStation 4","PlayStation Vita"],"r":"July 7"},{"t":"Accel World vs. Sword Art Online: Millennium Twilight","p":["PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"March 16"},{"t":"Ace of Seafood","p":["PlayStation 4"],"r":"November 9"},{"t":"Acorn Tactics","p":["Nintendo Switch"],"g":"Puzzle, Simulator, Strategy, Card & Board Game","l":"https://en.wikipedia.org/wiki/Acorn_Tactics","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zth.jpg","s":"Alien blobs from space are invading the Earth. It’s up to the Alien Counter Offensive Response Network (ACORN) to stop them from enacting their evil plans. Construct and customize a strike team of giant walking tanks and air drop them into combat. Customise, upgrade and train to save the planet from King Blob in a giant 25 mission hand-crafted story campaign. Then take your custom battle team into the random mission generator and visit procedurally generated bases and challenge yourself to endless battles. Collect and upgrade a deck of battle-cards to take with you into combat. Use their special effects to turn the tide of war against your foes. Can you defend the planet from invasion?"},{"t":"Adopt Me!","p":["Windows","macOS","Xbox One","iOS","Android","PlayStation 4"],"d":"Uplift Games","u":"Uplift Games","g":"MMORPG, pet-raising simulation","r":"July 13, 2017","l":"https://en.wikipedia.org/wiki/Adopt_Me!"},{"t":"Aer: Memories of Old","p":["Windows","PlayStation 4","Xbox One"],"d":"Forgotten Key","u":"Daedalic Entertainment","g":"Action-adventure","r":"October 25, 2017","l":"https://en.wikipedia.org/wiki/Aer:_Memories_of_Old","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1v8z.jpg","s":"Transform into a bird and fly to explore and experience a vibrant world of floating islands in the sky. Venture down into lost ancient ruins where each step leads you closer to the end of the world.\n\nAER puts you in the shoes of Auk, a magical shape-shifting girl who can transform between human and bird."},{"t":"Afghanistan '11","p":["Windows","Android"],"d":"Every Other Soldier","u":"Slitherine Software","g":"Turn-based strategy","r":"May 23, 2017","l":"https://en.wikipedia.org/wiki/Afghanistan_'11","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22mg.jpg","s":"Afghanistan '11 is the sequel to the highly praised and innovative Vietnam '65. It enhances and builds on it: Afghanistan '11 changes the paradigm of wargaming and manages to bring Counter-Insurgency and guerrilla warfare to your screen, properly represented thanks to a revolutionary gameplay formula!"},{"t":"AFL Evolution","p":["PlayStation 4","Xbox One","Windows"],"d":"Wicked Witch Software","u":"Tru Blu Entertainment","g":"Sports","r":"May 5, 2017","l":"https://en.wikipedia.org/wiki/AFL_Evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22mk.jpg","s":"EXPERIENCE THE EVOLUTION - AFL Evolution brings you the most intense and feature packed AFL experience ever."},{"t":"Agatha Knife","p":["Windows","macOS","Linux","PlayStation 4"],"d":"Mango Protocol","u":"Mango Protocol, Plug In Digital","g":"Adventure","r":"April 27, 2017","l":"https://en.wikipedia.org/wiki/Agatha_Knife","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wg4.jpg","s":"Embark on a whimsically twisted adventure with Agatha, a child torn between her love for eating meat and her friendships with animals. Join her as she discovers religion and creates her own, Carnivorism, to convince the animals that the sacrifice of their flesh is the secret to their eternal happiness."},{"t":"Agents of Mayhem","p":["Windows","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"August 15","l":"https://en.wikipedia.org/wiki/Agents_of_Mayhem","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22mh.jpg","s":"Agents of Mayhem is the new open world game from Volition, the studio that brought you the Saints Row franchise. Play as a cast of unique and diverse Super Agents from all over the world, and lead them in MAYHEM’s epic fight to save the city of Seoul from the destructive schemes of the evil supervillain organization LEGION!"},{"t":"Air Guitar Warrior","p":[],"l":"https://en.wikipedia.org/wiki/Air_Guitar_Warrior"},{"t":"Akiba's Beat","p":["PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"May 16","l":"https://en.wikipedia.org/wiki/Akiba%27s_Beat"},{"t":"Albion Online","p":["Windows","macOS","Linux"],"d":"Sandbox Interactive","u":"Sandbox Interactive","g":"MMORPG","r":"July 17, 2017","l":"https://en.wikipedia.org/wiki/Albion_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsxx.jpg","s":"Albion Online is a free-to-play sandbox MMORPG set in a medieval fantasy world inspired by Arthurian legends. The game uses a classless system where a player's equipped gear determines their abilities and playstyle. Items span eight tiers and are entirely player-crafted, forming a fully player-driven economy. The open world features zones with varying levels of PvP risk, from safe areas to full-loot zones where defeated players lose their equipment. Players can join guilds of up to 300 members to fight over territories and castles in large-scale battles. The game also offers PvE combat and various gathering and crafting activities."},{"t":"All the Delicate Duplicates","p":["Windows"],"d":"Mez Breeze, Andy Campbell","g":"Psychological/Exploration Game","r":"February 18, 2017","l":"https://en.wikipedia.org/wiki/All_the_Delicate_Duplicates","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z0i.jpg","s":"John, a single father, inherits a collection of arcane objects from his mysterious relative named Mo. Over time, John and his daughter Charlotte begin to realise that these objects have unusual properties: the more they are exposed to them, the more their reality and memories appear to change."},{"t":"Alwa's Awakening","p":["Linux","macOS","Windows","Nintendo Switch","PlayStation 4","Xbox One","Nintendo Entertainment System"],"d":"Elden Pixels","u":"Elden Pixels","g":"Metroidvania","r":"February 2, 2017","l":"https://en.wikipedia.org/wiki/Alwa's_Awakening","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zqw.jpg","s":"Use your magic staff and progress through a large interconnected world where you'll solve puzzles, fight enemies and defeat bosses in order to help free the land of Alwa. Explore and uncover the secrets by using your platforming skills in this challenging and charming 8-bit adventure game.\n\nAlwa’s Awakening is a game that tries to stay as close as possible to the authentic 8-bit look with sweet pixel art, a soundtrack filled with catchy chiptunes and so much charm it’ll bring you right back to the NES era. With easy to understand controls the game is easy to learn but tough to master, just like how games were in the old days!\n\n- A new challenging NES-inspired adventure game\n- Use the magic staff to solve puzzles and defeat enemies\n- Find and unlock upgrades to your items and abilities\n- Explore a large interconnected map in true 'Metroidvania' style\n- Listen to a completely new 8-bit soundtrack with over 25 new original tracks"},{"t":"Amnesia Fortnight 2017","p":["Windows"],"d":"Double Fine Productions","u":"Double Fine Productions","g":"Various","l":"https://en.wikipedia.org/wiki/Amnesia_Fortnight_2017"},{"t":"Angels with Scaly Wings","p":["Windows","PlayStation 4","Xbox One"],"g":"Visual novel, Dating sim","r":"January 31"},{"t":"Angry Birds Evolution","p":["Android","iOS"],"d":"Chimera Entertainment","u":"Rovio Entertainment","g":"Puzzle, role-playing","r":"June 15, 2017","l":"https://en.wikipedia.org/wiki/Angry_Birds_Evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rf7.jpg","s":"Something is causing the the pigs to herd to Bird Island in droves, and the birds have found their eggs in danger once again. It’s up to you to assemble an unstoppable team of evolved super birds and put a stop to the pigs’ shenanigans once and for all. Or at least until the next time they pull a stunt like this...\n\nCollect, assemble, and evolve your flock.\n100+ crazy new Angry Birds?! We’re gonna need a bigger nest. The flock is bigger and badder than ever before. Build your own team, combine super skills and evolve your birds into their ultimate form.\nEmbark on an epic adventure.\n\nSomething sinister is brewing on Bird Island. Why are there so many pigs around? Who is behind the mysterious Bacon Corp? What’s the Eagle Force? Who lost the dungeon keys? Find the answers – only in Angry Birds Evolution.\n\nCrush the pigs in explosive battles.\nWhat’s worse than egg-stealing pigs? Over 90 different varieties of egg-stealing Pigs, that's what. Pirates, ninjas, tourists – someone has to clean this place up. Let the feathers fly in full contact battles and send the pigs packing.\n\nJoin weekly events.\nEarn awesome rewards, and get a chance to add extra rare birds to your team by taking part in weekly events. Join by yourself or assemble a clan of buddies to compete with other clans. Build the strongest, most awesome clan on Bird Island and rule the roost!\n\nCompete against other players.\nThe Oinktagon: two teams enter – only one leaves (victorious). Challenge other players in PVP tournaments of the Bird Island pastime, Pigball, and dominate the leagues for even more awesome rewards.\n\nFEATURES:\n– Over 100 colorful new characters to hatch and collect.\n– Assemble the ultimate flock of birds and take down the pigs with ease.\n– 5 Classes of birds with unique abilities.\n– Evolve your feathery heroes into unstoppable super birds.\n– Explore the island and stop the Bacon Corp.\n– Climb up the Eagle Mountain and win ultimate eggs.\n– Battle other players in the Oinktagon.\n– Join clans to unlock perks, compete with other clans, and chat with clanmates.\n– Send out scouts for rewards & challenges"},{"t":"Animal Crossing: Pocket Camp","p":["iOS","Android"],"g":"Social sim","r":"November 21","l":"https://www.igdb.com/games/animal-crossing-pocket-camp","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nz5.jpg","s":"In Animal Crossing: Pocket Camp, it's up to you to build a fun campsite for you and your friends to enjoy. Tents, hammocks, fireplaces, a stuffed-animal sofa... mix and match to your heart's content! Make a trendy open-air café, or line up some microphones and guitars to create an outdoor music festival. In the mood for a little extra fun? Set up a merry-go-round and open a theme park. You can even make a pool, or fill the sky with fireworks!"},{"t":"Another Eden","p":["Android","iOS"],"d":"Wright Flyer Studios","u":"Wright Flyer Studios","g":"Role-playing","r":"April 12, 2017","l":"https://en.wikipedia.org/wiki/Another_Eden","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocru0.jpg","s":"Embark on a journey beyond time and space.\nTo save our lost future.\nBefore the darkness of time falls upon us all...\n\nGame Overview\n・A surprising amount of content for a mobile gaming app.\n・A modernized classic spacetime RPG.\n・An epic story crossing the Antiquity, Present, and Future from master story writer Masato Kato.\n・Including the main theme written by Mitsuda Yasunori, the game contains over 60 songs recorded with orchestras and folk music."},{"t":"Antihero","p":["Windows","macOS"],"d":"Tim Conkling","u":"Versus Evil","g":"Turn-based strategy","r":"July 10, 2017","l":"https://en.wikipedia.org/wiki/Antihero_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/onbw41orydmnbhd19k8u.jpg","s":"Run a thieves’ guild in a gas-lit underworld.\nAntihero is a fast-paced strategy game with an (Oliver) Twist. Recruit urchins, hire thugs, kit out your master thief, upgrade your guild… and bribe, blackmail, and assassinate your opposition.\n\nA turn-based multiplayer strategy game about running a thieves' guild. Antihero is all about short play sessions with super-interesting decisions. Recruit street urchins, hire gangs, steal everything - and bribe, blackmail, and assassinate your way to victory. Hone your skills against the AI, play online with the Antihero community, or share a PC with a friend in the offline hotseat multiplayer mode."},{"t":"Antinomy of Common Flowers","p":["Windows"],"d":"Twilight Frontier, Team Shanghai Alice","u":"Twilight Frontier, Team Shanghai Alice, Sunfish, Phoenixx","g":"Fighting","r":"May 7, 2017","l":"https://en.wikipedia.org/wiki/Antinomy_of_Common_Flowers"},{"t":"Antiquia Lost","p":["PlayStation 4","PlayStation Vita","Nintendo Switch"],"r":"September 5","l":"https://en.wikipedia.org/wiki/Antiquia_Lost"},{"t":"Antisphere","p":["Windows","PlayStation 4","Xbox One"],"r":"July 14","l":"https://en.wikipedia.org/wiki/Starbreeze_Studios"},{"t":"Aporia: Beyond the Valley","p":["Windows"],"d":"Investigate North","u":"Green Man Gaming","g":"Adventure, Puzzle Game","r":"July 19, 2017","l":"https://en.wikipedia.org/wiki/Aporia:_Beyond_the_Valley","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7y8a.jpg","s":"Aporia: Beyond The Valley brings a unique approach to the art of storytelling, by not using text or dialogue. It offers new, interesting puzzle mechanics, and elaborate environmental storytelling within an immersive world.\n\nAporia: Beyond The Valley is a first-person puzzle game set in the world of Ez’rat Qin. Explore a world filled with strange nature, ancient technology, and haunted by a spirit roaming the fog-covered forest. With a whole new story and puzzle mechanics, Aporia: Beyond The Valley presents players with the challenge of actively exploring and piecing together a non-linear story of what happened in this mysterious world."},{"t":"Arc Symphony","p":["Windows","macOS","Linux","Browser"],"d":"Matilde Park, Penelope Evans","g":"Adventure","r":"May 15, 2017","l":"https://en.wikipedia.org/wiki/Arc_Symphony","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fps.jpg","s":"Arc Symphony places you as an invader in the Usenet newsgroups of yesterday. Discover the ancient JRPG, Arc Symphony, in this meditation on fan culture and identity in the reflection of the monitor."},{"t":"Arcaea","p":["iOS","Android"],"d":"Lowiro","u":"Lowiro","g":"Rhythm","r":"March 9, 2017","l":"https://en.wikipedia.org/wiki/Arcaea","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6nnx.jpg","s":"A three dimensional rhythm game released on iOS and Android devices.\n\"A harmony of Light awaits you in a lost world of musical Conflict.\""},{"t":"Arcana Heart 3: Love Max Six Stars","p":["Windows"],"r":"December 12"},{"t":"Archangel","p":["Oculus Rift","Windows","PlayStation VR"],"d":"Skydance Interactive","u":"Skydance Interactive","g":"First-person shooter","r":"July 18, 2017","l":"https://en.wikipedia.org/wiki/Archangel_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co29ii.jpg","s":"We want to let you enter to the Archangel world, where Angels and Demons live inside an endless war, where Humans and Elves are their objective.\nAinur, is one of the last Angels who remains in this world and his mission, is the freedom, the peace for the humanity."},{"t":"Argo","p":["Windows"],"d":"Bohemia Interactive","u":"Bohemia Interactive","g":"Tactical shooter","r":"June 22, 2017","l":"https://en.wikipedia.org/wiki/Argo_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23qh.jpg","s":"Jump straight into combat in this experimental total conversion of Arma 3, and enter some of the most exhilarating online multiplayer battles in gaming. Project Argo is a competitive tactical first-person shooter, in which two bands of mercenaries compete over objectives in a 5-vs-5 match-up. Fight in unrestricted terrain, where a single bullet is all it takes, and master your craft to become (in)famous on the battlefield. Your keys to victory are teamwork, tactics, and skill."},{"t":"Ark: Survival Evolved","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"g":"Action-adventure, Survival","r":"August 29","l":"https://www.igdb.com/games/ark-survival-evolved","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co493k.jpg","s":"Ark: Survival Evolved is an open-world action-adventure survival game where players awaken stranded on a mysterious island populated by dinosaurs, prehistoric creatures, and mythical beasts. Gameplay revolves around gathering resources, crafting tools and structures, and taming creatures that can be ridden or used for combat and transportation. The game supports both single-player and multiplayer modes, with multiplayer servers allowing players to form tribes and compete or cooperate. Several expansion packs add new maps and storylines, and the game spawned an animated series, a remaster in Unreal Engine 5 titled Ark: Survival Ascended, and a planned sequel."},{"t":"Arkanoid vs. Space Invaders","p":["Android","iOS","Nintendo Switch"],"d":"Taito","u":"Taito, Square Enix","g":"Block breaker, Shoot'em up","r":"May 17, 2017","l":"https://en.wikipedia.org/wiki/Arkanoid_vs._Space_Invaders","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49oa.jpg","s":"Two of Taito's most beloved arcade classics combine with cameos from their other releases to produce one frantic title."},{"t":"Arktika.1","p":["Meta Quest"],"r":"October 10","l":"https://en.wikipedia.org/wiki/Arktika.1"},{"t":"Arms","p":["Nintendo Switch"],"g":"Fighting","r":"June 16","l":"https://en.wikipedia.org/wiki/Arms_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mxn.jpg","s":"Arms, a mix of boxing and shooting where you use extendable arms to battle your friends both locally and online! Take a Joy-Con in each hand and punch forward, twisting your fists to bend your attacks.\n\n\"Choose a fighting champion from around the world, equip your own combination of extendable arms, and then use a mix of button presses and quick hand motions to really take the fight to your opponent. Throw punches and guide them midflight to hit agile fighters, avoid incoming attacks with dashes, or trampoline high into the air to rain down fists from above. Power-up your punches to deal extra damage or curve your fists around obstacles to hit skittish opponents. Fill up your special gauge to dish out devastating combinations and finish them off. Unleash your inner fighter in this unbelievable sporting event! \""},{"t":"Arms Race - TCWE","p":["Windows"],"g":"Simulation","r":"October 5"},{"t":"Ashes Cricket","p":["PlayStation 4","Xbox One","Windows"],"d":"Big Ant Studios","u":"Big Ant Studios","g":"Sports","r":"November 2017","l":"https://en.wikipedia.org/wiki/Ashes_Cricket","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23o4.jpg","s":"Ashes Cricket is the officially licensed video game of cricket’s greatest rivalry. Bringing all the fast paced action, big hits and skill that you see in the greatest cricket competition on earth, in both a more realistic and authentic way than ever before, you’ll be able to bathe your team in glory in the men’s and women’s 2017/2018 Ashes tours."},{"t":"Assassin's Creed: Origins","p":["Windows","PlayStation 4","Xbox One"],"g":"Action-adventure, Stealth","r":"October 27","l":"https://www.igdb.com/games/assassins-creed-origins","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rbe.jpg","s":"Assassin’s Creed Origins is an action-adventure game set in ancient Egypt at the end of the Ptolemaic era. The story follows Bayek, a Medjay tasked with protecting the people, as personal tragedy draws him into a wider conflict that leads to the origins of the Assassin Brotherhood.\n\nThe game features a large open-world recreation of Egypt, including cities, deserts, and the Nile, with an increased emphasis on exploration. Gameplay combines stealth, melee and ranged combat, and role-playing elements such as character leveling, skill trees, and gear progression."},{"t":"Astro Duel Deluxe","p":["Nintendo Switch"],"r":"May 30","l":"https://en.wikipedia.org/wiki/Astro_Duel"},{"t":"Atelier Firis: The Alchemist and the Mysterious Journey","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"RPG","r":"March 7"},{"t":"Atelier Shallie Plus: Alchemists of the Dusk Sea","p":["PlayStation Vita"],"g":"RPG","r":"January 17"},{"t":"Atelier Sophie: The Alchemist of the Mysterious Book","p":["Windows"],"g":"RPG","r":"February 7"},{"t":"Atomega","p":["Windows"],"d":"Ubisoft Reflections","u":"Ubisoft","g":"Action, shooter","r":"September 19, 2017","l":"https://en.wikipedia.org/wiki/Atomega","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2phg.jpg","s":"Grow, fight, collect and evade in the last cosmic arena the very end of time. Acquire Mass to evolve your Exoform from the nimble Atomto the godlike Omega and compete for fun and dominance in a fast-paced, multiplayer shooter."},{"t":"Attack on Titan: Escape from Certain Death","p":["Nintendo 3DS"],"r":"March 30","l":"https://en.wikipedia.org/wiki/Attack_on_Titan#Video_games"},{"t":"Attentat 1942","p":["macOS","Windows","Linux","Android","iOS"],"d":"Charles University, Czech Academy of Sciences","u":"Charles University, Czech Academy of Sciences","g":"Adventure, Educational","r":"October 31, 2017","l":"https://en.wikipedia.org/wiki/Attentat_1942","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hmy.jpg","s":"Attentat 1942 tells the story of Nazi occupation from the perspective of those who experienced it firsthand. The game is built on dialogues, interactive comics, and authentic footage. Speak to eyewitnesses, live their memories, and discover the untold story of your family!"},{"t":"ATV Renegades","p":["PlayStation 4","Xbox One"],"r":"April 18"},{"t":"Aven Colony","p":["Windows","PlayStation 4","Xbox One"],"g":"City builder, Strategy","r":"July 25","l":"https://en.wikipedia.org/wiki/Aven_Colony","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co234w.jpg","s":"Aven Colony is a city-building and management sim that tells the story of humanity’s first settlement of an extrasolar world. Land on exotic Aven Prime, where you must construct and maintain the infrastructure and ensure the well-being of your citizens, all while dealing with the often harsh realities of an exotic alien world.\n\nOn top of this, you’ll face the greatest challenge of all — keeping your people happy. How will you feed your people? Will you be able to provide them with enough jobs, entertainment, retail outlets, and other services while protecting them from the planet’s many dangers? What social policies will you enact to influence your people? The future of the colony rests on your decisions."},{"t":"Axiom Verge","p":["Nintendo Switch"],"g":"Metroidvania","r":"October 5","l":"https://en.wikipedia.org/wiki/Axiom_Verge"},{"t":"Aztez","p":["Windows","macOS","Linux"],"d":"Team Colorblind","g":"Brawler, hack and slash, turn-based strategy","r":"August 1, 2017","l":"https://en.wikipedia.org/wiki/Aztez","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1za0.jpg","s":"In Aztez, you expand and maintain the Aztec empire through turn-based strategy, while managing violent outbreaks via real-time beat 'em up sequences. Every game is unique; different events will occur, different challenges will emerge, and different spoils will be taken each time you play. Spread, strengthen, subjugate!"},{"t":"Azur Lane","p":["Android","iOS"],"g":"Shooter, Role-playing (RPG), Simulator, Strategy, Tactical, Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Azur_Lane","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/pekj1zf9iydfvwjecrpw.jpg","s":"Azur Lane is a side-scrolling shoot 'em up video game created by Chinese developers Shanghai Manjuu and Xiamen Yongshi, released in 2017 for the iOS and Android operating systems. Set in an alternate timeline of World War II, players engage in side-scrolling shooter gameplay, using female moe anthropomorphic characters based on warships from the war's major participants. Other gameplay elements, like customizing a home and marrying in-game characters, are also present.\nFirst launched in China in May and in Japan in September 2017, Azur Lane has become very popular, especially in Japan where the player count reached five million within four months after its release. Players have voted the game among the top five on Google Play's Best Game of 2017 list for the region. Critics have attributed the game's popularity to its original and well-designed gameplay system."},{"t":"B-Project","p":[],"l":"https://en.wikipedia.org/wiki/B-Project"},{"t":"Baja: Edge of Control HD","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"September 14"},{"t":"BanG Dream! Girls Band Party!","p":["Android","iOS"],"d":"Craft Egg, Bushiroad","u":"Bushiroad, Mobimon Inc., bilibili, Kakao Games","g":"Rhythm game, visual novel","r":"March 16, 2017","l":"https://en.wikipedia.org/wiki/BanG_Dream!_Girls_Band_Party!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7lau.jpg","s":"BanG Dream! Girls Band Party! is a free-to-play rhythm game released for iOS/Android devices as part of the BanG Dream! multi-media franchise.\n\nThe game contains two modes: a story mode and a rhythm game mode. The story follows five girl bands pursuing their dreams of becoming musicians. The game is played by building teams consisting of these different band members. As they complete songs in the game, players acquire currencies that can be used to level up band members or buy new ones."},{"t":"Batman: The Telltale Series","p":["Nintendo Switch"],"g":"Graphic adventure","r":"November 14","l":"https://www.igdb.com/games/batman-the-telltale-series","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u65.jpg","s":"Batman: The Telltale Series is an episodic graphic adventure game developed by Telltale Games, first released in 2016. The game offers a narrative-focused experience, where players control Bruce Wayne and his alter ego, Batman, making choices that shape the story and relationships with characters.\n\nThe plot explores Bruce Wayne’s struggle to uncover corruption in Gotham City, while confronting revelations about his family’s past. The game features dialogue-driven gameplay, quick-time combat, and detective sequences. Decisions carry over across episodes, influencing the narrative’s direction and character arcs."},{"t":"Battle Bay","p":["iOS","Android"],"d":"Rovio Entertainment","u":"Rovio Entertainment","g":"Real-time strategy, Action, Shooter","r":"May 4, 2017","l":"https://en.wikipedia.org/wiki/Battle_Bay","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pio.jpg","s":"Choose a ship, select your weapons and go to battle against opponents around the world. Use team strategy and firepower to take your fleet to the top - it’s sink or win!"},{"t":"Battle Brothers","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Overhype Studios","u":"Overhype Studios, Hooded Horse","g":"Tactical role-playing","r":"March 24, 2017","l":"https://en.wikipedia.org/wiki/Battle_Brothers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iop.jpg","s":"Battle Brothers is a turn based strategy RPG mix which has you leading a mercenary company in a gritty, low-power, medieval fantasy world. You decide where to go, whom to hire or to fight, what contracts to take and how to train and equip your men in a procedurally generated open world campaign. Do you have what it takes to lead them through bloody battles and to victory? The game consists of a strategic worldmap and a tactical combat layer. On the worldmap you can freely travel in order to take contracts that earn you good coin, find places worth looting, enemies worth pursuing or towns to resupply and hire men at. This is also where you manage, level up and equip your Battle Brothers. Once you engage a hostile party the game will switch to a tactical map where the actual fighting takes place as detailed turn based combat."},{"t":"Battle Chasers: Nightwar","p":["Windows","PlayStation 4","Xbox One"],"g":"Role-playing (RPG), Strategy, Turn-based strategy (TBS), Indie","r":"October 3","l":"https://www.igdb.com/games/battle-chasers-nightwar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zad8syobz3hdosfl9rar.jpg","s":"Battle Chasers: Nightwar is an American made JPRG and dungeon-crawler, based on the best-selling Battle Chasers comic series by Joe Maduriera and inspired by JPRG greats such as Final Fantasy, Suikoden, Chrono Trigger, and Phantasy Star. It was developed by Airship Syndicate, funded through Kickstarter and published by THQ Nordic. The game features beautiful environments; a gorgeously animated strategic turn-based combat system; and hand-crafted dungeon rooms which are randomly arranged for a different experience each time. Players will battle enemies, find secrets, solve puzzles and explore the world."},{"t":"Battle Chef Brigade","p":["Windows","Nintendo Switch","PlayStation 4"],"d":"Trinket Studios","u":"Adult Swim Games, Trinket Studios","g":"Brawler, puzzle","r":"November 20, 2017","l":"https://en.wikipedia.org/wiki/Battle_Chef_Brigade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1pks.jpg","s":"Battle Chef Brigade features fantasy chefs, including Orcs, Elves, and Humans, who need to hunt dangerous monsters for ingredients. With those ingredients, before the critical eye of the judges, the chefs create culinary masterpieces in an intense tournament. Battle Chef Brigade pairs one part combo-based action hunting and one part puzzle-based cooking, all as the round clock ticks down."},{"t":"Battlerite","p":["Windows","Xbox One"],"d":"Stunlock Studios","u":"Stunlock Studios","g":"Team brawler","r":"November 7, 2017","l":"https://en.wikipedia.org/wiki/Battlerite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsmn.jpg","s":"Battlerite is a Team Arena Brawler focused on adrenaline-fueled player vs player combat. Short and intense matches, stripped of random elements to optimize the action. Welcome to a world where champions dedicate their lives to the arena."},{"t":"Battlestar Galactica Deadlock","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Black Lab Games","u":"Slitherine Software","g":"Turn-based strategy","r":"August 31, 2017","l":"https://en.wikipedia.org/wiki/Battlestar_Galactica_Deadlock","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6f1h.jpg","s":"Battlestar Galactica Deadlock takes you into the heart of the First Cylon War, to fight epic 3D battles that will test your tactical prowess.\n\nTake control of the Colonial Fleet from the bridge of the mobile shipyard, Daidalos, and free the Twelve Colonies from the Cylon threat. Build your fleets, protect the Quorum alliance and prepare to dig deeper into the conspiracies of this heroic conflict."},{"t":"Bayonetta","p":["Windows"],"d":"PlatinumGames","u":"Sega","g":"Action, Hack and slash","r":"April 11, 2017","l":"https://en.wikipedia.org/wiki/Bayonetta_(video_game)","i":"images/steam-460790.jpg","s":"PlatinumGames’ universally acclaimed action masterpiece finally comes to PC. Experience the over-the-top stylish action in 60fps at unlocked HD resolutions. The definitive way to play: being bad never felt so good."},{"t":"Beat Cop","p":["Linux","macOS","Windows"],"d":"Pixel Crow","u":"11 bit studios","g":"Point-and-click, Puzzle, Simulator, Adventure, Indie","r":"March 30, 2017","l":"https://www.igdb.com/games/beat-cop","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22zc.jpg","s":"A retro, pixel art style adventure in New York, inspired by 80’s cop shows. You are Jack Kelly and you’ve been framed into murder. Now as a regular beat cop you have to find out, who did that. Expect thick crime story, a lot of black humour and all the other things you can find on the streets of Brooklyn."},{"t":"Behold the Kickmen","p":["macOS","Windows"],"d":"Size Five Games","u":"Size Five Games","g":"Sports","r":"July 20, 2017","l":"https://en.wikipedia.org/wiki/Behold_the_Kickmen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co53pb.jpg","s":"Behold the Kickmen is a football game made by someone who has no understanding of, or interest in, what is affectionately known as \"The Wonderful Game\".\n\nStart at the bottom of the Big Boring Football Spreadsheet and grind your way up to become the best at the football anyone's ever seen."},{"t":"Ben 10","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"r":"November 14","l":"https://en.wikipedia.org/wiki/Ben_10_(2017_video_game)"},{"t":"Bendy and the Ink Machine – Chapter One: Moving Pictures","p":["Windows","macOS","Linux"],"g":"Survival horror","r":"February 10","l":"https://en.wikipedia.org/wiki/Bendy_and_the_Ink_Machine"},{"t":"Bendy and the Ink Machine — Chapter Two: The Old Song","p":["Windows","macOS","Linux"],"g":"Survival horror","r":"April 18","l":"https://en.wikipedia.org/wiki/Bendy_and_the_Ink_Machine"},{"t":"Berserk and the Band of the Hawk","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Action RPG, Hack and slash","r":"February 21","l":"https://en.wikipedia.org/wiki/Berserk_and_the_Band_of_the_Hawk"},{"t":"Between the Sky and Sea","p":[],"l":"https://en.wikipedia.org/wiki/Between_the_Sky_and_Sea"},{"t":"Birthdays the Beginning","p":["PlayStation 4","Windows"],"r":"January 19","l":"https://en.wikipedia.org/wiki/Birthdays_the_Beginning"},{"t":"Bit City","p":["iOS","Android"],"g":"City builder, Clicker","r":"March 13","l":"https://en.wikipedia.org/wiki/Bit_City"},{"t":"Black & White Bushido","p":["PlayStation 4","Xbox One"],"r":"May 17"},{"t":"Black Mirror","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"g":"Adventure","r":"November 28","l":"https://en.wikipedia.org/wiki/Black_Mirror_(2017_video_game)"},{"t":"Black Souls I","p":["Windows"],"g":"RPG","r":"July 30","l":"https://en.wikipedia.org/wiki/Black_Souls_(video_game_series)"},{"t":"Black the Fall","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Sand Sailor Studio","u":"Square Enix","g":"Puzzle-platform","r":"July 4, 2017","l":"https://en.wikipedia.org/wiki/Black_the_Fall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8p2r.jpg","s":"Black The Fall is an atmospheric side-scrolling shooter with puzzle solving elements.\n\nAn odd and unexpected black and white dream inspired by a childhood passed behind the Iron Curtain.\n\nDiscover an industrialized long lost world living in the shadow of the totalitarian state. Everyone should be regarded as a potential enemy, an informer, a criminal. Amnesic and unaware of circumstances which brought you into this place, you begin your journey which should reveal the mystery. Moving through a peculiar world you'll have to kill in order to survive, to solve different puzzles and to learn when to be brave and when to hide.\n\nAn early-access version of the game was released on Steam in June of 2014, as well as campaign through Kickstarter in the same year."},{"t":"Blackhole","p":["PlayStation 4"],"g":"Puzzle-platformer","r":"August 8","l":"https://en.wikipedia.org/wiki/Blackhole_(video_game)"},{"t":"Blackwood Crossing","p":["PlayStation 4","Windows","Xbox One"],"d":"PaperSeven","u":"Vision Games","g":"Adventure","r":"April 4, 2017","l":"https://en.wikipedia.org/wiki/Blackwood_Crossing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ybb.jpg","s":"Blackwood Crossing is a story-driven first-person adventure game. An intriguing and emotive tale exploring the fragile relationship between orphaned siblings, Scarlett and Finn. When their paths cross with a mysterious figure, an ordinary train ride evolves into a magical story of life, love and loss."},{"t":"Blaster Master Zero","p":["Nintendo 3DS","Nintendo Switch"],"d":"Inti Creates","u":"Inti Creates","g":"Action-adventure","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Blaster_Master_Zero","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n1q.jpg","s":"A loose reboot of the original Blaster Master by Inti Creates, utilizing elements from the original game, the \"Worlds of Power\" novelization, and the original Japanese version."},{"t":"Blitzkrieg 3","p":["Windows","macOS"],"d":"Nival","u":"Nival","g":"Massively multiplayer online real-time strategy game","r":"June 2, 2017","l":"https://en.wikipedia.org/wiki/Blitzkrieg_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r87.jpg","s":"Blitzkrieg 3 is an innovative online real time strategy game, where tactical multiplayer combat, player's base developement and historical battles merge with each other to create a unique gameplay experience. Blitzkrieg 3 continues the world-renowned Blitzkrieg game series that won over 40 awards.\n\nThe main feature of the game is a unique asynchronous multiplayer mode. It allows players to fight each other, even if one of them is offline. The defencive installations, which he built, and troops, placed by him in the defence, will pass under the control of AI to ward off other players’ attacks.\n\nAnd so while you relax – the enemies break their teeth on an impregnable fortress you have made, losing their troops and bringing you valuable resources, that will help you to improve your base, or buy new army units for future victories.\n\nBlitzkrieg 3 is a first real online-RTS, long-awaited by all strategy gaming fans. Innovative PvP will give you a brand new experience of RTS playing, while historical campaigns for each of the side of the conflict will present you with classical gameplay and valuable rewards for the online mode."},{"t":"Block'hood","p":["Windows","macOS","Linux"],"d":"Plethora Project","u":"Devolver Digital","g":"City-building","r":"May 11, 2017","l":"https://en.wikipedia.org/wiki/Block'hood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vlgd8s9sdltepdelpg5h.jpg","s":"Block’hood is a neighborhood-building simulator that celebrates the diversity and experimentation of cities and the unique ecosystems within them. Budding city planners will have access to 90+ building blocks to arrange and combine and to create unique neighborhoods and discover the implications of their designs. The game will embark on a story of ecology and understanding as additional resources are always needed to unlock new blocks, configurations, and combinations to create more prosperous neighborhoods. Throughout the design process, players will need to avoid the decay of their city blocks by making sure each unit doesn’t run out of resources and become a strain on the complimentary units around them.\n\nEnvision Your Neighborhood: Consider what Blocks are necessary for your neighborhood to thrive. There are no boundaries of what you can create with an expanding library of 90+ blocks.\n\nGenerate Resources: Each Block you create has inputs and outputs and by understanding how each block is dependent on other blocks, you can create a productive network. Optimize your production and generate abundant resources for the dozens of intricate symbiotic relationships in your neighborhood\n\nAvoid Decay: If blocks don't receive the inputs they need, they will decay over time and slowly become abandoned or destroyed. Once a block is abandoned or destroyed, you will have to remove it and avoid it from making other blocks decay further. Be careful as seeking an utopian neighborhood carelessly, can lead to dystopia.\n\nUnique Modes: Neighborhood designers an enjoy Sandbox Mode and Challenge Mode with modes for Education and Research planned for educational and academic use within the classroom."},{"t":"Blossom Tales: The Sleeping King","p":["Nintendo Switch"],"r":"December 21"},{"t":"Blue Reflection","p":["PlayStation 4","PlayStation Vita"],"g":"RPG","r":"March 30","l":"https://en.wikipedia.org/wiki/Blue_Reflection"},{"t":"Bokida: Heartfelt Reunion","p":["Windows"],"r":"May 17"},{"t":"Bomber Crew","p":["Windows","macOS","Linux"],"d":"Runner Duck","u":"Curve Digital","g":"Strategy, Survival game, Simulation video game, Management sim","r":"October 19, 2017","l":"https://en.wikipedia.org/wiki/Bomber_Crew","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2331.jpg","s":"Players will find themselves deep behind enemy lines, attempting to destroy their most coveted assets, while dealing with various hazards such as flak guns, enemy radar, weather and dreaded Ace Pilots.\n\nRecruiting, training and guiding the right crew, and keeping them alive, is vital in turning the tides of war and achieving success on your bombing campaign."},{"t":"Boost Beast","p":["Nintendo Switch"],"d":"Arzest","u":"Arc System Works","g":"Match-three","r":"July 20, 2017","l":"https://en.wikipedia.org/wiki/Boost_Beast","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2337.jpg","s":"\"BOOST BEAST\" is a defense puzzle game where players defeat the invading horde of zombies by clearing blocks and summoning animals. \n \nThe controls are simple! \nMatch 3 animal blocks of the same color to summon your cute animal friends and defeat the incoming waves of zombies! \nThere are many gimmicks that stand in your way during your quest to save the world. \nThere are cages that trap your animal friends, rocks that block your path, and the grim reaper who will turn your allies into zombies. \nMake use of bombs and chain combos to pave a path to victory! \n \nJoin forces with your cute animal army and clear all 204 stages! \nLets go animal army! Until the day where peace is restored!"},{"t":"Bravely Default: Fairy's Effect","p":["iOS","Android"],"d":"Silicon Studio","u":"Square Enix","g":"Role-playing video game","l":"https://en.wikipedia.org/wiki/Bravely_Default:_Fairy's_Effect","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2vl0.jpg","s":"A mobile game set 8000 years following the events of Bravely Default and Bravely Second: End Layer in a time when the Crystal's power has waned greatly and the world is undergoing an event known as \"The Great Collapse\"."},{"t":"Brawlhalla","p":["macOS","PlayStation 4","Windows"],"d":"Blue Mammoth Games","u":"Blue Mammoth Games, Ubisoft","g":"Platform fighter","r":"October 17, 2017","l":"https://en.wikipedia.org/wiki/Brawlhalla","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6i3u.jpg","s":"Brawlhalla is a free platform fighting game with over 100 million players that supports up to 8 players online in a single match with full cross-play. Frequent updates. 50 unique characters and counting. Come fight for glory in the halls of Valhalla!"},{"t":"Brawlout","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Angry Mob Games","u":"Angry Mob Games, Merge Games","g":"Fighting","l":"https://en.wikipedia.org/wiki/Brawlout","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r7b.jpg","s":"Brawlout is the competitive platform fighter, designed for couch play, online ranked matches and competitive tournaments."},{"t":"Bridge Constructor Portal","p":["Android","iOS","Linux","macOS","Windows"],"d":"ClockStone","u":"Headup Games","g":"Simulation, puzzle","r":"December 20, 2017","l":"https://en.wikipedia.org/wiki/Bridge_Constructor_Portal","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co230j.jpg","s":"Enter the Aperture Science Enrichment Center and experience Bridge Constructor Portal – the unique merging of the classic Portal and Bridge Constructor games."},{"t":"Bubsy: The Woolies Strike Back","p":["Windows","PlayStation 4"],"g":"Platformer","r":"October 31"},{"t":"Bucket Detective","p":["Windows","macOS"],"d":"The Whale Husband","g":"Adventure","r":"February 16, 2017","l":"https://en.wikipedia.org/wiki/Bucket_Detective","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co29c9.jpg","s":"Bucket Detective – A dark comedy/horror game in which you help a cult complete a strange ritual in exchange for divine inspiration to finish writing your terrible novel. A mostly linear experience, but the choices you make determine which of the five unique endings you receive. Play multiple times to unlock the complete story. Takes around 45 minutes to complete once and another 20 minutes to get a few more endings."},{"t":"Bud Spencer & Terence Hill: Slaps and Beans","p":["Windows","Linux","macOS","Android","iOS"],"d":"Trinity Team srls","u":"Buddy Productions GmbH","g":"Beat 'em up","r":"December 15, 2017","l":"https://en.wikipedia.org/wiki/Bud_Spencer_&_Terence_Hill:_Slaps_and_Beans","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1znh.jpg","s":"Bud Spencer and Terence Hill in their first virtual adventure. Slaps And Beans is a co-operative or single player scrolling beat’ em up game with the addition of platform elements and mini-games in which you'll interpret the characters of Bud Spencer and Terence Hill"},{"t":"Bulletstorm: Full Clip Edition","p":["Windows","PlayStation 4","Xbox One"],"g":"FPS","r":"April 7"},{"t":"Bundesfighter II Turbo","p":["Browser","macOS","Windows"],"d":"Colour Colliders","u":"funk","g":"Fighting","r":"September 21, 2017","l":"https://en.wikipedia.org/wiki/Bundesfighter_II_Turbo"},{"t":"Bury Me, My Love","p":["iOS","Android"],"g":"Visual novel","r":"October 25","l":"https://en.wikipedia.org/wiki/Bury_Me,_My_Love"},{"t":"Bush Hockey League","p":["Windows","Xbox One","PlayStation 4"],"d":"V7 Entertainment","u":"V7 Entertainment","g":"Sport","r":"March 28, 2017","l":"https://en.wikipedia.org/wiki/Bush_Hockey_League","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2304.jpg","s":"Aggressive hockey is back! Experience hockey the way it was meant to be played in this old school arcade style hockey game where blood on the ice is just another day at the rink. Big moustaches, no helmets, dirty hits, bench-clearing brawls, goalie fights, and stick fights – that’s Old Time Hockey."},{"t":"Butcher","p":["PlayStation 4","Xbox One","Nintendo Switch"],"r":"May 9","l":"https://en.wikipedia.org/wiki/Butcher_(video_game)"},{"t":"Butterfly Soup","p":["Windows","macOS","Linux"],"d":"Brianna Lei","g":"Visual novel","r":"September 16, 2017","l":"https://en.wikipedia.org/wiki/Butterfly_Soup","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20sq.jpg","s":"A visual novel about gay asian girls playing baseball and falling in love."},{"t":"Bye-Bye BoxBoy!","p":["Nintendo 3DS"],"d":"HAL Laboratory","u":"Nintendo","g":"Puzzle-platform","r":"February 2, 2017","l":"https://en.wikipedia.org/wiki/Bye-Bye_BoxBoy!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co230l.jpg","s":"Wait…a box is the last defense against annihilation?!\n\nWell, fear not—Qbby is no ordinary box. Using his four startling new powers, you must solve hundreds of puzzles across 18 deadly worlds. Create boxes to climb, hover, warp, and bomb your way to salvation! Whether you're a newcomer or an old vet, thinking outside the box has never been more fun.\n\nScattered across many challenging worlds, Black Smoke and other new hazards threaten to destroy Qbby. Survive vicious winds, viscous water, and more on your mission to rescue the mysteriously cute little wonders known as Qbabies. Each Qbaby you rescue will offer a new power: hit high buttons with a Boxrocket, destroy parts of the environment with a Bombox, teleport with a Warpbox, and even levitate a Remotebox. To the victor goes the goodies: earn new in-game costumes, comics, music, and challenge worlds by beating levels or tapping amiibo. Tap a Kirby series amiibo figure to receive a costume based on the tapped character! King Dedede box, anyone?\n\nCreate boxes and unleash four new box powers to solve new puzzles\nJourney across 18 worlds of puzzling stages with unexpected new hazards\nEarn new costumes, comics, music, challenge worlds, and more!\nThe new challenge worlds are unlike anything in the series so far\nSAVE THE QBABIES!!!"},{"t":"C ya laterrrr","p":["Browser"],"d":"Dan Hett","g":"Hypertext fiction, Electronic literature, Interactive fiction","l":"https://en.wikipedia.org/wiki/C_ya_laterrrr","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobu4m.jpg","s":"c ya later is a hypertext game based on the author's experience after their brother's death in the 2017 Manchester Arena terrorist attack."},{"t":"Call of Duty: WWII","p":["Windows","PlayStation 4","Xbox One"],"g":"FPS","r":"November 3","l":"https://www.igdb.com/games/call-of-duty-wwii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rdj.jpg","s":"Call of Duty: WWII creates the definitive World War II next generation experience across three different game modes: Campaign, Multiplayer, and Co-Operative. Featuring stunning visuals, the Campaign transports players to the European theater as they engage in an all-new Call of Duty story set in iconic World War II battles. Multiplayer marks a return to original, boots-on-the ground Call of Duty gameplay. Authentic weapons and traditional run-and-gun action immerse you in a vast array of World War II-themed locations. The Co-Operative mode unleashes a new and original story in a standalone game experience full of unexpected, adrenaline-pumping moments."},{"t":"Canadian Football 2017","p":["Windows","Xbox One"],"d":"Canuck Play Inc.","u":"Canuck Play Inc.","g":"Sports","r":"July 26, 2017","l":"https://en.wikipedia.org/wiki/Canadian_Football_2017","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2a8e.jpg","s":"Fast, explosive offensive action, we have it all in our Canadian gridiron simulation title that brings to fans everything they love about how Canucks have been playing the game for more than 100 years. That means 12 players, 3 downs, 20 seconds, and no fair catch eh."},{"t":"Candleman","p":["Xbox One"],"d":"Spotlightor Interactive","u":"Zodiac Interactive, Indienova, E-Home Entertainment","g":"Puzzle-platform","r":"February 1, 2017","l":"https://en.wikipedia.org/wiki/Candleman","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22uy.jpg","s":"A 3D platformer featuring unique low-light gameplay. Players control the candle and can move, jump and light up. As the candle burns, it reveals safe passage and drips wax but also reduces its height and lifespan. Players must navigate the dark and treacherous landscape and solve puzzles in order to reach the blue light at the end of each level."},{"t":"Car Mechanic Simulator 2018","p":["Windows"],"d":"Red Dot Games","u":"PlayWay S.A.","g":"Vehicle simulation","r":"July 28, 2017","l":"https://en.wikipedia.org/wiki/Car_Mechanic_Simulator_2018","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22v4.jpg","s":"Build and expand your repair service empire in this incredibly detailed and highly realistic simulation game, where attention to car detail is astonishing. Find classic, unique cars in the new Barn Find module and Junkyard module. You can even add your self-made car in the Car Editor."},{"t":"Carcassonne – Tiles & Tactics","p":["Windows","Android"],"g":"Digital tabletop","r":"November 29","l":"https://en.wikipedia.org/wiki/Carcassonne_%E2%80%93_Tiles_%26_Tactics"},{"t":"Cars 3: Driven to Win","p":["Nintendo Switch","PlayStation 4","PlayStation 3","Xbox One","Xbox 360","Wii U"],"g":"Racing","r":"June 13"},{"t":"Cartoon Network: Battle Crashers","p":["Nintendo Switch"],"g":"Brawler","r":"October 31"},{"t":"Castle Story","p":["Linux","macOS","Windows"],"d":"Sauropod Studio","u":"Sauropod Studio","g":"Sandbox","r":"August 17, 2017","l":"https://en.wikipedia.org/wiki/Castle_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22vd.jpg","s":"Castle Story is a creative voxel-based strategy game in which you can build castles one brick at a time using an army of little creatures called Bricktrons. Design and build your own castles, expand your territory in a vast landscape and defend your Bricktrons against onslaughts of hostile creatures."},{"t":"Cat Bird","p":["iOS","Android"],"g":"Platformer","r":"August 23","l":"https://en.wikipedia.org/wiki/Cat_Bird"},{"t":"Cat Quest","p":["Nintendo Switch"],"g":"Action RPG","r":"November 10","l":"https://en.wikipedia.org/wiki/Cat_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qlq.jpg","s":"Cat Quest is a 2D open world RPG with the exploration of Skyrim, but set in the visual style of an overworld. This is a fantasy world that asks the question of how different it would be if cats lived in it instead of humans!\nGo to places like the Catpital where the Lion King rules, or experience delicacies like the catnip pie! Talk to the locals, some already on their 7th or 8th lives(what? not all cats have nine lives y'know), and go on a catventure through a world you've never seen before!"},{"t":"CATS: Crash Arena Turbo Stars","p":["Android","iOS"],"u":"Nazara Publishing","g":"Fighting","r":"April 19, 2017","l":"https://en.wikipedia.org/wiki/CATS:_Crash_Arena_Turbo_Stars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28a6.jpg","s":"From the creators of the hit games Cut the Rope and King of Thieves, comes the most ingenious and stylish battle bot constructor! Join more than 50 million players from all over the world and become the star of the Arena!"},{"t":"Cattails","p":["Windows","macOS","Linux"],"d":"Falcon Development","g":"Role-playing video game, survival game, life simulation game","r":"December 1, 2017","l":"https://en.wikipedia.org/wiki/Cattails_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1jvp.jpg","s":"Become a cat! Cattails is a unique animal simulation RPG. Hunt for food, fight invading cats, explore to gather herbs, and socialize with other cats in an expansive open world. Get married and raise a family of kittens, befriend your neighbors, and learn to live in the dangerous wilderness!"},{"t":"Causality","p":["Windows","macOS","Linux","iOS","Android"],"d":"Loju","u":"Loju","g":"Puzzle","r":"February 2, 2017","l":"https://en.wikipedia.org/wiki/Causality_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22vg.jpg","s":"Causality is a puzzle game about manipulating time, altering the sequence of events and changing the outcome of each level.\n\nSet across strange and alien landscapes, help a group of stranded astronauts find a route to safety. Travel through time, work with your past selves and solve paradoxes as you take on this uniquely challenging puzzler.\n\nEach level represents a brief but hazardous moment in time. Levels are completed by guiding each astronaut to an exit that matches their colour, within a limited time frame. When all astronauts reach an exit the level is complete."},{"t":"Caveblazers","p":["Windows"],"d":"Deadpan Games","u":"Yogscast Games","g":"Platform","r":"May 24, 2017","l":"https://en.wikipedia.org/wiki/Caveblazers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gb5.jpg","s":"Caveblazers is a challenging and brutal roguelike platformer. Journey into a mysterious cave, fighting orcs and goblins with an abundance of weapons and magical items! Make friends along the way to aid your adventure, then watch in despair as they are crushed in to a bloody pulp under a troll's fist."},{"t":"Caveman Warriors","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"r":"September 22"},{"t":"Cayne","p":["Linux","macOS","Windows"],"d":"The Brotherhood Games","u":"The Brotherhood Games","g":"Point-and-click, Adventure, Indie","r":"January 24, 2017","l":"https://www.igdb.com/games/cayne","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co225a.jpg","s":"In this grim return to the STASIS universe, expectant protagonist, Hadley, wakes up in a facility. Where is she? Why is she there? And, why do they want her baby?\n\nHelp panicked and anxious Hadley find her feet and brave stomach-churning situations to break free, by solving puzzles in this FREE horror adventure game."},{"t":"Champion Jockey Special","p":[],"l":"https://en.wikipedia.org/wiki/Champion_Jockey_Special"},{"t":"Chaos;Child","p":["PlayStation 4","PlayStation Vita"],"g":"Visual novel","r":"October 13","l":"https://en.wikipedia.org/wiki/Chaos;Child"},{"t":"Chaos;Child Love Chu Chu!!","p":["PlayStation 4","PlayStation Vita"],"d":"Mages","u":"5pb.","g":"Visual novel","r":"March 30, 2017","l":"https://en.wikipedia.org/wiki/Chaos;Child_Love_Chu_Chu!!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co69uz.jpg","s":"Chaos;Child Love Chu Chu!! is a visual novel video game. Is a spin-off from the 2014 game Chaos;Child, and part of the larger Science Adventure series. The story, which is affected by player choices, is set in Shibuya, Tokyo, and follows Takuru Miyashiro, who ignores the \"Reincarnation of the New Generation of Madness\" events, instead focusing on spending time with girls."},{"t":"Chess Ultra","p":["PlayStation 4","Windows","Xbox One","Nintendo Switch"],"d":"Ripstone","u":"Ripstone","g":"Computer chess","r":"June 21, 2017","l":"https://en.wikipedia.org/wiki/Chess_Ultra","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22vs.jpg","s":"Introducing Chess Ultra; the most breathtaking chess game ever made. Experience stunning 4K visuals, seamless online multiplayer, Grandmaster approved AI and full VR compatibility."},{"t":"Children of Zodiarcs","p":["Windows","macOS","PlayStation 4"],"r":"July 18"},{"t":"Chroma Squad","p":["PlayStation 4","Xbox One"],"g":"Tactical RPG","r":"May 19","l":"https://en.wikipedia.org/wiki/Chroma_Squad"},{"t":"ChromaGun","p":["PlayStation 4"],"g":"FPS, Puzzle","r":"August 22","l":"https://en.wikipedia.org/wiki/ChromaGun"},{"t":"Cinderella Nine","p":[],"l":"https://en.wikipedia.org/wiki/Cinderella_Nine"},{"t":"Cities: Skylines","p":["Xbox One","PlayStation 4"],"g":"City builder, CMS","r":"April 21"},{"t":"City Shrouded in Shadow","p":["PlayStation 4"],"g":"Survival","r":"October 19","l":"https://en.wikipedia.org/wiki/City_Shrouded_in_Shadow"},{"t":"Civilization VI","p":["iOS"],"g":"TBS, 4X","r":"December 21","l":"https://en.wikipedia.org/wiki/Civilization_VI"},{"t":"Cladun Returns: This is Sengoku!","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"June 6"},{"t":"Clawee","p":["Windows","iOS","Android"],"d":"Gigantic","u":"Gigantic","g":"Claw machine","l":"https://en.wikipedia.org/wiki/Clawee"},{"t":"Clone Hero","p":["Windows","macOS","Linux","Android","iOS"],"d":"CH Team","u":"CH Team","g":"Music, rhythm","l":"https://en.wikipedia.org/wiki/Clone_Hero"},{"t":"Club Penguin Island","p":["Android","iOS","macOS","Windows"],"g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Club_Penguin_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qbd.jpg","s":"Club Penguin Island is a free to play kids adventure fantasy game for mobile devices, PC, and Mac, and it is the sequel to the smash hit game Club Penguin. Calling all treasure hunters, style seekers, party penguins, foodies, social butterflies, rock stars, and explorers. You and your friends will find the adventures of a lifetime on Club Penguin Island! Explore and adventure, or show your style! Whatever you like to do, you’ll be able to do it here. Online safeguards and live moderators ensure that the game is safe for kids of all ages, all the time. What are you waiting for? You can visit the magical land of Club Penguin anytime, anywhere, on your mobile device. Now waddle on down!"},{"t":"Club Penguin Rewritten","p":["Browser"],"g":"Adventure, Arcade","l":"https://en.wikipedia.org/wiki/Club_Penguin_Rewritten","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2prr.jpg"},{"t":"Cobalt WASD","p":["Windows"],"d":"Oxeye Game Studio","u":"Mojang Studios","g":"Action","r":"November 30, 2017","l":"https://en.wikipedia.org/wiki/Cobalt_WASD","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23m9.jpg","s":"Cobalt WASD is a multiplayer bomb-defusal action platformer with grenades that stop time. Blast your way to the bomb site or repel the assault! Use teleporter guns, grappling hooks, sticky sentry turrets and quick tactical thinking to lead your team to victory! Play online or against AI!"},{"t":"Code 7: A Story-Driven Hacking Adventure Episode 1: Threading","p":["Windows","macOS","Linux"],"g":"Adventure, Typing","r":"August 11"},{"t":"Coffee Crisis","p":["Genesis / Mega Drive","Nintendo Switch","PlayStation 4","Xbox One","Windows"],"d":"Mega Cat Studios","u":"Mega Cat Studios","g":"Beat 'em up","r":"February 24, 2017","l":"https://en.wikipedia.org/wiki/Coffee_Crisis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23me.jpg","s":"Coffee Crisis is an arcade-style beat 'em up full of caffeinated carnage! This is a full scale release for the Sega Genesis/Mega Drive, packed with classic gameplay and an extra espresso shot of action!"},{"t":"Cold Waters","p":["Windows","macOS"],"d":"Killerfish Games","u":"Killerfish Games","g":"Submarine simulator","r":"July 5, 2017","l":"https://en.wikipedia.org/wiki/Cold_Waters_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xv4.jpg","s":"Spiritual Successor to the Microprose Classic “Red Storm Rising”\n\nAfter tracking a Soviet landing force bound for Iceland it is time to plan your attack. Do you silently close in to torpedo the landing ships and escape during the resulting chaos? Or strike with long-range missiles but risk counterattack from the enemy escorts? Have you detected them all, could another submarine be out there listening for you? Has the hunter become the hunted? Will you survive the Cold Waters?\n\nInspired by the 1988 classic “Red Storm Rising”, take command a nuclear submarine in a desperate attempt to prevent “mutually assured destruction” when the Cold War gets hot and WWIII begins.\n\nYou will be tasked with intercepting convoys, amphibious landings, insertion missions and battling it out with enemy warships, submarines and aircraft. Thankfully, an arsenal of wire-guided torpedoes, anti-ship and cruise missiles and the occasional SEAL team are on board to keep the Iron Curtain at bay.\n\nMajor Features:\n- Real-time naval combat\n- Over 40 classes of ships and submarines all meticulously researched\n- Dynamic Campaign where your performance matters\n- Realistic sonar model\n- Authentic Soviet combat tactics"},{"t":"Collar × Malice","p":["PlayStation Vita"],"g":"Visual novel","r":"July 28","l":"https://en.wikipedia.org/wiki/Collar_%C3%97_Malice"},{"t":"Collection of Mana","p":[],"l":"https://en.wikipedia.org/wiki/Collection_of_Mana"},{"t":"Conarium","p":["Windows"],"g":"Adventure","r":"June 6","l":"https://en.wikipedia.org/wiki/Conarium_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iwu.jpg","s":"Conarium is a chilling Lovecraftian game, which follows a gripping story involving four scientists and their endeavor to challenge what we normally consider to be the ‘absolute’ limits of nature. Inspired by H.P. Lovecraft’s novella \"At the Mountains of Madness\", but largely set after the original story.\n\nYou, as Frank Gilman, open your eyes inside a room filled with strange, pulsating noises. Patterns of lights executing a Danse Macabre on the walls is presented by a queer device on the table. Having recalled nothing other than that you’re in Upuaut, an Antarctic base located near south pole, you find the place deserted and have a distinct feeling of something being terribly wrong. Somehow knowing that your memories cannot guide you enforces a strange feeling of vulnerability, a familiar yet alien sensation of being a part of a peculiar whole... Soon you will discover that having used the device during the expedition, you have died but then returned subtly changed, speaking of strange memories and of strange places. You have lost something important or gained something sinister...\n\nExplore the antarctic base, as well as dreams and visions. Study clues, unlock secrets but avoid macabre beings at all cost."},{"t":"Constructor HD","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"RTS, CMS","r":"May 26","l":"https://en.wikipedia.org/wiki/Constructor_(video_game)#Ports"},{"t":"Cook, Serve, Delicious! 2","p":["Windows","macOS","Linux"],"d":"Vertigo Gaming","u":"Vertigo Gaming","g":"Simulation","r":"September 13, 2017","l":"https://en.wikipedia.org/wiki/Cook,_Serve,_Delicious!_2"},{"t":"Cosmic Express","p":["Android","iOS","Linux","macOS","Windows"],"g":"Puzzle","r":"March 16, 2017","l":"https://en.wikipedia.org/wiki/Cosmic_Express","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1o36.jpg","s":"All aboard the Cosmic Express, a delightfully brain-melting game where the puzzles are out of this world! Your job is to lay down the train tracks across a series of tiny space stations. Each alien has a home of their own, and there’s only room for one extraterrestrial at a time in the passenger car. It's cute, harder than it looks, and guaranteed to give you hours of challenging fun across hundreds of levels."},{"t":"Cosmic Star Heroine","p":["Windows","PlayStation 4"],"g":"RPG","r":"April 11","l":"https://en.wikipedia.org/wiki/Cosmic_Star_Heroine"},{"t":"Crash Bandicoot","p":["PlayStation 4"],"d":"Vicarious Visions","u":"Activision","g":"Platform","r":"June 30, 2017","l":"https://www.igdb.com/games/crash-bandicoot--2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc2ck.jpg","s":"A remake of Crash Bandicoot found in the Crash Bandicoot N. Sane Trilogy collection. Not to be confused with the actual bundle."},{"t":"Crash Bandicoot 2: Cortex Strikes Back","p":["PlayStation 4"],"d":"Vicarious Visions","u":"Activision","g":"Platform","r":"June 30, 2017","l":"https://www.igdb.com/games/crash-bandicoot-2-cortex-strikes-back--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8xg.jpg","s":"A remake of Crash Bandicoot 2: Cortex Strikes Back found in the Crash Bandicoot N. Sane Trilogy collection. Not to be confused with the actual bundle."},{"t":"Crash Bandicoot N. Sane Trilogy","p":["PlayStation 4"],"g":"Platformer","r":"June 30","l":"https://en.wikipedia.org/wiki/Crash_Bandicoot_N._Sane_Trilogy"},{"t":"Crash Bandicoot: Warped","p":["PlayStation 4"],"d":"Vicarious Visions","u":"Activision","g":"Platform","r":"June 30, 2017","l":"https://www.igdb.com/games/crash-bandicoot-warped--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8xi.jpg","s":"A remake of Crash Bandicoot: Warped found in the Crash Bandicoot N. Sane Trilogy collection. Not to be confused with the actual bundle."},{"t":"Crash Club","p":["iOS","Android"],"g":"MMO","r":"May 10","l":"https://en.wikipedia.org/wiki/Crash_Club"},{"t":"Crawl","p":["Windows","macOS","Linux","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Powerhoof","u":"Powerhoof","g":"Beat 'em up","r":"April 11, 2017","l":"https://en.wikipedia.org/wiki/Crawl_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1lrj.jpg","s":"Crawl is the local multiplayer dungeon crawler where your friends control the monsters! It’s bullet-hell beat-em-up meets old-school RPG, in an arcadey party-game for up to 4 players. One player is the hero, exploring a randomly generated dungeon full of traps and monsters - all controlled by the other players. If you slay the hero you take their place and it’s your turn to crawl! Then it's a race to gain enough XP and loot to reach the final battle, where it's all on one as the other players collectively control the hulking final boss!"},{"t":"Creativerse","p":["Windows","macOS"],"g":"Survival, Sandbox","r":"May 8"},{"t":"Creeping Terror","p":["Nintendo 3DS"],"r":"October 31"},{"t":"Criminal Girls: Invite Only","p":["Windows"],"g":"RPG","r":"January 11"},{"t":"Crossout","p":["Windows","Xbox One","PlayStation 4","iOS"],"d":"Targem Games","u":"Gaijin Entertainment","g":"Vehicular combat","r":"May 30, 2017","l":"https://en.wikipedia.org/wiki/Crossout","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wid.jpg","s":"Crossout - the postapocalyptic MMO action game where you can create a unique design for an armoured vehicle from dozens of parts and then drive it into multiplayer battles raging on land and in the skies alike."},{"t":"Cryptark","p":["Windows","PlayStation 4"],"d":"Alientrap, Sickhead Games","u":"Alientrap","g":"Roguelike","r":"June 20, 2017","l":"https://en.wikipedia.org/wiki/Cryptark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23nb.jpg","s":"\"Cryptark is a 2D roguelike shooter that challenges players with boarding and neutralizing procedurally generated alien starships to earn income for their Privateering enterprise. Purchase improved equipment and weapons to tackle more dangerous targets, but be cautious as failure will result in a loss of investment and profit. The decaying alien arks will defend themselves from intruders with a wide arsenal of cyborg monstrosities, robotics, and security systems, all obstacles that must be surpassed to achieve victory, the destruction of the ship’s central System Core.\n\n- Complex, procedurally generated alien space-hulks to board and defeat.\n- Challenging, re-playable campaign that tests your strategy and tactics.\n- Over 60 weapons and items, including frag-cannons, tractor-beams, flamethrowers and nukes.\n- High-score leader boards to rank your skills.\n- Fully lip-synced voice acting brings your fellow shipmates to life.\n- Blood-pumping soundtrack perfect for intense firefights.\""},{"t":"CryptoKitties","p":[],"d":"Dapper Labs","u":"Dapper Labs","g":"Virtual pet","r":"November 2017","l":"https://en.wikipedia.org/wiki/CryptoKitties"},{"t":"Culdcept Revolt","p":["Nintendo 3DS"],"g":"TBS","r":"October 3","l":"https://en.wikipedia.org/wiki/Culdcept_Revolt"},{"t":"Cuphead","p":["Windows","Xbox One"],"g":"Run and gun","r":"September 29","l":"https://en.wikipedia.org/wiki/Cuphead","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62ao.jpg","s":"Cuphead is a run-and-gun action game focused primarily on boss battles. Its visual style is modeled after 1930s cartoons, using traditional hand-drawn cel animation, watercolor backgrounds, and original jazz recordings. Players control Cuphead or Mugman in single-player or local co-op, traversing themed worlds, acquiring new weapons, and unlocking super moves. The game includes both boss encounters and side-scrolling platforming stages."},{"t":"Cyberdimension Neptunia: 4 Goddesses Online","p":["PlayStation 4"],"g":"Action RPG, Puzzle","r":"October 10"},{"t":"Damascus Gear: Operation Tokyo HD Edition","p":["PlayStation 4"],"r":"May 31"},{"t":"Dancing Ballz","p":["Android","iOS"],"d":"Amanotes Pte. Ltd.","u":"Amanotes Pte. Ltd.","g":"Rhythm game, music","r":"June 15, 2017","l":"https://en.wikipedia.org/wiki/Dancing_Ballz"},{"t":"Danganronpa 1•2 Reload","p":["PlayStation 4"],"g":"Adventure, Visual novel","r":"March 14"},{"t":"Danganronpa Another Episode: Ultra Despair Girls","p":["Windows","PlayStation 4"],"g":"Action-adventure","r":"June 27"},{"t":"Danganronpa V3: Killing Harmony","p":["PlayStation 4","PlayStation Vita","Windows"],"g":"Adventure, Visual novel","r":"January 12","l":"https://www.igdb.com/games/danganronpa-v3-killing-harmony--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocnyc.jpg","s":"Welcome to a new world of Danganronpa, and prepare yourself for the biggest, most exhilarating episode yet. Set in a “psycho-cool” environment, a new cast of 16 characters find themselves kidnapped and imprisoned in a school. Inside, some will kill, some will die, and some will be punished. Reimagine what you thought high-stakes, fast-paced investigation was as you investigate twisted murder cases and condemn your new friends to death."},{"t":"Danger Zone","p":["Windows","PlayStation 4"],"r":"May 30"},{"t":"Dark and Light","p":["Windows"],"d":"Snail Games","u":"Snail Games","g":"Role-playing (RPG), Simulator, Adventure","r":"July 20, 2017","l":"https://en.wikipedia.org/wiki/Dark_and_Light_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2466.jpg","s":"Dark and Light is a vast sandbox RPG set in a world dominated by powerful elemental forces. Find your way in a meticulously crafted world, featuring breathtaking landscapes, a wide variety of mythical creatures, and limitless possibility to craft, build, and unlock over 100 abilities."},{"t":"Dark Rose Valkyrie","p":["PlayStation 4"],"g":"RPG","r":"June 6","l":"https://en.wikipedia.org/wiki/Dark_Rose_Valkyrie"},{"t":"Dark Souls III: The Ringed City","p":["Windows","PlayStation 4","Xbox One"],"d":"FromSoftware","u":"Bandai Namco Entertainment","g":"Action role-playing","r":"March 27, 2017","l":"https://en.wikipedia.org/wiki/Dark_Souls_III:_The_Ringed_City"},{"t":"Dark Witch Music Episode: Rudymical","p":["Nintendo Switch"],"d":"Inside System, Esquarda","u":"Flyhigh Works","g":"Rhythm","r":"May 11, 2017","l":"https://en.wikipedia.org/wiki/Dark_Witch_Music_Episode:_Rudymical","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co93pc.jpg","s":"The popular minigame \"Rudymical\" from Dark Witch Story 2 has been renewed and now can be played on your mobile devices!"},{"t":"Darksiders: Warmastered Edition","p":["Wii U"],"g":"Hack and slash, Action-adventure","r":"May 23","l":"https://en.wikipedia.org/wiki/Darksiders"},{"t":"Darkwood","p":["Linux","macOS","Windows"],"d":"Acid Wizard Studio","u":"Acid Wizard Studio, Crunching Koalas, Hooded Horse","g":"Survival horror","r":"August 17, 2017","l":"https://en.wikipedia.org/wiki/Darkwood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24nh.jpg","s":"Darkwood is a unforgiving survival horror with a procedurally generated, open world. By blending RPG, roguelike and adventure elements together with a challenging difficulty, Darkwood aims to please players craving for a deep and rewarding experience.\n\nThe fear of unknown is powerful. Your senses will be deceived by Darkwood's surreal terrors. No answer will be given to you for free, yet somewhere in the woods lies the truth, an explanation to what has happened in this godforsaken place.\n\nBy day, explore the randomly generated woods, scavenge for materials and weapons, discover secrets, solve mysteries and talk, trade with or kill the various inhabitants of Darkwood. By night, return to your hideout, barricade, set up traps and hide or defend yourself from the horrors that lurk in the dark."},{"t":"Day of Infamy","p":["Windows","macOS","Linux"],"d":"New World Interactive","u":"New World Interactive","g":"First-person shooter, action, strategy","r":"March 23, 2017","l":"https://en.wikipedia.org/wiki/Day_of_Infamy_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsve.jpg","s":"The creators of Insurgency present the next installment of their successful FPS platform with Day of Infamy. Featuring tactical close-quarters WWII engagements across a wide range of multiplayer and coop scenarios, Day of Infamy is a highly intense teamwork-rewarding experience."},{"t":"Days of War","p":["Windows","PlayStation 4","Xbox One"],"d":"Driven Arts","u":"Driven Arts","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Days_of_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24nq.jpg","s":"Days of War is a fast paced WW2 shooter with 32 player infantry combat in a high fidelity environment. Days of War makes a return to the classic WW2 shooter with the latest industry technology."},{"t":"De Blob","p":["Windows"],"g":"Puzzle-platformer","r":"April 27","l":"https://en.wikipedia.org/wiki/De_Blob"},{"t":"De Mambo","p":["Nintendo Switch","Linux","macOS","Windows","PlayStation 4"],"d":"The Dangerous Kitchen","u":"Chorus Worldwide","g":"Platform, Fighter","r":"June 29, 2017","l":"https://en.wikipedia.org/wiki/De_Mambo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gsp.jpg","s":"De Mambo is The Dangerous Kitchen's first game that lets players take control of up to four characters locked in infinite mambo!\n\nHelp them escape this horrible—and somewhat provocative—despair! Knock your opponent off the screen… and use your measly one button to attack with three levels of charge!\n\nBreak the level however you decide (thanks to some flimsy architecture) to make your game marginally different each time you play."},{"t":"Dead by Daylight","p":["PlayStation 4","Xbox One"],"g":"Survival horror","r":"June 20","l":"https://en.wikipedia.org/wiki/Dead_by_Daylight"},{"t":"Dead or Alive 5 Infinite","p":[],"l":"https://en.wikipedia.org/wiki/Dead_or_Alive_5_Infinite"},{"t":"Dead Rising 4: Frank's Big Package","p":["PlayStation 4"],"g":"Action-adventure","r":"December 5","l":"https://en.wikipedia.org/wiki/Dead_Rising_4"},{"t":"Death Horizon","p":["Gear VR"],"d":"Dream Dev Studio VR","g":"Shooter game","r":"September 21, 2017","l":"https://en.wikipedia.org/wiki/Death_Horizon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co271a.jpg","s":"Death Horizon is a realistic VR shooter developed specially for mobile VR devices. \n \nIn the secret Horizon laboratory, a horrific virus has broken free, and now all the employees have turned to zombies. Only the game’s protagonist can prevent the downfall of humanity. Your task is to make your way to the station’s reactor and disable the distribution of the virus. To do that, you’ll need to kill all the enemies in your path and complete the tasks. Come back alive too, if you can. \n \nDeveloped specially for the Samsung Gear VR and Google Daydream mobile VR platforms"},{"t":"Death Squared","p":["Windows","macOS","Nintendo Switch","Xbox One","PlayStation 4"],"d":"SMG Studio","u":"SMG Studio","g":"Puzzle","r":"March 14, 2017","l":"https://en.wikipedia.org/wiki/Death_Squared","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qrjrknu797scexyv0c0u.jpg","s":"Death Squared is a co-op puzzle game about cooperation, communication, and robot explosions."},{"t":"Deemo","p":["Nintendo Switch"],"g":"Rhythm","r":"September 28","l":"https://en.wikipedia.org/wiki/Deemo"},{"t":"Deemo: The Last Recital","p":["PlayStation Vita"],"g":"Rhythm","r":"May 16"},{"t":"Deep Space Waifu","p":["Windows"],"g":"Action","r":"May 30"},{"t":"Deformers","p":["PlayStation 4","Windows","Xbox One"],"d":"Ready at Dawn","u":"GameTrust","g":"Brawler","r":"April 21, 2017","l":"https://en.wikipedia.org/wiki/Deformers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7vod.jpg"},{"t":"Defunct","p":["PlayStation 4","Xbox One"],"g":"Adventure","r":"December 20","l":"https://en.wikipedia.org/wiki/Defunct_(video_game)"},{"t":"Demon Gaze II","p":["PlayStation 4","PlayStation Vita"],"g":"RPG, Dungeon crawl","r":"November 14","l":"https://en.wikipedia.org/wiki/Demon_Gaze_II"},{"t":"Demon's Crystals","p":["PlayStation 4","Xbox One"],"r":"May 12"},{"t":"Derelict Fleet","p":["Windows","PlayStation 4"],"r":"July 11"},{"t":"Desperate Housewives: The Game","p":["iOS","Android"],"d":"megazebra","u":"MegaZebra","g":"Casual, role-playing game","r":"June 2017","l":"https://en.wikipedia.org/wiki/Desperate_Housewives:_The_Game_(2017_video_game)"},{"t":"Destiny 2","p":["PlayStation 4","Xbox One","Windows"],"g":"FPS","r":"September 6","l":"https://en.wikipedia.org/wiki/Destiny_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc89g.jpg","s":"Dive into the world of Destiny 2 to explore the mysteries of the solar system and experience responsive first-person shooter combat. Unlock powerful elemental abilities and collect unique gear to customize your Guardian's look and playstyle. Enjoy Destiny 2’s cinematic story, challenging co-op missions, and a variety of PvP modes alone or with friends. Download for free today and write your legend in the stars."},{"t":"Detention","p":["PlayStation 4","Windows","macOS","Linux","Nintendo Switch","Android"],"d":"Red Candle Games","u":"Red Candle Games","g":"Point-and-click adventure","l":"https://en.wikipedia.org/wiki/Detention_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24yo.jpg","s":"Detention is a atmospheric horror game set in 1960s Taiwan under martial law. Incorporated religious elements based in Taiwanese/Chinese culture and mythology, the game provided players with unique graphics and gaming experience."},{"t":"Dia Horizon","p":["iOS","Android"],"g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Dia_Horizon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co316n.jpg","s":"The game follows the player as a hero leading a group of adventurers to battle monsters in a dungeon. The player forms a team of four characters, purchasing different adventurers with different stats and prices. During battle, the player can either manually control the characters' attacks or let the game control it."},{"t":"Diablo III: Rise of the Necromancer","p":["macOS","PlayStation 4","Windows","Xbox One"],"d":"Blizzard Entertainment","u":"Blizzard Entertainment","g":"Action role-playing, hack and slash","r":"June 27, 2017","l":"https://en.wikipedia.org/wiki/Diablo_III:_Rise_of_the_Necromancer"},{"t":"Dies irae: Amantes amentes","p":["Windows"],"g":"Visual novel","r":"June 2","l":"https://en.wikipedia.org/wiki/Dies_irae_(visual_novel)"},{"t":"Digimon World: Next Order","p":["PlayStation 4"],"g":"RPG","r":"January 31"},{"t":"Diluvion","p":["Windows","macOS"],"d":"Arachnid Games","u":"Gambitious Digital Entertainment","g":"Action-adventure, role-playing","r":"February 2, 2017","l":"https://en.wikipedia.org/wiki/Diluvion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k36.jpg","s":"Diluvion is a 3D deep sea, Jules Verne inspired, exploration game with RPG elements and thrilling submarine combat. As the Captain of your own vessel, you must grow and manage your crew as you search for the secrets of the past in a hauntingly beautiful flooded world.\n\nForced into the deep oceans by a Great Flood that occurred countless centuries ago, humanity now lives trapped under a thick layer of unbreakable ice and their survival hangs by a tenuous thread. However, their penchant for perseverance is strong, and a new civilization has emerged with distinct kingdoms, religions and cultures. By a twist of fate you, an aspiring submarine captain, have been given the honor of commanding your first sub. With a brave crew at your command, you now venture into the unknown on a quest to discover humanity’s greatest secret.\n\nExplore the dangers of the depths in this beautifully realized flooded world, and unearth untold riches and glory. Discover the remnants of civilization in numerous unique towns and learn their local lore, trade stories and treasure, and hire crew new members.\n\nContinuously improve each of the game’s 9 unique pilotable submarines using a deep upgrade system, and gain access to new areas and loot. Discover numerous types of cannons and torpedoes to help you overcome the dangers of the deep, and assemble your own unique crew to brave it alongside you. Whether you wish to play as a silent hunter or a guns blazing dreadnought, arrange your crew members and weapons to fit your playstyle."},{"t":"Dino Frontier","p":["PlayStation VR"],"r":"August 1"},{"t":"Dirt 4","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"June 6","l":"https://en.wikipedia.org/wiki/Dirt_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1srr.jpg","s":"Dirt 4 is all about embracing danger. It’s about the thrill, exhilaration and adrenaline that is absolutely vital to off-road racing. It’s about loving the feeling of pushing flat out next to a sheer cliff drop, going for the gap that’s too small and seeing how much air you can get. Be Fearless."},{"t":"Disc Jam","p":["PlayStation 4","Windows"],"d":"High Horse Entertainment","u":"High Horse Entertainment","g":"Sports","r":"March 7, 2017","l":"https://en.wikipedia.org/wiki/Disc_Jam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24zq.jpg","s":"A fast-paced action-sports game that pits 2-4 players against each other in a unique combination of air hockey and tennis. Players scramble to retrieve and throw a glowing disc while unleashing devastating abilities and defending variable-point end zones. An exciting blend of strategy and skill, this arcade-inspired title boasts a zany roster of characters to compete with friends both on the couch and online."},{"t":"Disgaea 2","p":["Windows"],"g":"Tactical RPG","r":"January 30","l":"https://en.wikipedia.org/wiki/Disgaea_2"},{"t":"Disgaea 5 Complete","p":["Nintendo Switch"],"g":"Tactical RPG","r":"May 23","l":"https://en.wikipedia.org/wiki/Disgaea_5"},{"t":"Dishonored: Death of the Outsider","p":["Windows","PlayStation 4","Xbox One"],"g":"Action-adventure, Stealth","r":"September 15","l":"https://www.igdb.com/games/dishonored-death-of-the-outsider","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5pd2.jpg","s":"Dishonored: Death of the Outsider is a stand-alone expansion pack and a sequel to Dishonored 2. The game features all the series' hallmarks, including brutal combat systems, unique level design and immersive story-telling that responds to your every choice. With compelling characters and exhilarating action, Death of the Outsider is the perfect entry point for those new to the Dishonored series, while delivering a significant expansion of the world and gameplay for long-time fans."},{"t":"Distrust","p":["Windows"],"d":"Cheerdealers","u":"Alawar","g":"Strategy, survival","r":"August 23, 2017","l":"https://en.wikipedia.org/wiki/Distrust_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gdq.jpg","s":"DISTRUST is an isometric survival adventure with procedural generation on an Arctic research station lost in the endless dark of a polar night. A story-rich fiction with multiple endings that suits both singleplayer fans and co-op enthusiasts."},{"t":"Divide","p":["PlayStation 4"],"r":"January 31"},{"t":"Divided We Fall","p":["Windows","macOS","Linux"],"g":"RTS","r":"October 2","l":"https://en.wikipedia.org/wiki/Divided_We_Fall_(video_game)"},{"t":"Divinity: Original Sin II","p":["Windows"],"d":"Larian Studios","u":"Larian Studios","g":"RPG","r":"September 14, 2017","l":"https://store.steampowered.com/app/435150","i":"images/steam-435150.jpg","s":"The critically acclaimed RPG that raised the bar, from the creators of Baldur's Gate 3. Gather your party. Master deep, tactical combat. Venture as a party of up to four - but know that only one of you will have the chance to become a God."},{"t":"Doki Doki Literature Club!","p":["Windows","macOS"],"g":"Visual novel","r":"September 22","l":"https://en.wikipedia.org/wiki/Doki_Doki_Literature_Club!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6p5e.jpg","s":"The Literature Club is full of cute girls! Will you write the way into their heart? This game is not suitable for children or those who are easily disturbed."},{"t":"Domina","p":["Windows"],"d":"Bignic","g":"Simulation","r":"April 3, 2017","l":"https://en.wikipedia.org/wiki/Domina_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w4a.jpg","s":"Domina is a Gladiator management game.\nThe graphics are definitely stylish (a type of pixel art very popular at the time) and the music mixes modern rhythms with ancient sounds in an exceptional way.\n\nThe gaming system is based on limited time and resources. Each day runs rather quickly and the player can play only a few activities. Training your fighters is essential, as is winning in the arena and obtaining prizes and resources that will allow us to better equip our gladiators and obtain favors from the authorities.\n\nThe fights are always risky because no result is perfectly guaranteed and losing the best fighters is a tragedy from which you recover only with great difficulty, especially when you are defeated in fights between teams of gladiators. Over time their ludus will grow in celebrity (in case of success) and we can compete with increasingly complex challenges, including participation in tournaments in various parts of Italy of increasing difficulty against opponents.\n\nFinally, there are the touches of class as gladiators who get drunk in the arena (if you insist on rewarding them with wine during training), weapons launched by the public to help a fighter, severed limbs and the ability to post on facebook and twitter replays duels.\n\nBut Domina also impresses with a different aspect from that of mere gameplay or production values. Domina is in fact a title designed to be played in a stream and offers several moments of meaningful interaction with the spectators. First of all, once the Twitch mode is activated, the game collects the names of the stream viewers and uses them for the various gladiators that the streamer manages during the game; both the first batch of fighters and all subsequent new arrivals will be identifiable as the stream viewers.\n\nAlready this, by itself, allows Domina to acquire a new level of interaction with the public and, therefore, of entertainment. The viewers follow the story of their character, require training, new equipment and invoke the use in the arena. As has already happened in an unstructured way in games like X-Com (the streamer created the characters in the image and request of the viewers), so it happens in a structured and automatic way in Domina.\n\nBut that is not all. In Domina the viewers vote in the various multi-choice events proposed by the game using a mechanism similar to other 'stream based' games. And then you enter the arena and the fun is multiplied because not only spectators can participate by launching incitements and insults (thus determining other game statistics), but, in case a gladiator surrenders without being killed, they can vote for death or life through the classic thumb up / down."},{"t":"Dominions 5: Warriors of the Faith","p":["Windows","Linux","macOS"],"d":"Illwinter Game Design","u":"Illwinter Game Design","g":"Strategy","r":"November 27, 2017","l":"https://en.wikipedia.org/wiki/Dominions_5:_Warriors_of_the_Faith","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pxw.jpg","s":"A turn based strategy game."},{"t":"Don Bradman Cricket 17","p":["Windows"],"g":"Sports (cricket)","r":"January 22","l":"https://en.wikipedia.org/wiki/Don_Bradman_Cricket_17"},{"t":"Don't Knock Twice","p":["HTC Vive","Meta Quest"],"g":"Survival horror","r":"May 30","l":"https://en.wikipedia.org/wiki/Don%27t_Knock_Twice_(video_game)"},{"t":"Doom","p":["Nintendo Switch"],"g":"FPS","r":"November 10","l":"https://en.wikipedia.org/wiki/Doom_(2016_video_game)"},{"t":"Double Dragon IV","p":["Windows","PlayStation 4"],"g":"Brawler","r":"January 30","l":"https://en.wikipedia.org/wiki/Double_Dragon_IV"},{"t":"Dragon Ball Xenoverse 2","p":["Nintendo Switch"],"g":"Fighting, RPG","r":"September 22","l":"https://en.wikipedia.org/wiki/Dragon_Ball_Xenoverse_2"},{"t":"Dragon Fang Z: The Rose & Dungeon of Time","p":["Nintendo Switch"],"r":"December 20"},{"t":"Dragon Quest Heroes II","p":["Windows","PlayStation 4"],"g":"Action RPG, Hack and slash","r":"April 25","l":"https://en.wikipedia.org/wiki/Dragon_Quest_Heroes_II"},{"t":"Dragon Quest VIII: Journey of the Cursed King","p":["Nintendo 3DS"],"g":"RPG","r":"January 20"},{"t":"Dragon Quest XI","p":["Nintendo 3DS","PlayStation 4"],"g":"RPG","r":"July 29","l":"https://en.wikipedia.org/wiki/Dragon_Quest_XI"},{"t":"Dragon Quest XI: Echoes of an Elusive Age","p":["PlayStation 4"],"d":"Square Enix Business Division 6","u":"Square Enix","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"July 29, 2017","l":"https://www.igdb.com/games/dragon-quest-xi-echoes-of-an-elusive-age","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1x9d.jpg","s":"Dragon Quest XI continues the gameplay of previous games in the series, in which players explore worlds and fight against various monsters, including the ability to explore high areas. Before entering battle, players can also toggle between the 3D and 2D graphical styles. The game features the series' traditional turn-based battle system."},{"t":"Dragon's Dogma: Dark Arisen","p":["PlayStation 4","Xbox One"],"g":"Action RPG, Hack and slash","r":"October 5"},{"t":"Drawn to Death","p":["PlayStation 4"],"g":"TPS","r":"April 4","l":"https://en.wikipedia.org/wiki/Drawn_to_Death"},{"t":"Dreadnought","p":["PlayStation 4"],"g":"Vehicular combat (spaceship)","r":"December 7","l":"https://en.wikipedia.org/wiki/Dreadnought_(video_game)"},{"t":"Dream Daddy: A Dad Dating Simulator","p":["Windows","macOS","Linux"],"d":"Game Grumps","u":"Game Grumps","g":"Visual novel","r":"July 20, 2017","l":"https://en.wikipedia.org/wiki/Dream_Daddy:_A_Dad_Dating_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8771.jpg","s":"Dream Daddy: A Dad Dating Simulator is a game where you play as a Dad and your goal is to meet and romance other hot Dads. Are you ready? Hi ready, I'm Dad."},{"t":"Dreamfall Chapters: The Longest Journey","p":["PlayStation 4","Xbox One"],"g":"Adventure","r":"May 5"},{"t":"Drive Girls","p":["PlayStation Vita"],"r":"May 26"},{"t":"DropMix","p":["iOS","Android"],"d":"Harmonix","u":"Hasbro","g":"Rhythm, card game, music video game","r":"September 20, 2017","l":"https://en.wikipedia.org/wiki/DropMix","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wqq.jpg","s":"DropMix is a music mixing game developed by Harmonix and published by Hasbro. The game uses a mix of physical cards with chips embedded with near field communication, a specialized electronic game board with NFC and Bluetooth capabilities, and a companion application for mobile devices (iOS or Android) that communicates with the board via Bluetooth. By playing a card, representing a specific song, atop a proper board space, the board will detect its NFC code and relay that to the app, which will play a sample from that song, such as a drum loop or a vocal section. With multiple cards on the board, the app will manage how all the current songs are mixed as played through the app, creating a mashup. The game has several game modes for single and multi-player play, and additional cards, featuring more song samples, can be purchased as booster packs."},{"t":"Drunk or Dead","p":["SteamVR","Oculus Rift"],"d":"4 I Lab","u":"4 I Lab","g":"First-person shooter","r":"January 10, 2017","l":"https://en.wikipedia.org/wiki/Drunk_or_Dead","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2azb.jpg","s":"Don't worry, shoot zombie! You are caught by zombie apocalypse caused by a virus, which affects only sober people. To stay alive, you have to drink and shoot zombies."},{"t":"Dude Simulator","p":["Windows"],"d":"Kiddy","u":"Kiddy","g":"Simulator, Adventure, Indie","r":"July 13, 2017","l":"https://www.igdb.com/games/dude-simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa93t.jpg","s":"Dude Simulator is an open world sandbox game. This is a life simulator. The main objective is to enjoy what you are doing."},{"t":"Dujanah","p":["Windows","macOS","Linux"],"d":"Jack King-Spooner","g":"Art game","r":"September 19, 2017","l":"https://en.wikipedia.org/wiki/Dujanah","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2cuv.jpg","s":"An experimental/philosophical claymation adventure game in which the husband and child of a woman named Dujanah go missing and she sets out to find them in a semi-fictional Middle Eastern setting."},{"t":"Dungeons 3","p":["Linux","macOS","Windows","PlayStation 4","Xbox One"],"d":"Realmforge Studios","u":"Kalypso Media","g":"Strategy, simulation","r":"October 13, 2017","l":"https://en.wikipedia.org/wiki/Dungeons_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fm9.jpg","s":"Unleash your dark side by creating a unique underground dungeon from a huge array of rooms, traps and structures. Raise the most terrifying army the world has ever seen, by choosing from despicable creatures such as orcs, succubae, zombies and much, much more. Then, once you have built your forces, emerge from the darkness and guide your army to the light of the overworld, where you will corrupt the land and dispatch anything even vaguely heroic, cute or unicorn-shaped. And in a first for the Dungeons series, experience randomly generated levels, so that no two sessions are alike – never-ending fun for any evil conqueror!"},{"t":"DWVR","p":["PlayStation VR"],"r":"September 26"},{"t":"Dynasty Warriors: Godseekers","p":["PlayStation 4","PlayStation Vita"],"g":"RPG","r":"January 31"},{"t":"Earth Atlantis","p":["Nintendo Switch","Windows","macOS","Linux"],"d":"Pixel Perfex","u":"Headup Games","g":"Simulation, strategy","r":"October 5, 2017","l":"https://en.wikipedia.org/wiki/Earth_Atlantis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24gx.jpg","s":"A side-scrolling Metroidvania-style underwater shooter focused on hunting boss monsters in post-apocalyptic ocean."},{"t":"Earth Defense Force 4.1: Wing Diver The Shooter","p":["PlayStation 4"],"g":"TPS","r":"November 22","l":"https://en.wikipedia.org/wiki/Earth_Defense_Force_4.1"},{"t":"Earth Defense Force 5","p":["PlayStation 4"],"g":"TPS","r":"December 7","l":"https://en.wikipedia.org/wiki/Earth_Defense_Force_5"},{"t":"Earthlock: Festival of Magic","p":["Wii U"],"g":"RPG","r":"September 14"},{"t":"Echo","p":["Windows","PlayStation 4"],"g":"Action, Stealth","r":"September 19","l":"https://en.wikipedia.org/wiki/Echo_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24h2.jpg","s":"After a century in stasis the girl En arrives at her destination: A Palace out of legend, a marvel of the old civilization eons gone, still awaiting its first human occupants. Out here, using forgotten technologies, she hopes to bring back a life that shouldn’t have been lost.\n\nIn Echo everything has consequence: As you try to wield its magical technologies it becomes apparent that the Palace has a will of its own… It studies everything you do, everything you are – to use it against you."},{"t":"ELEX","p":["Windows","PlayStation 4","Xbox One"],"g":"Action RPG","r":"October 17","l":"https://en.wikipedia.org/wiki/ELEX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qv7.jpg","s":"An action, role-playing open world game for PC and Consoles, Elex was developed by Piranha Bytes, creators of the award winning Gothic series and is set in a brand new, post-apocalyptic, Science-Fantasy universe where magic meets mechs.\n\n\"Advanced in technology, civilized and with a population of billions, Magalan was a planet looking to the future. Then the meteor hit.\n\nThose who survived are now trapped in a battle to survive, a struggle to decide the fate of a planet. At the center of this fight is the element “Elex”. A precious, limited resource that arrived with the meteor, Elex can power machines, open the door to magic, or re-sculpt life into new, different forms.\n\nBut which of these choices should be the future of Magalan? Can technology or magic save this world? Or will this new power destroy all those left alive amongst the ruins?\""},{"t":"Elliot Quest","p":["PlayStation 4","Nintendo 3DS","Xbox One"],"g":"Platformer, Adventure, Metroidvania","r":"May 9","l":"https://en.wikipedia.org/wiki/Elliot_Quest"},{"t":"Embers of Mirrim","p":["Windows","PlayStation 4"],"r":"May 23"},{"t":"Emily Is Away Too","p":["Windows","macOS","Linux"],"g":"Visual novel, Romance","r":"May 26, 2017","l":"https://en.wikipedia.org/wiki/Emily_Is_Away_Too","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24r9.jpg","s":"Emily is Away Too is the spiritual successor to the critically acclaimed original. Message both Emily and Evelyn as you determine the outcome of your senior year. Extend the story past the chat window with youtube links, facebook profiles and file transfers. And most importantly, change your text color to lime green so everyone knows you're the coolest kid in school."},{"t":"Endless Space 2","p":["macOS","Windows"],"d":"Amplitude Studios","u":"Sega","g":"Turn-based strategy, 4X","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Endless_Space_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2svr.jpg","s":"In Endless Space you play the role of the leader of one of the many intelligent beings of a galaxy at the beginning of the space age. Very quickly, you discover the remnants of an older civilization. That civilization called themselves the Endless, among their ruins, a matter called Dust with amazing proprieties is found. It shapes into whatever its user thinks of, it gives a reality to dreams… dreams that lead to the extinction of the Endless.\n\nSince then that matter became the most precious matter of the universe, and therefore the universal currency… but in front of the power of the Dust it is hard, even for the purest beings, not to fall under its charm…\n\nWe want the players to live an experience that goes beyond just strategy. You will live your own story of space conquest, with your own randomly generated galaxy full of civilizations, lifeforms, technologies and unknown worlds for you to conquer."},{"t":"Energy Balance","p":["PlayStation Vita"],"r":"July 12"},{"t":"Engare","p":["macOS","Windows"],"d":"Mahdi Bahrami","u":"Mahdi Bahrami","g":"Puzzle","r":"October 23, 2017","l":"https://en.wikipedia.org/wiki/Engare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2b3s.jpg","s":"Engare is a game about movement and geometry. Part puzzle game, part drawing tool, Engare is a all about your geometric imagination. It’s a meditation on the dynamics of simple machines and the beauty buried deep within repeating motion."},{"t":"Enter the Gungeon","p":["Nintendo Switch"],"g":"Bullet hell , Roguelike","r":"December 14","l":"https://en.wikipedia.org/wiki/Enter_the_Gungeon"},{"t":"Equestria at War","p":["Windows","macOS","Linux"],"d":"Equestria at War Team","g":"Grand strategy, real time strategy, simulation","r":"June 30, 2017","l":"https://en.wikipedia.org/wiki/Equestria_at_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7pwe.jpg","s":"Equestria at War is a Hearts of Iron IV mod that seeks to recreate the fantastical world of Equestria from the My Little Pony franchise, dimmed with a bleaker setting rife with both nuances and its own plentiful twists, such as the notion of industrialization, far-reaching corruption and an ample amount of political intrigue."},{"t":"Etrian Odyssey V: Beyond the Myth","p":["Nintendo 3DS"],"g":"RPG, Dungeon crawl","r":"October 17"},{"t":"Ever Oasis","p":["Nintendo 3DS"],"g":"Action-adventure, RPG","r":"June 23","l":"https://en.wikipedia.org/wiki/Ever_Oasis"},{"t":"EverQuest II: Planes of Prophecy","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest_II:_Planes_of_Prophecy"},{"t":"EverQuest: Ring of Scale","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest:_Ring_of_Scale"},{"t":"Everspace","p":["macOS","Windows","Xbox One"],"d":"Rockfish Games","u":"Rockfish Games","g":"Space combat, roguelike","r":"May 25, 2017","l":"https://en.wikipedia.org/wiki/Everspace","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ms.jpg","s":"Everspace is an action-focused single-player space shooter with rock solid 6DOF controls combining roguelike elements with top-notch visuals and a captivating non-linear story as well as VR support in the final version."},{"t":"Everybody's Golf","p":["PlayStation 4"],"g":"Sports","r":"August 29","l":"https://en.wikipedia.org/wiki/Everybody%27s_Golf_(2017_video_game)"},{"t":"EVERYTHING","p":["PlayStation 4"],"g":"Simulation","r":"March 21","l":"https://en.wikipedia.org/wiki/Everything_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24rj.jpg","s":"Everything is an interactive experience where everything you see is a thing you can be, from animals to planets to galaxies and beyond. Travel between outer and inner space, and explore a vast, interconnected universe of things without enforced goals, scores, or tasks to complete. Everything is a procedural, AI-driven simulation of the systems of nature, seen from the points of view of everything in the Universe. Narrated by the late British philosopher Alan Watts."},{"t":"Everything is Going to Be OK","p":["Windows","macOS"],"d":"Nathalie Lawhead","g":"Indie","r":"January 31, 2017","l":"https://en.wikipedia.org/wiki/Everything_is_Going_to_Be_OK","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co280z.jpg","s":"A collection of short minigames about surviving trauma, depression, and a society that values commodification of grief."},{"t":"Exile Election","p":["PlayStation Vita","PlayStation 4"],"d":"Regista","u":"Nippon Ichi Software","g":"Visual novel","r":"April 27, 2017","l":"https://en.wikipedia.org/wiki/Exile_Election","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fno.jpg","s":"The game takes place in an abandoned amusement park. The game's characters are trapped within the park, with the outside world being in a post-apocalyptic wasteland infested with murderous monsters. Within the park, the game's thirteen main characters are held captive by a mysterious mechanical doll named \"Alice\", who holds the \"death games\", which basically force the characters against each other for survival - the losers being exiled back out into the world. Alice refuses to stop the games until only two characters are alive and present. The game's protagonist is Kaname Ichijou, a young man who has the ability to see sound as colors and sees spoken falsehoods in the color red. He also harbors a grudge against most of the rest of the characters of the game for allowing the exile of his little sister."},{"t":"Expeditions: Viking","p":["Windows"],"d":"Logic Artists","u":"Logic Artists","g":"Tactical role-playing","r":"April 27, 2017","l":"https://en.wikipedia.org/wiki/Expeditions:_Viking","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24rl.jpg","s":"Expeditions: Viking is a Historically-themed RPG set in the Viking Age. As the new leader of a humble clan of farmers and fighters players must adventure into the unknown lands to the west to raid and/or trade their way to wealth, fame and glory. Will you rewrite history as a peaceful and benevolent trader? Or pave your road to Valhalla with the treasures and bones of your fallen enemies? Experience choice and consequence as never before in the much awaited addition to the Expeditions Series, Expeditions: Viking."},{"t":"Expeditions: Vikings","p":["Windows"],"r":"April 27"},{"t":"F1 2017","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"August 25","l":"https://en.wikipedia.org/wiki/F1_2017_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co237a.jpg","s":"Win the 2017 World Championship, break every record in the fastest ever F1 cars, and race some of the most iconic F1 cars of the last 30 years. With an even deeper ten year Career, more varied gameplay in the new ‘Championships’ mode, and a host of other new features, both online and offline, F1 2017 is the most complete and thrilling F1 videogame ever."},{"t":"Fable Fortune","p":["Windows","Xbox One"],"g":"DCCG","r":"July 25","l":"https://en.wikipedia.org/wiki/Fable_Fortune"},{"t":"Faeria","p":["Windows","macOS","Linux"],"d":"Abrakam","u":"Versus Evil","g":"Collectible card game, turn-based strategy","r":"March 8, 2017","l":"https://en.wikipedia.org/wiki/Faeria","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mwi.jpg","s":"Faeria is a digital collectible card and turn-based strategy game that takes place on a dynamic playing board set in a fantasy universe. Players in Faeria battle one-on-one against other players or computer-controlled opponents. Battles take place on a empty hex board and the goal for each player is to reduce the opponent's avatar health to zero before their own is exhausted. Part of the game's strategy is managing the placement of tiles on the board to create routes for one's creatures to reach the opponent while limiting progress from the opponent.\n\nWinning games earns in-game currency that can be used to purchase new packs of cards, from which the player can then customize their deck. Support for the iOS and Android versions of the game were dropped in 2018 to focus on the PC version. The game also moved out of its free-to-play model and announced plans for card expansion DLCs around the same time."},{"t":"Fairy Fencer F Advent Dark Force","p":["Windows"],"g":"RPG","r":"February 14","l":"https://en.wikipedia.org/wiki/Fairy_Fencer_F_Advent_Dark_Force"},{"t":"Faith: The Unholy Trinity","p":["Windows","Nintendo Switch"],"d":"Airdorf Games","u":"New Blood Interactive","g":"Survival horror, Religious horror","r":"October 4, 2017","l":"https://en.wikipedia.org/wiki/Faith:_The_Unholy_Trinity"},{"t":"Fallen Legion: Flames of Rebellion","p":["PlayStation Vita"],"g":"RPG, Platformer, Action","r":"July 18","l":"https://en.wikipedia.org/wiki/Fallen_Legion"},{"t":"Fallen Legion: Sins of an Empire","p":["PlayStation 4"],"g":"RPG, Platformer, Action","r":"July 18","l":"https://en.wikipedia.org/wiki/Fallen_Legion"},{"t":"Faraway: Puzzle Escape","p":["Android","iOS"],"d":"Pine Studio","u":"Snapbreak Games","g":"Puzzle game","r":"May 15, 2017","l":"https://en.wikipedia.org/wiki/Faraway:_Puzzle_Escape","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1j5t.jpg","s":"Faraway: Puzzle Escape is an adventure game, a modern tribute to Myst designed for phones and tablets. In Faraway you're an adventurer exploring ruins of ancient temples full of challenges and mysterious riddles."},{"t":"Farming Simulator 18","p":["Nintendo 3DS","PlayStation Vita"],"g":"Simulation","r":"June 6","l":"https://en.wikipedia.org/wiki/Farming_Simulator"},{"t":"Farpoint","p":["PlayStation VR"],"g":"FPS","r":"May 16","l":"https://en.wikipedia.org/wiki/Farpoint_(video_game)"},{"t":"Fast RMX","p":["Nintendo Switch"],"d":"Shin'en Multimedia","u":"Shin'en Multimedia","g":"Racing","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Fast_RMX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1koy.jpg","s":"The Nintendo Switch version of Fast Racing NEO.\n\n\"Race through a futuristic sci-fi world at incredible speeds in FAST RMX.\n\nJump into the driver’s seat of your anti-gravity vehicle and put your skills to the test in high octane competitions. Challenge your friends to local split-screen competitions or take part in online races against players from all around the world.\""},{"t":"Fate/Extella: The Umbral Star","p":["PlayStation 4","PlayStation Vita"],"g":"Action","r":"January 17"},{"t":"Fearful Symmetry & The Cursed Prince","p":["Windows","Xbox One"],"r":"December 12"},{"t":"FIFA 18","p":["Windows","Nintendo Switch","PlayStation 3","PlayStation 4","Xbox 360","Xbox One"],"g":"Sports","r":"September 29","l":"https://en.wikipedia.org/wiki/FIFA_18","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uxd.jpg","s":"Powered by Frostbite, EA SPORTS FIFA 18 blurs the line between the virtual and real worlds, bringing to life the players, teams, and atmospheres that immerse you in the emotion of The World’s Game. The biggest step in gameplay innovation in franchise history, FIFA 18 introduces Real Player Motion Technology, an all-new animation system which unlocks a new level of responsiveness, and player personality – now Cristiano Ronaldo and other top players feel and move exactly like they do on the real pitch. Player Control combined with new Team Styles and Positioning give you the tools to deliver Dramatic Moments that ignite Immersive Atmospheres around the world. The World’s Game also takes you on a global journey as Alex Hunter Returns along with a star-studded cast of characters, including Cristiano Ronaldo and other European football stars. And in FIFA Ultimate Team, FUT ICONS, featuring Ronaldo Nazário and other football legends, are coming to FIFA 18 on PlayStation 4, Xbox One, and PC when the game launches on September 29, 2017."},{"t":"Fight of Gods","p":["Windows","Nintendo Switch","PlayStation 4","Arcade"],"d":"Digital Crafter","u":"Digital Crafter, exA-Arcadia","g":"Fighting game","r":"September 7, 2017","l":"https://en.wikipedia.org/wiki/Fight_of_Gods"},{"t":"Fight'N Rage","p":["Nintendo Switch","Windows"],"d":"SebaGamesDev, BlitWorks","u":"SebaGamesDev, BlitWorks","g":"Beat 'em up","r":"September 19, 2017","l":"https://en.wikipedia.org/wiki/Fight'N_Rage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24h3.jpg","s":"Fight’N Rage is a brand new old-school side-scroller beat’em up. Inspired by the classics from the “golden age”, and with an art style that mimics the aesthetic from the 90's arcade gems, this game pays homage to all classic gameplay features that makes this genre one of the best from its time!"},{"t":"Figment","p":["Linux","macOS","Windows"],"d":"Bedtime Digital Games","u":"Bedtime Digital Games","g":"Music, Platform, Puzzle, Adventure, Indie","r":"September 22, 2017","l":"https://www.igdb.com/games/figment","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co691d.jpg","s":"A musical action-adventure set in the recesses of the human mind... Welcome to the world of Figment. A strange and surreal world; a place filled with our deepest thoughts, urges and memories, populated by the many voices we hear in our heads.\n\nThis mind has been quiet and calm for many years. But something has changed. New thoughts have started to emerge - taking the shape of nightmarish creatures who spread fear wherever they go. The only hope is for the grumpy Dusty, the mind's former voice of courage, to get back to his old self and help the mind to face its fears.\n\nJoin Dusty and his ever-optimistic friend, Piper, on an adventure through the different sides of the mind, solving puzzles to set things straight, beating back the nightmares and seeking to restore the courage that's been lost."},{"t":"Final Fantasy XII: The Zodiac Age","p":["PlayStation 4"],"g":"RPG","r":"July 11","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XII","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g6o.jpg","s":"\"FINAL FANTASY XII THE ZODIAC AGE improves upon the 2006 classic FINAL FANTASY XII, now more beautiful and easier to play than ever. The high-definition remaster introduces several modern advancements, including reconstructed battle design and a revamped job system. With newly implemented trophies and share functions, as well as stark visual and sound improvements in true HD for the first time, players both returning and new to the game will experience a grand adventure that spans the world of Ivalice in an entirely fresh and improved way.\n\nIncludes several all-new enhanced gameplay features:\n– The Zodiac Job System\n– Improved character leveling system that now caters to the player’s preference\n– Trial Mode – Take on monsters and enemies in up to 100 consecutive battles\n– Speed Mode\n– Latest-generation HD graphical capabilities, including characters and movie scenes fully remastered in high definition.\n– True 7.1 surround sound, including high definition voicing and newly recorded background music utilizing the current generation of sound production.\n– Modern advancements including PlayStation4 trophy support and share functionalities, auto-save and shortened loading times\n– An endless amount of gameplay and adventure including Hunts, Battles, and mini-games\""},{"t":"Final Fantasy XIV: Stormblood","p":["Windows","macOS","PlayStation 4"],"g":"MMO, RPG","r":"June 20","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XIV"},{"t":"Final Fantasy XV: A New Empire","p":["Android","iOS"],"d":"Epic Action","u":"MZ","g":"Strategy","r":"June 29, 2017","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XV:_A_New_Empire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vjg.jpg","s":"Be the hero of your own Final Fantasy XV adventure in the brand new mobile strategy game Final Fantasy XV: A New Empire! Build your own kingdom, discover powerful magic, and dominate the realm alongside all of your friends!\n\nFinal Fantasy XV: A New Empire is a mobile adventure that lets you rewrite a favorite classic to fulfill your unique destiny. Journey through vast kingdoms, gather magical resources, and build the strongest Empire in Final Fantasy history! Fight fire with magic to defend friends and defeat foes alongside millions of players from around the world! Do you have the strength and strategy to control the Crystal and rule the Realm?"},{"t":"Finding Paradise","p":["Windows","macOS","Linux"],"g":"Interactive drama , Adventure, RPG","r":"December 14","l":"https://en.wikipedia.org/wiki/Finding_Paradise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24h6.jpg","s":"A story-driven experience about two doctors traversing through a dying man's memories to artificially fulfill his last wish."},{"t":"Fire Emblem Echoes: Shadows of Valentia","p":["Nintendo 3DS"],"g":"Tactical RPG","r":"May 19","l":"https://www.igdb.com/games/fire-emblem-echoes-shadows-of-valentia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coba3w.jpg","s":"In 1992, the second game in the Fire Emblem series, Fire Emblem Gaiden, launched exclusively in Japan. Now, for the first time, fans outside of Japan will get a taste of this classic game on the Nintendo 3DS family of systems. Fire Emblem Echoes: Shadows of Valentia is inspired by the 1992 original, reimagined on a grander scale. Every aspect of the Fire Emblem Gaiden game's presentation has been updated, along with the game being fully voiced. Fire Emblem Echoes: Shadows of Valentia recreates classic Fire Emblem gameplay with a modern twist, mixing in exploration of dungeons crawling with enemies.\""},{"t":"Fire Emblem Heroes","p":["iOS","Android"],"g":"Tactical RPG","r":"February 2","l":"https://en.wikipedia.org/wiki/Fire_Emblem_Heroes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rc1.jpg","s":"\"Take part in strategic turn-based battles streamlined for on-the-go play with maps that fit in the palm of your hand! Lead your army with easy touch and drag controls, including the ability to attack by simply swiping an ally over an enemy.\""},{"t":"Fire Emblem Warriors","p":["Nintendo Switch","Nintendo 3DS"],"g":"Hack and slash, RPG","r":"October 20","l":"https://en.wikipedia.org/wiki/Fire_Emblem_Warriors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24h8.jpg","s":"\"Clash with legions of soldiers and fierce monsters as Marth, Xander, Corrin, and other Fire Emblem heroes unleashing over-the-top-powerful Dynasty Warriors-style moves. Take direct control of known and original Fire Emblem characters, issue them strategic commands in the midst of battle, pair up heroes to unleash stunning attacks, and more. Unlock new playable heroes, each with their own unique moves, special attacks, weapon types, and voiced dialogue in this large-scale action game from the Hyrule Warriors team.\""},{"t":"Fire Pro Wrestling World","p":["Windows"],"d":"ZEX Corporation","u":"Spike Chunsoft","g":"Fighting, wrestling","r":"December 19, 2017","l":"https://en.wikipedia.org/wiki/Fire_Pro_Wrestling_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co206j.jpg","s":"The greatest grappling game returns to take on the world! Customize every aspect of the match, from your wrestler to the ring itself, in your fight for the championship belt."},{"t":"FlatOut 4: Total Insanity","p":["PlayStation 4","Xbox One","Windows"],"d":"Kylotonn","u":"Nacon, Strategy First","g":"Racing","r":"March 17, 2017","l":"https://en.wikipedia.org/wiki/FlatOut_4:_Total_Insanity","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1svu.jpg","s":"FlatOut 4: Total Insanity is a return to the franchise's adrenaline-pumping arcade destruction roots. Featuring an exciting blend of white-knuckle speed and wild out-of-control racing tracks, FlatOut 4 promises an intense death-defying demolition derby game featuring muscle cars, race cars, trucks and even a rocket boosted ice cream van!"},{"t":"Flinthook","p":["Windows","PlayStation 4","Xbox One"],"g":"Platformer, Roguelike","r":"April 18","l":"https://en.wikipedia.org/wiki/Flinthook"},{"t":"Flip Wars","p":["Nintendo Switch"],"d":"Over Fence","u":"Over Fence, Nintendo","g":"Action, tile-matching, party","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Flip_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30z6.jpg","s":"\"This tense multiplayer action game will have you stomping to flip over panels—and unwitting opponents! To win, flip the most panels to your color in local battles, online*, or single-player. The more you flip, the faster you’ll move in a mad dash to nab power ups. Increase your flip range, turn invincible, and more across 3 modes and 12 arenas!\n\nCompete alone or against up to 3 players to see who’s best at each mode: flip the most panels before time runs up in Panel Battle, knock out the most opponents in Time Battle, or outlast your rivals in Life Battle. All 12 arenas have 4 layouts to choose from, some containing hazards like panel-flipping buttons, beam cannons, and waves so beautiful they truly stun competitors. Learn the art of the flip with tutorials and try your hand at achievements. When you’re ready to compete, jump into an online* battle or a private room with friends via local wireless. No matter how you play, it’s time to think fast and pull off the ultimate color scheme!\""},{"t":"Flying Tigers: Shadows Over China","p":["Windows"],"d":"Ace Maddox","u":"Ace Maddox","g":"Action-adventure, combat flight simulation","r":"May 29, 2017","l":"https://en.wikipedia.org/wiki/Flying_Tigers:_Shadows_Over_China","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24hs.jpg","s":"Flying Tigers: Shadows Over China is an air-combat action game based on the historical events of America’s secret volunteer squadrons that defended China against Japan in the China-Burma-India theatre of World War 2."},{"t":"Football Manager 2018","p":["Windows","macOS","Linux"],"g":"Sports","r":"November 10","l":"https://en.wikipedia.org/wiki/Football_Manager_2018","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24hg.jpg","s":"They say football is a game of opinions and everyone has theirs, but it’s only yours that counts around here.\n\nYou make the decisions now, from who you sign and who you sell, to how you manage your budget. Will you build tactics around the players at your disposal or train them in your vision of how the game should be played? Who you pick and who you bench will affect squad harmony, and it’s up to you to manage it. Every decision comes back to you.\n\nGet it right and you’ll be the star of the show, grabbing the newspaper headlines and dominating trends on social media. They’ll write your name in footballing folklore…if you succeed, of course.\n\nWith unparalleled choices both on and off the pitch, all within the immersive footballing world, it’s time to decide what kind of manager do you want to be?\n\nTry your hand in 50 of the biggest footballing countries\nWin the title with any one of world’s top 2500 clubs\nPlay the transfer market with over 600,000 real players and staff\nWatch your football vision come to life before your very eyes\n\nAll purchases of Football Manager 2018 also include a free copy of Football Manager Touch 2018 for PC/Mac and Linux.\n\nNew for this season!\n\nDynamics – A harmonious squad produces better results on the pitch. By building partnerships amongst your players – both on and off the pitch – and maintaining a good dressing room atmosphere you’ll get the best performances out of your squad.\n\nMatchday Live – A brand new graphics engine produces the best lighting, stadiums and player models in the series’ history, alongside a sleeker match interface and modernised presentation that bring your fixtures to life.\n\nReal World Scouting System – A true-to-life representation of the techniques used by the world’s biggest clubs including more detailed data analysis that, combined with a wider range of scouting options, give you a better overview of any potential signing.\n\nSports Science – The new Medical Centre gives you a more complete overview of your squad’s injury situation, with your medical team providing advice on feedback on individual players’ injury risks and how to avoid injuries occurring during training.\n\nTactics – A redesigned tactics screen puts analysis at its heart, giving you a clear view of whether your tactic is working. The new pre-match briefing allows you to be better prepared for your upcoming fixtures, while new player roles give you more ways to exploit your players’ abilities.\n\nFantasy Draft – Redesigned with a new interface that is perfect for streaming and with several new setup options that help tailor the Fantasy Draft experience to you, including a bigger squad budget and a Quick Start option.\n\nFootball Intelligence – A realistic transfer market that reflects the inflated transfer fees and contract values, more clauses to help finalise that blockbuster deal and the more intelligent transfer and board AI that take into account more contextual information from the game world."},{"t":"For Honor","p":["Windows","PlayStation 4","Xbox One"],"g":"Action, Fighting","r":"February 14","l":"https://en.wikipedia.org/wiki/For_Honor","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coclez.jpg","s":"Enter the chaos of war as a bold Knight, a brutal Viking, or a deadly Samurai. Play the thrilling story campaign or fight in brutal PvP modes, all on new dedicated servers. Enjoy an evolved experience with 18 Heroes, 18 maps, new PvP and ranked modes, thousands of gear items, and more."},{"t":"Fortnite","p":["Windows","PlayStation 4","Xbox One"],"g":"Battle royale","r":"September 26","l":"https://en.wikipedia.org/wiki/Fortnite_Battle_Royale"},{"t":"Forts","p":["Windows"],"d":"EarthWork Games","u":"EarthWork Games","g":"Real-time strategy","r":"April 19, 2017","l":"https://en.wikipedia.org/wiki/Forts_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coabh1.jpg","s":"Forts is a physics-based RTS where foes design and build custom bases, arm them to the teeth and blast their opponent's creations to rubble."},{"t":"Forza Motorsport 7","p":["Windows","Xbox One"],"g":"Racing","r":"October 3","l":"https://en.wikipedia.org/wiki/Forza_Motorsport_7","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24hd.jpg","s":"Forza Motorsport 7 immerses players in the exhilarating thrill of competitive racing. From mastering the new motorsport-inspired campaign to collecting a wide range of cars to experiencing the excitement of driving at the limit, this is Forza reimagined."},{"t":"Four Last Things","p":["Windows","Android","iOS"],"g":"Point-and-click adventure","r":"February 23, 2017","l":"https://en.wikipedia.org/wiki/Four_Last_Things_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24hy.jpg","s":"Four Last Things is a very silly pythonesque adventure made from Renaissance-era paintings and public domain recordings of classical music. It is about sin, and the Four Last Things – Death, Judgement, Heaven and Hell – and strives to be intelligent and ridiculous in equal measures."},{"t":"Fractured Minds","p":["PlayStation 4","Xbox One","Windows","iOS","Android","Nintendo Switch"],"d":"Emily Mitchell","u":"Wired Productions","g":"Role-playing, puzzle","r":"November 14, 2017","l":"https://en.wikipedia.org/wiki/Fractured_Minds"},{"t":"Freddy Fazbear's Pizzeria Simulator","p":["Windows"],"g":"Simulator, Strategy, Indie","l":"https://en.wikipedia.org/wiki/Freddy_Fazbear's_Pizzeria_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co720f.jpg","s":"Presenting a fun Five Nights at Freddy's adventure with a lighter touch for the holidays, Freddy Fazbear's Pizzeria Simulator puts you in charge of developing your own restaurant! Design pizzas, feed kids, and get high scores!"},{"t":"Free Fire","p":["Android","iOS"],"d":"Garena","u":"Garena","g":"Battle royale","r":"December 8, 2017","l":"https://en.wikipedia.org/wiki/Free_Fire_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52c7.jpg","s":"Free Fire is the ultimate survival shooter game available on mobile. Each 10-minute game places you on a remote island where you are pit against 49 other players, all seeking survival. Players freely choose their starting point with their parachute, and aim to stay in the safe zone for as long as possible. Drive vehicles to explore the vast map, hide in the wild, or become invisible by proning under grass or rifts. Ambush, snipe, survive, there is only one goal: to survive and answer the call of duty."},{"t":"Freeways","p":["Windows","macOS","Android","iOS"],"d":"Captain Games","u":"Captain Games","g":"Simulation","r":"September 2017","l":"https://en.wikipedia.org/wiki/Freeways_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26xo.jpg","s":"You are a traffic engineer. Draw freeway interchanges. Optimize for efficency and avoid traffic jams!"},{"t":"Friday the 13th: The Game","p":["Windows","PlayStation 4","Xbox One"],"g":"Survival horror","r":"May 26","l":"https://www.igdb.com/games/friday-the-13th-the-game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20x7.jpg","s":"Friday the 13th: The Game is a third-person horror, survival game where players take on the role of a teen counselor, or for the first time ever, Jason Voorhees. You and six other unlucky souls will do everything possible to escape and survive while the most well-known killer in the world tracks you down and brutally slaughters you."},{"t":"Full Throttle Remastered","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Graphic adventure","r":"April 18","l":"https://en.wikipedia.org/wiki/Full_Throttle_(1995_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ie.jpg","s":"Originally released by LucasArts in 1995, Full Throttle is a classic graphic adventure game from industry legend Tim Schafer, telling the story of Ben Throttle; butt-kicking leader of biker gang the Polecats, who gets caught up in a tale of Motorcycles, Mayhem and Murder."},{"t":"Futurama: Worlds of Tomorrow","p":["iOS","Android"],"d":"TinyCo","u":"Jam City","g":"City building game, Adventure","r":"June 29, 2017","l":"https://en.wikipedia.org/wiki/Futurama:_Worlds_of_Tomorrow","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2816.jpg","s":"A city building and RPG Futurama game."},{"t":"Future Unfolding","p":["Windows","PlayStation 4"],"r":"March 15"},{"t":"Galaxy of Pen & Paper","p":["Android","Linux","macOS","iOS","Windows"],"g":"RPG","r":"July 27","l":"https://en.wikipedia.org/wiki/Galaxy_of_Pen_%26_Paper"},{"t":"Gang Beasts","p":["Linux","macOS","Windows","PlayStation 4"],"d":"Boneloaf","u":"Double Fine Presents, Boneloaf","g":"Beat 'em up, party","r":"December 12, 2017","l":"https://en.wikipedia.org/wiki/Gang_Beasts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24is.jpg","s":"Gang Beasts is a silly multiplayer party game with surly gelatinous characters, brutal slapstick fight sequences, and absurd hazardous environments, set in the mean streets of Beef City."},{"t":"Gangstar: New Orleans","p":[],"l":"https://en.wikipedia.org/wiki/Gangstar:_New_Orleans"},{"t":"Gear.Club Unlimited","p":["Nintendo Switch"],"g":"Racing","r":"November 21","l":"https://en.wikipedia.org/wiki/Gear.Club_Unlimited"},{"t":"Get Even","p":["Windows","PlayStation 4","Xbox One"],"g":"FPS","r":"June 23","l":"https://en.wikipedia.org/wiki/Get_Even_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wm6.jpg","s":"\"Take a deep breath...\" Try to remember: a girl, a chair, a bomb. Just keep... calm. Follow the voice into the depths of your memory. Relax... and search for the darkest memories in the deepest recesses of your mind. Can you find her? The clock is ticking... And this is just a part of the treatment."},{"t":"Getting Over It with Bennett Foddy","p":["Windows","macOS","iOS"],"d":"Bennett Foddy","g":"Platform","r":"October 6, 2017","l":"https://en.wikipedia.org/wiki/Getting_Over_It_with_Bennett_Foddy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wl5.jpg","s":"Getting Over It with Bennett Foddy is a punishing climbing game, a homage to Jazzuo's 2002 B-Game classic 'Sexy Hiking'. You move the hammer with the mouse, and that's all there is. With practice, you'll be able to jump, swing, climb and fly. Great mysteries and a wonderful reward await the master hikers who reach the top of the mountain.\n\nTo quote Jazzuo himself: \"The hiking action is very similar to way you would do it in real life, remember that and you will do well\"."},{"t":"Ghost in the Shell: Stand Alone Complex – First Assault Online","p":["Windows"],"d":"NeoPle","u":"Nexon","g":"First-person shooter","r":"July 1, 2017","l":"https://en.wikipedia.org/wiki/Ghost_in_the_Shell:_Stand_Alone_Complex_%E2%80%93_First_Assault_Online"},{"t":"Giga Wrecker","p":["Windows"],"d":"Game Freak","u":"Rising Star Games","g":"Puzzle-platform","r":"February 6, 2017","l":"https://en.wikipedia.org/wiki/Giga_Wrecker","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5462.jpg","s":"\"Giga Wrecker is a 2D puzzle-platform action game developed and published by Game Freak. You play as a cyborg girl, who has the power of reconstructing debris and scraps into various weapons, and explore a world invaded by an army of mysterious robots.\""},{"t":"Gigantic","p":["Windows","Xbox One"],"d":"Motiga","u":"Perfect World Entertainment","g":"Third-person shooter, Team brawler","r":"July 20, 2017","l":"https://en.wikipedia.org/wiki/Gigantic_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24j8.jpg","s":"Gigantic is a visually-stunning evolution in team action gaming, where freedom of movement, play-style choice, and towering Guardians makes 5x5 competition more accessible and fun than ever."},{"t":"Global Soccer Manager 2017","p":["Windows"],"g":"Sports","r":"May 24"},{"t":"GNOG","p":["PlayStation VR"],"g":"Point-and-click, Music, Puzzle, Adventure, Indie","r":"May 2","l":"https://en.wikipedia.org/wiki/GNOG","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uag.jpg","s":"From acclaimed indie studio KO_OP and in association with beloved game-making initiative Double Fine Presents, Gnog is a 3D puzzle game set in a tactile world of toys and secrets. Point, click, grab, poke, spin, pull, and play with uniquely charming monster heads, and explore the hidden worlds inside them from your couch, or face-to-face in stunning PlayStation VR. Filled with eye-catching designs, playful interactions, and a rich, reactive soundtrack, the hand-crafted heads come to life in your hands!\n\nInspired by real-world toy designs, every Gnog head is a miniature world to discover. Grab a bookcase and spin it to reveal a hidden pile of coins, slide levers to navigate a damaged ship through outer space, crank a wheel to cook a stew on the stove – each playful interaction generates lively feedback and surprising consequences. Set to a relaxing and dynamic soundtrack that evolves with each level, the surreal worlds and joyful puzzles of Gnog will have you turning heads!"},{"t":"Go! Go! Kokopolo 3D: Space Recipe for Disaster","p":["Nintendo 3DS"],"d":"Tanukii Studios Limited","u":"Circle Ent, Starsign","g":"Action, Maze, Puzzle","r":"February 23, 2017","l":"https://en.wikipedia.org/wiki/Go!_Go!_Kokopolo_3D:_Space_Recipe_for_Disaster"},{"t":"God Wars: Future Past","p":["PlayStation 4","PlayStation Vita"],"g":"Tactical RPG","r":"June 20"},{"t":"Goken","p":["Windows"],"r":"September 28"},{"t":"Golf Story","p":["Nintendo Switch"],"g":"RPG, Adventure, Sports","r":"September 28","l":"https://en.wikipedia.org/wiki/Golf_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q9e.jpg","s":"Play the story of a golfer, forced to give up all that he holds dear for one final shot at accomplishing his dream.\n\nBut all is not so simple in the world of golf. To best today's players you have to be able to keep up with them not just on the course, but also off it."},{"t":"Golf Zero","p":["iOS","Android","Browser"],"d":"Colin Games","u":"Ratalaika Games","g":"Platformer, sports","r":"March 14, 2017","l":"https://en.wikipedia.org/wiki/Golf_Zero","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g6f.jpg","s":"Golf Zero is a crazy mix of golf and platforming. Jump, bounce and slide your way around the levels trying everything you can to get the ball in the hole.\n\nThere is nothing quite like a nice round of Golf. The freshly cut grass, the birds singing, the razor sharp saw blades, the mid-air bullet time shot as you dodge a bone crushing boulder.\n\nWork your way through the 40 normal levels or compete against the rest of the world in the speed run levels."},{"t":"Gorogoa","p":["Windows","macOS","Nintendo Switch"],"g":"Puzzle","r":"December 14","l":"https://en.wikipedia.org/wiki/Gorogoa","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kby.jpg","s":"Gorogoa is a beautiful hand-drawn story suspended inside a completely unique puzzle. Arrange and combine lavishly illustrated panels, each one a separate interactive window into a living game world."},{"t":"Graceful Explosion Machine","p":["Windows","Nintendo Switch","PlayStation 4"],"d":"Vertex Pop","u":"Vertex Pop","g":"Scrolling shooter","r":"April 6, 2017","l":"https://en.wikipedia.org/wiki/Graceful_Explosion_Machine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24yc.jpg","s":"\"Skillfully pilot the advanced Graceful Explosion Machine (GEM) fighter while blasting swarms of crystalline enemies with your ludicrously overpowered quad-weapon array!\n\nLost in deep space, you'll shoot, dash and combo your way through jewel-hued alien worlds, fighting to find a way home.\""},{"t":"Gran Turismo Sport","p":["PlayStation 4"],"g":"Racing","r":"October 17","l":"https://en.wikipedia.org/wiki/Gran_Turismo_Sport","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wk2.jpg","s":"Welcome to the future of motorsports – the definitive motor racing experience is back and better than ever only on PlayStation 4.\n\nGran Turismo Sport is the world’s first racing experience to be built from the ground up to bring global, online competitions sanctioned by the highest governing body of international motorsports, the FIA (Federation International Automobile). Create your legacy as you represent and compete for your home country or favorite manufacturer."},{"t":"Granny","p":["Android","iOS"],"d":"DVloper","u":"DVloper","g":"Adventure, Indie, Arcade","r":"November 24, 2017","l":"https://www.igdb.com/games/granny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co95dl.jpg","s":"Granny is a stealth horror game in which the player must escape from a house within five days while avoiding detection by an elderly captor who reacts to sound. Players hide in wardrobes and under beds, solve puzzles, and quietly navigate the environment to find a way out."},{"t":"Gravity Rush 2","p":["PlayStation 4"],"g":"Action-adventure","r":"January 20","l":"https://en.wikipedia.org/wiki/Gravity_Rush_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaxyt.jpg","s":"Another mind-bending adventure awaits gravity queen Kat as a new danger emerges to threaten the fabric of the universe itself. Still searching for clues behind the mystery of her origin, and with the powerful Raven at her side, Kat must master three unique gravity attack styles as she takes on enemies and massive bosses."},{"t":"Grimoire: Heralds of the Winged Exemplar","p":["Windows"],"d":"Golden Era Games","u":"Golden Era Games","g":"Role-playing Dungeon Crawl","r":"August 4, 2017","l":"https://en.wikipedia.org/wiki/Grimoire:_Heralds_of_the_Winged_Exemplar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uw4.jpg","s":"Cleveland Mark Blakemore's Magnum Opus! The ultimate classic style turn-based roleplaying game in the tradition of Wizardry, Might&Magic, Lands Of Lore and Eye of the Beholder! A game that took over 20 years to produce! As much as 600 hours of play with hand-painted graphics and old skool goodness!"},{"t":"Guardians of the Galaxy: The Telltale Series","p":["Android","iOS","PlayStation 4","Windows","Xbox One"],"d":"Telltale Games","u":"Telltale Games","g":"Graphic adventure, Interactive film","r":"April 18, 2017","l":"https://en.wikipedia.org/wiki/Guardians_of_the_Galaxy:_The_Telltale_Series","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27yt.jpg","s":"Marvel's Guardians of the Galaxy: The Telltale Series is a brand new story of the universe's unlikeliest heroes: Star-Lord, Gamora, Drax, Rocket, and Groot. In the wake of an epic battle, the Guardians discover an artifact of unspeakable power. Each of them has a reason to desire this relic, as does a ruthless enemy who is the last of her kind, and who will stop at nothing to tear it from their hands.\n\nFrom Earth to the Milano to Knowhere and beyond, and set to the beat of awesome music, you wear the rocket-powered boots of Star-Lord in an original Guardians adventure, where your decisions and actions drive the story you experience."},{"t":"Guardians of the Galaxy: The Telltale Series – Episode 5: Don't Stop Believin'","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"November 7"},{"t":"Guardians of the Galaxy: The Telltale Series — Episode 1: Tangled Up in Blue","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"April 18"},{"t":"Guardians of the Galaxy: The Telltale Series — Episode 2: Under Pressure","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"June 6"},{"t":"Guardians of the Galaxy: The Telltale Series — Episode 3: More Than a Feeling","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"August 22"},{"t":"Guardians of the Galaxy: The Telltale Series — Episode 4: Who Needs You","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"October 10"},{"t":"Guild Wars 2: Path of Fire","p":["Windows"],"g":"MMO, RPG","r":"September 22"},{"t":"Guilty Gear Xrd Rev.2","p":["PlayStation 4","PlayStation 3"],"g":"Fighting","r":"May 26","l":"https://en.wikipedia.org/wiki/Guilty_Gear_Xrd"},{"t":"Gun Gun Pixies","p":["PlayStation Vita"],"d":"Shade","u":"Compile Heart, PQube","g":"Third-person shooter","r":"April 27, 2017","l":"https://en.wikipedia.org/wiki/Gun_Gun_Pixies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24y3.jpg","s":"Tiny aliens battle other tiny aliens at a woman's dormitory in this 3rd person shooter"},{"t":"Gundam Breaker 3 Break Edition","p":["PlayStation 4","PlayStation Vita"],"r":"May 2"},{"t":"Gundam Versus","p":["PlayStation 4"],"r":"September 29","l":"https://en.wikipedia.org/wiki/Gundam_Versus"},{"t":"Gungrave VR","p":["PlayStation VR"],"g":"TPS","r":"December 14"},{"t":"Gunman Taco Truck","p":["Android","iOS","Windows","macOS"],"u":"Romero Games","g":"Roguelike","r":"January 28, 2017","l":"https://en.wikipedia.org/wiki/Gunman_Taco_Truck","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z0w.jpg","s":"Gunman Taco Truck is an action-packed drive across the post-apocalypse United States to reach the safe haven of Winnipeg, Canada, where there are no taco trucks and your family’s taco business can thrive. Getting to the safe towns is hectic but your truck is armed with weapons that blast mutants into taco fillings. In the towns you serve up the mutant scraps to struggling survivors who are more picky than they should be. Use money earned and scrap metal found to upgrade your truck and buy gas and supplies for the trip to the next town."},{"t":"Guns of Boom","p":["iOS","Android"],"d":"Game Insight","u":"Game Insight","g":"First-person shooter","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Guns_of_Boom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ojf.jpg","s":"Mobile PvP shooter with dynamic battles, super easy controls, and tons of guns and equipment!"},{"t":"Hakoniwa Company Works","p":["PlayStation 4"],"d":"Nippon Ichi Software","u":"Nippon Ichi Software","g":"Tactical role-playing, sandbox","r":"July 13, 2017","l":"https://en.wikipedia.org/wiki/Hakoniwa_Company_Works","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28dz.jpg"},{"t":"Hakuoki: Kyoto Winds","p":["PlayStation Vita"],"r":"May 16"},{"t":"Half-Life: C.A.G.E.D.","p":["Windows","macOS","Linux"],"d":"Future Games Select","u":"Future Games Select","g":"First-person shooter","r":"September 21, 2017","l":"https://en.wikipedia.org/wiki/Half-Life:_C.A.G.E.D.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc67v.jpg","s":"C.A.G.E.D. is an explosive prison escape adventure! Break-out and battle your way to freedom in this electrifying modification for Half-Life."},{"t":"Halo Wars 2","p":["Windows","Xbox One"],"g":"RTS","r":"February 21","l":"https://en.wikipedia.org/wiki/Halo_Wars_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2807.jpg","s":"After decades adrift and declared “lost with all hands,” the brave crew of the UNSC Spirit of Fire are mysteriously awoken above an ancient Forerunner haven known as the Ark. In Halo Wars 2, Captain Cutter and his crew will face one of humanity’s most formidable threats yet: The Banished – a fierce and powerful Brute faction led by a cunning and lethal warrior known as Atriox.\n\nHalo Wars 2 delivers real-time strategy at the speed of Halo combat. Get ready to lead armies of Spartans and other Halo fighting forces like Warthogs, Scorpions and exciting new units in a brutal war against a terrifying new enemy on the biggest Halo battlefield yet."},{"t":"Hand of Fate 2","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"g":"Action RPG","r":"November 7","l":"https://en.wikipedia.org/wiki/Hand_of_Fate_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iiq.jpg","s":"Hand of Fate 2 is a dungeon crawler set in a world of dark fantasy. Master a living boardgame where every stage of the adventure is drawn from a deck of legendary encounters chosen by you! Choose wisely - your opponent, the enigmatic Dealer, will pull no punches as he shapes you into the instrument of his revenge.\n\nThe table has changed, but the stakes remain the same: life or death!\n\nKEY GAME FEATURES\n\nA world transformed - 100 years have passed since the Dealer was usurped and the Game of Life and Death gained a new master.\n\n22 exciting new challenges that will push your deck-building skills to the limit - Hunt fiendish assassins, reunite star-crossed lovers or build up a fortress to withstand a raider assault!\n\nEnlist the aid of all new companion characters - team up with them in battle, or have them bend the rules of the boardgame in your favor!\n\nHundreds of new encounters, artifacts and items to earn and upgrade.\n\nEnhanced action-RPG combat - shred foes with quick dual-wielded daggers or brutalize them with heavy two-handed hammers. Build up your combo meter to unleash powerful special attacks!\n\nEngage new foes united by all-new card suits - Cross swords with disciplined Imperial soldiers, purge corrupted mutants and fend off northern raiders."},{"t":"Harvest Moon: Light of Hope","p":["Windows"],"g":"Farming","r":"November 14"},{"t":"Harvest Moon: Lil' Farmers","p":["iOS","Android"],"r":"May 25"},{"t":"Has-Been Heroes","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Action, Roguelike, Strategy","r":"March 28","l":"https://en.wikipedia.org/wiki/Has-Been_Heroes"},{"t":"Hatsune Miku: Project DIVA Future Tone","p":["PlayStation 4"],"g":"Rhythm","r":"January 10"},{"t":"Heat Signature","p":["Windows"],"d":"Suspicious Developments","u":"Suspicious Developments","g":"Action, stealth","r":"September 21, 2017","l":"https://en.wikipedia.org/wiki/Heat_Signature_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qrb.jpg","s":"Fly your tiny defenceless pod up to larger ships, dock with their airlock, and sneak inside. Once you're in, you creep through their corridors, ambushing guards, hiding bodies, stealing new weapons, blowing them up from the inside, or hijacking their turrets and even the whole ship."},{"t":"Hellblade: Senua's Sacrifice","p":["Windows","PlayStation 4"],"g":"Action-adventure, Hack and slash","r":"August 8","l":"https://www.igdb.com/games/hellblade-senuas-sacrifice","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l7l.jpg","s":"Hellblade: Senua's Sacrifice is a single-player action-adventure game set in a dark fantasy world inspired by Norse mythology and Celtic culture. Players control Senua, a Pict warrior who journeys into the Norse underworld to rescue the soul of her dead lover from the goddess Hela. The game blends melee combat, puzzle solving, and psychological horror, with Senua's psychosis shaping how the world is perceived, including voices that provide guidance or attempt to mislead the player.\n\nThe game was developed by a team of around twenty people and features no heads-up display or tutorials. Instead, audio cues from voices in Senua's head guide the player through combat and environmental challenges. The portrayal of psychosis was developed in collaboration with neuroscientists and people who experience the condition."},{"t":"Hello Neighbor","p":["Windows","macOS","Xbox One"],"g":"Stealth, Survival horror","r":"December 8","l":"https://en.wikipedia.org/wiki/Hello_Neighbor","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8kr5.jpg","s":"Hello Neighbor is a stealth horror game about sneaking into your creepy neighbor's house to figure out what horrible secrets he's hiding in his basement. You play against an AI that adapts from your actions. Really enjoying climbing through that backyard window? Expect a bear trap there. Sneaking through the front door? There'll be cameras there soon. Trying to escape? Your neighbor will find a shortcut and catch you."},{"t":"Herald: An Interactive Period Drama","p":["Windows","macOS","Linux","PlayStation 4","Xbox 360","Xbox One"],"d":"Wispfire","g":"Adventure, Period Drama","r":"February 22, 2017","l":"https://en.wikipedia.org/wiki/Herald:_An_Interactive_Period_Drama"},{"t":"Herocade","p":["PlayStation VR"],"r":"April 18"},{"t":"Heroes of the Seven Seas","p":["PlayStation VR"],"r":"July 24"},{"t":"Hey! Pikmin","p":["Nintendo 3DS"],"g":"Action","r":"July 28","l":"https://en.wikipedia.org/wiki/Hey!_Pikmin"},{"t":"Hidden Agenda","p":["PlayStation 4"],"g":"Adventure, Interactive film","r":"October 24","l":"https://en.wikipedia.org/wiki/Hidden_Agenda_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co280a.jpg","s":"Hidden Agenda follows homicide detective Becky Marney and district attorney Felicity Graves as they investigate doubts about a convicted serial killer's guilt. Five years after the Trapper killer's arrest, Finn awaits execution while maintaining his innocence, prompting both women to reexamine the case. Players shape the narrative through a companion smartphone app that connects to the PS4, making choices that affect character relationships, uncover evidence, and determine the true identity of the killer. The game features both single-player story mode and competitive multiplayer, where participants pursue hidden objectives. Through quick-time events, clue searches, and dialogue choices tracked via the app's logbook system, players navigate three chapters of branching storylines that can lead to multiple conclusions, including the possibility of becoming a suspect themselves."},{"t":"Hidden Dragon: Legend","p":["PlayStation 4"],"r":"September 19"},{"t":"Hidden Star in Four Seasons","p":["Windows"],"d":"Team Shanghai Alice","u":"Team Shanghai Alice","r":"August 11, 2017","l":"https://en.wikipedia.org/wiki/Hidden_Star_in_Four_Seasons"},{"t":"High Hell","p":["Windows","macOS"],"g":"FPS","r":"October 23","l":"https://en.wikipedia.org/wiki/High_Hell"},{"t":"Hiveswap","p":["Windows","macOS","Linux"],"g":"Adventure","r":"September 14","l":"https://en.wikipedia.org/wiki/Hiveswap"},{"t":"Hob","p":["Windows","PlayStation 4"],"g":"Action-adventure","r":"September 26","l":"https://en.wikipedia.org/wiki/Hob_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n2l.jpg","s":"Hob is set on a beautiful and dangerous unknown world, with buzzing life above and the whirrs of mysterious machinery below. The more players delve into the world’s design, the more they uncover a planet in peril. Players must learn to survive, understand their true purpose through acquiring skills, and ultimately transform the nature of the world itself.\n\nHob is presented without text or dialogue. Narrative is revealed as players explore and interact with their mysterious planet, and the strange life forms that inhabit it. Hob features smooth controller gameplay, multi-layered puzzles, and striking visuals."},{"t":"Hollow Knight","p":["Windows"],"g":"Metroidvania","r":"February 24","l":"https://en.wikipedia.org/wiki/Hollow_Knight","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobfzp.jpg","s":"A 2D metroidvania with an emphasis on close combat and exploration in which the player enters the once-prosperous now-bleak insect kingdom of Hallownest, travels through its various districts, meets friendly inhabitants, fights hostile ones and uncovers the kingdom's history while improving their combat abilities and movement arsenal by fighting bosses and accessing out-of-the-way areas."},{"t":"Home Sweet Home","p":["Windows"],"d":"Yggdrazil Group","u":"Yggdrazil Group","g":"Survival horror","r":"September 27, 2017","l":"https://en.wikipedia.org/wiki/Home_Sweet_Home_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z2u.jpg","s":"Home Sweet Home is a first-person horror adventure game based on Thai myths and beliefs. The core gameplay focuses on storytelling and stealth to avoid perilous spirits hunting you. Moreover, few puzzles are added into the game, making gameplay more various. While playing this game, you will be thrilled by a horror Thai atmosphere, unpredictable scary moments and challenging gameplay!"},{"t":"Homescapes","p":["Android","iOS","Windows","macOS"],"d":"Playrix","u":"Playrix","g":"Puzzle","r":"August 2017","l":"https://en.wikipedia.org/wiki/Homescapes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3vyt.jpg","s":"Homescapes is a mobile game developed by Playrix that combines match-3 puzzle mechanics with home renovation simulation. In the game, players join the main character, Austin the butler, in his quest to help his parents restore their old family mansion to its former glory. The gameplay primarily revolves around completing match-3 puzzle levels to earn stars, which are then used to progress in the renovation process."},{"t":"Horizon Zero Dawn","p":["PlayStation 4"],"g":"Action RPG","r":"February 28","l":"https://en.wikipedia.org/wiki/Horizon_Zero_Dawn","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2una.jpg","s":"Welcome to a vibrant world rich with the beauty of nature – but inhabited by awe-inspiring, highly advanced machines. As a young machine hunter named Aloy, you must unravel the mysteries of this world and find your own destiny."},{"t":"Horizon Zero Dawn: The Frozen Wilds","p":["PlayStation 4"],"d":"Guerrilla Games","u":"Sony Interactive Entertainment","g":"Action role-playing","r":"November 7, 2017","l":"https://en.wikipedia.org/wiki/Horizon_Zero_Dawn:_The_Frozen_Wilds"},{"t":"HQ","p":["iOS","Android"],"u":"Intermedia Labs","g":"Trivia game","r":"August 26, 2017","l":"https://en.wikipedia.org/wiki/HQ_(video_game)"},{"t":"Human Resource Machine","p":["Nintendo Switch"],"g":"Puzzle","r":"March 3","l":"https://en.wikipedia.org/wiki/Human_Resource_Machine"},{"t":"Husk","p":["Windows"],"r":"February 3"},{"t":"I am Setsuna","p":["Nintendo Switch"],"g":"RPG","r":"March 3","l":"https://en.wikipedia.org/wiki/I_am_Setsuna"},{"t":"I and Me","p":["Nintendo Switch","Windows"],"d":"Wish Fang","u":"Ratalaika Games","g":"Puzzle-platform","r":"July 6, 2017","l":"https://en.wikipedia.org/wiki/I_and_Me","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24we.jpg","s":"If there were another me, Observing myself from the perspective of a spectator, How would I regard another me?"},{"t":"Icey","p":["PlayStation 4"],"g":"Hack and slash","r":"August 8"},{"t":"Ikemen Vampire","p":[],"l":"https://en.wikipedia.org/wiki/Ikemen_Vampire"},{"t":"Impact Winter","p":["Windows"],"r":"May 23"},{"t":"Incidence","p":["iOS"],"g":"Sports","r":"June 1","l":"https://en.wikipedia.org/wiki/Incidence_(video_game)"},{"t":"Infinite Stratos","p":[],"l":"https://en.wikipedia.org/wiki/Infinite_Stratos"},{"t":"Injustice 2","p":["PlayStation 4","Xbox One"],"g":"Fighting","r":"May 16","l":"https://en.wikipedia.org/wiki/Injustice_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xym.jpg","s":"Power up and build the ultimate version of your favorite DC legends in INJUSTICE 2. With a massive selection of DC Super Heroes and Super-Villains, INJUSTICE 2 allows you to equip every iconic character with unique and powerful gear earned throughout the game. Experience an unprecedented level of control over how your favorite characters look, how they fight, and how they develop across a huge variety of game modes. This is your super Hero. Your Journey. Your Injustice."},{"t":"Into the Dead 2","p":["iOS","Android"],"d":"PikPok","u":"PikPok, Versus Evil, Gearbox Publishing","g":"First person shooter","r":"August 9, 2017","l":"https://en.wikipedia.org/wiki/Into_the_Dead_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86sm.jpg","s":"Journey through the zombie apocalypse in a race to save your family. Arm yourself with an arsenal of powerful weapons and do whatever it takes to survive. Maim, mow down, and massacre the Dead - anything to keep moving! In a world where no one is safe, how far will you go to make it out alive?"},{"t":"Iron Marines","p":["iOS","Android"],"g":"RTS","r":"September 14","l":"https://en.wikipedia.org/wiki/Iron_Marines"},{"t":"Ittle Dew 2+","p":["Nintendo Switch"],"g":"Action-adventure, RPG","r":"November 14","l":"https://en.wikipedia.org/wiki/Ittle_Dew_2%2B"},{"t":"JoJo's Bizarre Adventure: Diamond Records","p":["Android","iOS"],"d":"Bandai Namco Entertainment","u":"Bandai Namco Entertainment","g":"Action","r":"February 20, 2017","l":"https://en.wikipedia.org/wiki/JoJo's_Bizarre_Adventure:_Diamond_Records","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5qbc.jpg","s":"JoJo's Bizarre Adventure: Diamond Records is a 3D action video game developed and published by Bandai Namco Entertainment for iOS and Android, and was released on February 20, 2017 in Japan. It is based on the JoJo's Bizarre Adventure anime series, with the main portion of the game consisting of quests based on the series' story. The player controls assembles teams of JoJo's Bizarre Adventure characters, and play through the quests with the goal of knocking out enemy characters. The game uses a free-to-play model, with the player acquiring new characters and items through a gasha mechanic."},{"t":"Juanito Arcade Mayhem","p":["Windows","Android","iOS"],"d":"Game Ever Studio","u":"Game Ever Studio","g":"Action","r":"August 3, 2017","l":"https://en.wikipedia.org/wiki/Juanito_Arcade_Mayhem","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21ao.jpg","s":"Juanito Arcade Mayhem revives all the retro classics using the mechanics made popular by Super Pang. Don your finest pyjamas and help Juanito defend our favorite games from the alien Clonocell invasion!"},{"t":"Just Dance 2017","p":["Nintendo Switch"],"g":"Rhythm","r":"March 3","l":"https://en.wikipedia.org/wiki/Just_Dance_2017"},{"t":"Just Dance 2018","p":["PlayStation 4","PlayStation 3","Xbox One","Xbox 360","Nintendo Switch","Wii U","Wii"],"g":"Rhythm","r":"October 24","l":"https://en.wikipedia.org/wiki/Just_Dance_2018"},{"t":"Justice Duel","p":["Nintendo Entertainment System"],"d":"Mega Cat Studios","u":"Mega Cat Studios","g":"Platform","l":"https://en.wikipedia.org/wiki/Justice_Duel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kod.jpg","s":"Take to the skies on the back of scientifically-engineered eagles and joust against AI patriots from America’s past. Dodge fireworks, bear traps, and dead presidents in 4-Player Local Co-op! The history might be wrong, but the justice is so right.\n\n- Historically Inaccurate Combat\n- 4 Player Local Co-op\n- Campaign Mode"},{"t":"Jydge","p":["Android","iOS","Linux","macOS","Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"10tons","u":"10tons","g":"Twin-stick shooter","r":"October 3, 2017","l":"https://en.wikipedia.org/wiki/Jydge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/emd0bet1ecnr5wshpr6o.jpg","s":"Build your Jydge. Enter Edenbyrg. Get out alive.\n\nJydge is a lawful but awful roguehate top-down shooter where you get to build your own cybernetic Jydge and eradicate crime in the never-sleeping megacity of Edenbyrg."},{"t":"Kamen Rider: Climax Fighters","p":["PlayStation 4"],"r":"December 7"},{"t":"Kamiko","p":["Nintendo Switch"],"d":"Skipmore","u":"Flyhigh Works","g":"Action","r":"April 13, 2017","l":"https://en.wikipedia.org/wiki/Kamiko","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21ap.jpg","s":"KAMIKO is a game styled around Japanese Shinto beliefs.\n\nFight as priestesses called \"KAMIKO\" and battle against demons while solving puzzles to make your way through the stages.\n\nLook no further if you are looking for an arcade action game with a twist!\n\nEach stage has several Torii (gates) which are magically sealed. Find a way to break all the seals to make your way to the stage boss.\n\nAnother fun and easy original created by indie games SKIPMORE."},{"t":"Ken Follett's The Pillars of the Earth","p":["Linux","macOS","Windows","PlayStation 4","Xbox One"],"d":"Daedalic Entertainment","u":"Daedalic Entertainment","g":"Point-and-click adventure","r":"August 16, 2017","l":"https://en.wikipedia.org/wiki/Ken_Follett's_The_Pillars_of_the_Earth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co252a.jpg","s":"England, 12th century: Philip the monk becomes Prior of the small abbey of Kingsbridge. At the same time, a boy called Jack is raised by his outlawed mother in the woods. His apprenticeship as a stonemason paves his way to become a great architect. Soon, his steps lead him to Kingsbridge where he will build one of the greatest cathedrals England has ever seen. Aliena and Richard have to survive on their own, after the sibling's father, the Earl of Shiring, has been incarcerated and murdered. Aliena vows to make her brother the rightful heir and Earl of Shiring. Like Jack, their way leads them to Kingsbridge. Aliena puts her expertise as a tradeswoman to good use, supporting the cathedral's construction and falls in love with Jack. But Kingsbridge and its people are in grave danger. Philip's rivals, Bishop Waleran and Wiliam, a vengeful noble rejected by Aliena, see the town and its rise to importance as a thorn in their flesh. They want to see Kingsbridge burn.\n\nThe game-adaption of the world-bestseller \"The Pillars of the Earth\" is the first co-operative project of Daedalic Entertainment and Bastei Lübbe. This game will be more than just complementary media to the book and will instead retell the story in a new, interactive way. A team of about 20 people works to create a multi-platform adaption of this bestseller. The writers are also in contact and co-operation with the Follett Office and Ken Follett himself. Daedalic is the only studio at the time adapting such an epic reading-experience into an interactive format.\n\nThe game itself will be released in 2017, at the same time the third novel of the Kingsbridge-Series will be published. The game will be internationally available for PC, Mac, Linux, PS4, Xbox One and mobile devices."},{"t":"Kingdom Hearts 0.2: Birth by Sleep - A Fragmentary Passage","p":["PlayStation 4"],"d":"Square Enix Business Division 3","u":"Square Enix","g":"Role-playing (RPG), Hack and slash/Beat 'em up","r":"January 12, 2017","l":"https://www.igdb.com/games/kingdom-hearts-0-dot-2-birth-by-sleep-a-fragmentary-passage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8m20.jpg","s":"A short sequel to Kingdom Hearts Birth By Sleep that partially takes place during the events of the first Kingdom Hearts, A fragmentary passage gets its name from a hidden ending to BBS and tells the story of Master Aqua's ten-year journey through the Realm of Darkness. 0.2 acts as a prologue to the upcoming Kingdom Hearts III, and also as a demo of Kingdom Hearts traversal, combat, and graphics in Unreal Engine 4 as it will appear in KH3. This game is only playable as part of the collection Kingdom Hearts HD 2.8 Final Chapter Prologue."},{"t":"Kingdom Hearts Dream Drop Distance HD","p":["PlayStation 4"],"d":"Square Enix Business Division 3","u":"Square Enix","g":"Fighting, Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"January 12, 2017","l":"https://www.igdb.com/games/kingdom-hearts-dream-drop-distance-hd","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8m1w.jpg","s":"Kingdom Hearts Dream Drop Distance HD is a full HD remaster of Kingdom Hearts 3D: Dream Drop Distance designed for the PlayStation 4. It was released as part of a package of three games entitled Kingdom Hearts HD 2.8 Final Chapter Prologue.\n\nThe game is largely the same as its Nintendo 3DS counterpart, but includes some additional features as well as alterations designed to adapt the game to the PS4. The conversion from two screens to one is the most notable of the changes seen. Little has changed in terms of gameplay. However, three new Dream Eaters have been introduced and minor game features have been altered to adapt to the PS4."},{"t":"Kingdom Hearts HD 1.5 Remix","p":["PlayStation 4"],"g":"Action RPG","r":"March 28","l":"https://en.wikipedia.org/wiki/Kingdom_Hearts_HD_1.5_Remix"},{"t":"Kingdom Hearts HD 2.5 Remix","p":["PlayStation 4"],"g":"Action RPG","r":"March 28","l":"https://en.wikipedia.org/wiki/Kingdom_Hearts_HD_2.5_Remix"},{"t":"Kingdom Hearts HD 2.8 Final Chapter Prologue","p":["PlayStation 4"],"g":"Action RPG","r":"January 24","l":"https://en.wikipedia.org/wiki/Kingdom_Hearts_HD_2.8_Final_Chapter_Prologue"},{"t":"Kingdoms and Castles","p":["Windows"],"r":"July 20","l":"https://en.wikipedia.org/wiki/Kingdoms_and_Castles"},{"t":"Kingsway","p":["Windows"],"u":"Adult Swim Games, Andrew Morrish","g":"Role-playing","r":"July 18, 2017","l":"https://en.wikipedia.org/wiki/Kingsway_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/hlnrp1snyn6rtjdsdrdf.jpg","s":"Kingsway is the #1 operating system for daily tasks such as skeleton smashing and loot-organizing. Trouble sorting through all your potions and swords? Don't worry! Kingsway can help you manage, and with an easy to use interface you'll have time leftover for a peaceful stroll through the underworld."},{"t":"Kirby's Blowout Blast","p":["Nintendo 3DS"],"g":"Action, Platformer","r":"July 6","l":"https://en.wikipedia.org/wiki/Kirby%27s_Blowout_Blast"},{"t":"Knack II","p":["PlayStation 4"],"g":"Action, Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Knack_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4le9.jpg","s":"Meet Knack, a little guy with surprising moves and the ability to transform from big to small and back again in this family-friendly adventure from the developers at PlayStation."},{"t":"Knee Deep","p":["Windows","PlayStation 4","Xbox One","macOS","Linux"],"d":"Prologue Games","u":"Wales Interactive","g":"Adventure","r":"January 31, 2017","l":"https://en.wikipedia.org/wiki/Knee_Deep_(video_game)"},{"t":"Knowledge is Power","p":["PlayStation 4"],"d":"Wish Studios","u":"Sony Interactive Entertainment","g":"Party","r":"October 24, 2017","l":"https://en.wikipedia.org/wiki/Knowledge_is_Power_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nhc.jpg","s":"A trivia game in the PlayLink line of PlayStation 4 games that utilize mobile devices as controllers."},{"t":"Kona","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"g":"Puzzle, Adventure, Indie","r":"March 17","l":"https://www.igdb.com/games/kona","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vwz.jpg","s":"A story-driven survival game set in 1970's Quebec in which Carl Flaubert, a private detective sent to the fictional Atamipek Lake to investigate a deceptively simple case, must solve the mystery surrounding the region while surviving the harsh Northern Canadian winter."},{"t":"Kono Subarashii Sekai ni Shukufuku o! Kono Yokubukai Game ni Shinpan o!","p":["PlayStation 4","PlayStation Vita"],"r":"September 7","l":"https://en.wikipedia.org/wiki/KonoSuba"},{"t":"Kowloon's Gate VR: Suzaku","p":["PlayStation VR"],"r":"October 26"},{"t":"Kyoei Toshi","p":["PlayStation 4"],"d":"Granzella","u":"Bandai Namco Entertainment","g":"Survival","r":"October 19, 2017","l":"https://en.wikipedia.org/wiki/Kyoei_Toshi","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28a8.jpg","s":"Disaster Report-esque game starring villains from disaster movies."},{"t":"L.A. Noire","p":["Nintendo Switch","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"November 14","l":"https://en.wikipedia.org/wiki/L.A._Noire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ld0.jpg","s":"L.A. Noire for PlayStation 4 and Xbox One delivers the complete original game and all additional downloadable content with a range of technical enhancements for greater visual fidelity and authenticity, including enhanced lighting and clouds, new cinematic camera angles, high resolution textures and more. L.A. Noire plays natively in 1080p for the PlayStation 4 and Xbox One consoles, and stunning 4K for PlayStation 4 Pro and Xbox One X, capturing the grit and grime of the City of Angels like never before."},{"t":"Last Day of June","p":["PlayStation 4","Windows"],"d":"Ovosonico","u":"505 Games","g":"Adventure, puzzle","r":"August 31, 2017","l":"https://en.wikipedia.org/wiki/Last_Day_of_June","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q7s.jpg","s":"A deep, interactive adventure about love and loss, beautifully depicted and offering an intense cinematic experience. What would you do to save the one you love?"},{"t":"Last Day on Earth: Survival","p":["Android","iOS"],"d":"Kefir!","u":"Kefir!","g":"Shooter, Role-playing (RPG), Simulator, Strategy, Hack and slash/Beat 'em up, Adventure","r":"May 25, 2017","l":"https://www.igdb.com/games/last-day-on-earth-survival","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rgn.jpg","s":"Last Day on Earth is a free multiplayer zombie survival strategy game, where all survivors are driven by one target: stay alive and survive as long as you can and shoot walking dead zombies. There is no place left for friendship, love and compassion. A deadly plague pandemic has turned the world into a dead zone. You can trust only yourself in this post apocalyptic world infected with walking dead zombies."},{"t":"Late Shift","p":["macOS","Windows","PlayStation 4","Xbox One"],"d":"CtrlMovie","u":"Wales Interactive","g":"Adventure, interactive movie","r":"April 18, 2017","l":"https://en.wikipedia.org/wiki/Late_Shift_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1njk.jpg","s":"Late Shift is a high stakes FMV crime thriller. After being forced into the robbery of a lucrative auction house, mathematics student Matt is left proving his innocence in the brutal London heist. Your choices will have consequences from the very start, right through to the very end. One small decision could change the entire outcome in a choose-your-own-adventure style gameplay that can lead to one of seven conclusions."},{"t":"LawBreakers","p":["Windows","PlayStation 4"],"g":"FPS","r":"August 8","l":"https://en.wikipedia.org/wiki/LawBreakers"},{"t":"Layton's Mystery Journey","p":["Nintendo 3DS"],"g":"Puzzle, Adventure","r":"October 6","l":"https://en.wikipedia.org/wiki/Layton%27s_Mystery_Journey"},{"t":"Leaving Lyndow","p":["Windows","macOS","PlayStation 4"],"d":"Eastshade Studios","u":"Eastshade Studios","g":"Adventure","r":"February 8, 2017","l":"https://en.wikipedia.org/wiki/Leaving_Lyndow","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wim.jpg","s":"Leaving Lyndow is a short, first-person exploration adventure game, set in the Eastshade universe. It's Clara's last day on the island where she grew up. With high honors, she's graduated and fulfilled her childhood dream of joining the Guild of Maritime Exploration. She needs to complete preparations, visit her favorite places, and say her goodbyes before leaving on a journey she may not return from. *dangerous journey not included*"},{"t":"Legends of Equestria","p":["Windows","macOS","Linux"],"d":"Legends of Equestria Team","g":"Massively multiplayer online role-playing game","r":"September 9, 2017","l":"https://en.wikipedia.org/wiki/Legends_of_Equestria","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobmj2.jpg","s":"Legends of Equestria is a MMORPG where players play as a pony in a magical world filled with friendship and many adventures."},{"t":"Legion TD","p":[],"l":"https://en.wikipedia.org/wiki/Legion_TD"},{"t":"Lego City Undercover","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"April 4","l":"https://en.wikipedia.org/wiki/Lego_City_Undercover"},{"t":"Lego Marvel Super Heroes 2","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"November 14","l":"https://en.wikipedia.org/wiki/Lego_Marvel_Super_Heroes_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27zd.jpg","s":"Lego Marvel Super Heroes 2 is a Lego-themed action-adventure video game developed by Traveller's Tales. It is the sequel to 2013's Lego Marvel Super Heroes and the third instalment of the Lego Marvel franchise.\n\nWith the core gameplay following the same style of past Lego titles, the game features the ability to manipulate time and a four-player competitive Super Hero battle mode. Lego Marvel Super Heroes 2's storyline centers around superheroes from different eras and realities of the Marvel Universe as they fight against the time-travelling villain Kang the Conqueror in a battle across space and time."},{"t":"Lego Worlds","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Sandbox","r":"March 7","l":"https://en.wikipedia.org/wiki/Lego_Worlds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1j95.jpg","s":"LEGO Worlds is an open environment of procedurally-generated Worlds made entirely of LEGO bricks which you can freely manipulate and dynamically populate with LEGO models. Create anything you can imagine one brick at a time, or use large-scale landscaping tools to create vast mountain ranges and dot your world with tropical islands. Drop in prefabricated structures to build and customize any world to your liking. Explore using helicopters, dragons, motorbikes or even gorillas and unlock treasures that enhance your gameplay. Watch your creations come to life through characters and creatures that interact with you and each other in unexpected ways. In LEGO Worlds, anything is possible!"},{"t":"Letterpress","p":["Android"],"g":"TBS, Word","r":"August 25","l":"https://en.wikipedia.org/wiki/Letterpress_(video_game)"},{"t":"Lichtspeer","p":["PlayStation Vita"],"g":"Action","r":"April 11","l":"https://en.wikipedia.org/wiki/Lichtspeer"},{"t":"Life Is Strange: Before the Storm","p":["PlayStation 4","Windows","Xbox One","Linux","macOS","Android","iOS","Nintendo Switch"],"d":"Deck Nine","u":"Square Enix","g":"Adventure","r":"August 31, 2017","l":"https://en.wikipedia.org/wiki/Life_Is_Strange:_Before_the_Storm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1twj.jpg","s":"Life is Strange: Before the Storm is a new three part standalone story adventure set three years before the events of the first game. This time play as Chloe Price, a rebel who forms an unlikely friendship with Rachel Amber in dramatic new story in the BAFTA award winning franchise."},{"t":"Life Is Strange: Before the Storm — Episode 1","p":["Windows","PlayStation 4","Xbox One"],"g":"Graphic adventure","r":"August 31"},{"t":"Life Is Strange: Before the Storm — Episode 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Graphic adventure","r":"October 19"},{"t":"Life Is Strange: Before the Storm — Episode 3","p":["Windows","PlayStation 4","Xbox One"],"g":"Graphic adventure","r":"December 20"},{"t":"Light Tracer","p":["PlayStation 4"],"r":"September 26"},{"t":"Lightfield","p":["PlayStation 4","Xbox One"],"r":"September 26","l":"https://en.wikipedia.org/wiki/Lightfield"},{"t":"Linelight","p":["Windows"],"d":"My Dog Zorro","u":"My Dog Zorro","g":"Action, Adventure, Casual, Indie","r":"January 30, 2017","l":"https://store.steampowered.com/app/469790","i":"images/steam-469790.jpg","s":"Linelight is an elegant puzzle game set in a world of lines."},{"t":"Little Inferno","p":["Nintendo Switch"],"g":"Puzzle","r":"March 3","l":"https://en.wikipedia.org/wiki/Little_Inferno"},{"t":"Little Nightmares","p":["Windows","PlayStation 4","Xbox One"],"g":"Puzzle-platformer, Survival horror","r":"April 28","l":"https://en.wikipedia.org/wiki/Little_Nightmares","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rdi.jpg","s":"Little Nightmares is a puzzle-platform horror adventure game developed by Tarsier Studios and published by Bandai Namco Entertainment. Set in a mysterious world, Little Nightmares follows the journey of Six, a hungry little girl who must escape the Maw, an iron vessel inhabited by monstrous, twisted beings."},{"t":"Little Red Lie","p":["Windows","macOS"],"g":"Adventure","r":"July 7","l":"https://en.wikipedia.org/wiki/Little_Red_Lie"},{"t":"Little Witch Academia: Chamber of Time","p":["PlayStation 4"],"g":"Action RPG","r":"November 30"},{"t":"LocoRoco 2 Remastered","p":["PlayStation 4"],"g":"Puzzle-platformer","r":"December 9","l":"https://en.wikipedia.org/wiki/LocoRoco_2"},{"t":"LocoRoco Remastered","p":["PlayStation 4"],"g":"Puzzle-platformer","r":"May 9","l":"https://en.wikipedia.org/wiki/LocoRoco"},{"t":"Lode Runner Legacy","p":["Windows"],"g":"Platform, Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Lode_Runner_Legacy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27z0.jpg","s":"Lode Runner Legacy is the latest edition in the popular Lode Runner series. Players control “Runner” to recover stolen gold while avoiding enemies and minefields. Enjoy the ingenious balance of puzzle and action gameplay, an updated Voxel visual style and powerful game editors."},{"t":"Log Jammers","p":["Windows","Xbox One","PlayStation 4","Nintendo Switch","Nintendo Entertainment System"],"d":"Mega Cat Studios","u":"Mega Cat Studios","g":"Sports","l":"https://en.wikipedia.org/wiki/Log_Jammers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3j6y.jpg","s":"Log Jammers is a homebrew arcade sports game. It is similar to the PC and console versions of the same name and by the same developer. Those versions are not identical and described as an \"upmake\" of the NES version. The game borrows elements from Windjammers, which served as an inspiration.\n\nPlayers select one of six characters from a cast with names such as Rad Carlton, Bruiser Bogardus, Hot Foot Francis, Sparerib Boneapart, Mayo Monsoon or Ollie Oilsack. There are also multiple environments and different game modes. The characters are described as lumberjacks. Matches take place on a fixed screen view shown from an elevated position. Characters are standing on rolling logs and throw an axe that acts like a ball.\n\nIn a typical tournament different opponents need to be defeated one after the other. Points are scored by throwing the axe into the goal area behind the opponent. This zone is different for each environment. Sometimes there is only a single, large goal area, while another environment has three zones for five, two and five points respectively. In some levels like North Pool the middle part is entirely open, while in others like Mount Olympus the axe can only be thrown through a few open passages.\n\nThe opponent guards these areas and attempts to catch or bounce back the axe to try the same on the other side. A set is won when someone reaches twelve points. The best of three sets wins a match. Special items appear during matches such as stars (use a signature throw different for each character), magnets (increase catching range for five seconds), ice cubes (decrease the opponent's movement speed for a short amount of time) and oil (the axe cannot be caught for five seconds and will bounce back instead, and at a reduced speed). There are counters for some power-ups. For instance, when the signature throw is caught by the opponent, their signature throw becomes active right away.\n\nThe game supports competitive multiplayer against another opponent on the same screen. The game comes in a box with a green cartridge and a full colour manual."},{"t":"Lone Echo","p":["Windows","Meta Quest"],"g":"Adventure","r":"July 20","l":"https://en.wikipedia.org/wiki/Lone_Echo"},{"t":"Loot Rascals","p":["Windows","PlayStation 4"],"r":"March 7","l":"https://en.wikipedia.org/wiki/Loot_Rascals"},{"t":"Lord of Vermilion","p":["Arcade"],"d":"Think Garage","u":"Square Enix","g":"Fantasy collectible card game","l":"https://en.wikipedia.org/wiki/Lord_of_Vermilion"},{"t":"Lost Dimension","p":["Windows"],"g":"Tactical RPG","r":"October 30","l":"https://en.wikipedia.org/wiki/Lost_Dimension"},{"t":"Lumo","p":["Nintendo Switch"],"g":"Puzzle-platformer","r":"November 16","l":"https://en.wikipedia.org/wiki/Lumo_(video_game)"},{"t":"Lupinball","p":["Windows","macOS"],"d":"Craftven","u":"Craftven","g":"Bullet hell dodgeball","r":"August 17, 2017","l":"https://en.wikipedia.org/wiki/Lupinball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qm2.jpg","s":"Werewolves shooting fireballs at each other! Survive each round as it becomes more and more chaotic from everyone's fireballs bouncing around non-stop. Be the last wolf standing in this hilarious 2-4 player arcade deathmatch, local or online!"},{"t":"Madden NFL 18","p":["PlayStation 4","Xbox One"],"g":"Sports","r":"August 25","l":"https://en.wikipedia.org/wiki/Madden_NFL_18","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc9ho.jpg","s":"Madden NFL 18 takes a significant visual leap with the power of the Frostbite engine. See stunning new stadium exteriors surrounded by vast cityscapes and watch the spectacle of NFL gameday come to life in the most photorealistic game to date. Play each matchup to your specifications by selecting from three new Play Styles or play the best real world match ups each week in Play Now Live! With the introduction of even more ways to play, coupled with your favorite modes, Madden Ultimate Team and Franchise, this is Madden like you’ve never seen before."},{"t":"Mage: The Ascension – Refuge","p":["Windows","macOS","Linux","Android","iOS"],"g":"Interactive fiction","r":"February 15"},{"t":"Mages of Mystralia","p":["Windows","PlayStation 4"],"g":"Action-adventure","r":"May 18","l":"https://en.wikipedia.org/wiki/Mages_of_Mystralia"},{"t":"Magia Record","p":["Android","iOS"],"g":"Role-playing (RPG), Turn-based strategy (TBS)","l":"https://en.wikipedia.org/wiki/Magia_Record","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r0y.jpg","s":"Puella Magi Madoka Magica Side Story: Magia Record is a mobile game developed by f4samurai, and is part of the Puella Magi Madoka Magica franchise."},{"t":"MagiCat","p":["Windows"],"g":"Puzzle-platformer","r":"August 22"},{"t":"Mainlining","p":["Windows"],"d":"Rebelephant","u":"Merge Games","g":"Point and click adventure","r":"January 26, 2017","l":"https://en.wikipedia.org/wiki/Mainlining","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24yx.jpg","s":"After MI7 has been hacked, your primary goal is to bring a cyber-criminal network to justice. Played entirely from within the environment of your computer's desktop, Mainlining is a thrilling point and click hacking adventure that features a gripping narrative which will have you hooked from the very first case."},{"t":"Manga Time Kirara","p":[],"l":"https://en.wikipedia.org/wiki/Manga_Time_Kirara"},{"t":"Mario & Luigi: Superstar Saga + Bowser's Minions","p":["Nintendo 3DS"],"g":"RPG","r":"October 6"},{"t":"Mario + Rabbids Kingdom Battle","p":["Nintendo Switch"],"g":"TBT , Tactical RPG","r":"August 29","l":"https://en.wikipedia.org/wiki/Mario_%2B_Rabbids_Kingdom_Battle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2274.jpg","s":"This is the story of an unexpected encounter between Mario and the irreverent Rabbids. The Mushroom Kingdom has been torn apart by a mysterious vortex, transporting the Rabbids into the once-peaceful area, splintering this beloved land. To bring order back to the Kingdom, Mario, Luigi, Princess Peach, and Yoshi team up with Rabbids heroes in a journey through four different worlds."},{"t":"Mario Kart 8 Deluxe","p":["Nintendo Switch"],"d":"Nintendo EPD","u":"Nintendo","g":"Racing (kart)","r":"April 28, 2017","l":"https://en.wikipedia.org/wiki/Mario_Kart_8","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co213p.jpg","s":"Hit the road with the definitive version of Mario Kart 8 and play anytime, anywhere! Race your friends or battle them in a revised battle mode on new and returning battle courses. Play locally in up to 4-player multiplayer in 1080p while playing in TV Mode. Every track from the Wii U version, including DLC, makes a glorious return. Plus, the Inklings appear as all-new guest characters, along with returning favorites, such as King Boo, Dry Bones, and Bowser Jr.!"},{"t":"Mario Party: The Top 100","p":["Nintendo 3DS"],"g":"Party","r":"November 10"},{"t":"Mario Sports Superstars","p":["Nintendo 3DS"],"g":"Sports","r":"March 24","l":"https://en.wikipedia.org/wiki/Mario_Sports_Superstars"},{"t":"Marvel vs. Capcom: Infinite","p":["Windows","PlayStation 4","Xbox One"],"g":"Fighting","r":"September 19","l":"https://www.igdb.com/games/marvel-vs-capcom-infinite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wqa.jpg","s":"Marvel vs. Capcom: Infinite will feature a variety of exciting and accessible single player modes and rich multi-player content for new players and longtime fans alike. In addition to single player Arcade, Training and Mission modes, a visually stunning and immersive cinematic Story Mode will put players at the center of both universes as they battle for survival against a sinister new threat. Marvel vs. Capcom: Infinite is being built to highlight a combination of iconic locations and fan favorite characters from both universes, including Captain Marvel and Iron Man from the Marvel side, and Ryu and Mega Man X from Capcom."},{"t":"Mary Skelter: Nightmares","p":["PlayStation Vita"],"g":"RPG, Dungeon crawl","r":"September 19"},{"t":"Mass Effect: Andromeda","p":["Windows","PlayStation 4","Xbox One"],"g":"Action RPG","r":"March 21","l":"https://www.igdb.com/games/mass-effect-andromeda--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co39vk.jpg","s":"A new adventure awaits in the Mass Effect universe. With stunning visuals and a new galaxy to discover, BioWare delivers the next generation of space exploration.\n\nCommander Shepard's story may be over, but there are many more stories to tell in the Mass Effect universe. Mass Effect Andromeda will be set in a new galaxy, with new characters, new quests and a whole load of new consequence-laden decisions to make.\n\nMass Effect: Andromeda takes you to the Andromeda galaxy, far beyond the Milky Way. There, you'll lead our fight for a new home in hostile territory - where WE are the aliens.\n\nPlay as the Pathfinder - a leader of a squad of military-trained explorers - with deep progression and customisation systems. This is the story of humanity’s next chapter, and your choices throughout the game will ultimately determine our survival in the Andromeda Galaxy.\n\nAs you unfold the mysteries of the Andromeda Galaxy and the hope for humanity lies on your shoulders – You must ask yourself… How far will you go?\n\nKey Features:\n\nReturn to the Mass Effect universe. Lead the first humans in Andromeda on a desperate search for our new home. In this new chapter of Mass Effect, meet and recruit all-new, interesting characters caught up in an epic space saga filled with mystery and galactic conflict.\n\nFight for survival. Battle with your Pathfinder team against terrifying enemies and creatures. New additions like destructible environments, boosted jumps for added verticality, and all-new weapons and Biotics make combat more thrilling than ever.\n\nBuild your hero. Create a formidable hero with amazing weapons, powers and tech. A much more flexible skill and weapon progression tree means you can replicate your play style to make you unstoppable against new, powerful alien enemies.\n\nExplore a new galaxy. Chart your own course in a dangerous new region. Unravel the mysteries of the Andromeda galaxy as you discover rich, alien worlds in the search for humanity’s new home."},{"t":"Matterfall","p":["PlayStation 4"],"g":"Shooter","r":"August 15","l":"https://en.wikipedia.org/wiki/Matterfall"},{"t":"Max: The Curse of Brotherhood","p":["Nintendo Switch"],"g":"Puzzle-platformer","r":"December 21"},{"t":"Mega Man 2.5D","p":["Windows"],"g":"Platform","r":"January 31, 2017","l":"https://en.wikipedia.org/wiki/Mega_Man_2.5D","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ob8.jpg","s":"Mega Man 2.5D is a fangame developed by a small team of obsessive Mega Man fans. It began in 2009 as an animated proof-of-concept. This got a surprising amount of positive response, and because of this a couple of us got together with the goal of making a playable game out of it.\n\nThere are mainly two things that set Mega Man 2.5D apart from most other Mega Man games. The first is the co-op mode, where two players team up to take on Dr. Wily. The other is the use of camera perspective changes which is featured a lot in the single-player mode of the game."},{"t":"Mega Man Maker","p":["Windows"],"d":"Mega Man Maker Team","g":"Platform, level editor","r":"July 15, 2017","l":"https://en.wikipedia.org/wiki/Mega_Man_Maker","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3w2x.jpg","s":"Based on Capcom's Mega Man series, players are able to create and share their own Mega Man levels online such as a traditional stage from the Mega Man series, puzzle levels and automatic levels (which were made popular in Nintendo's Super Mario Maker) and are able to play other people's levels either by searching their level IDs or the level name. The available categories are \"newest\", \"oldest\", \"worst rated\", \"best rated\", \"popular\" and \"most played\" with the number of upvotes and downs votes affecting best rated and worst rated respectively. It is commonly referred to as a Super Mario Maker alternative by Mega Man fans."},{"t":"Megaton Rainfall","p":["PlayStation 4","PlayStation VR"],"g":"Action","r":"October 17","l":"https://en.wikipedia.org/wiki/Megaton_Rainfall"},{"t":"Memoranda","p":["Windows","macOS","Linux"],"r":"January 25"},{"t":"Metroid: Samus Returns","p":["Nintendo 3DS"],"g":"Action-adventure","r":"September 15","l":"https://www.igdb.com/games/metroid-samus-returns","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3j82.jpg","s":"Metroid: Samus Returns is a remake of Metroid 2: Return of Samus.\nIt uses a 3D graphic style with a side view camera that zooms in and changes for cutscenes. It also has new mechanics, items, and abilities.\n\n\"Brave the hostile terrain of an alien planet teeming with vicious life forms as legendary bounty hunter Samus Aran. Her mission? Terminate the Metroid menace in this masterful reimagining of her 1991 Game Boy adventure. Samus Aran’s arsenal has been enhanced with new moves and abilities that are sure to help her face the deadly surprises that await. This intense, side-scrolling action platformer is a great entry point into the Metroid franchise and perfect for returning fans as well, and it’s available only on the Nintendo 3DS family of systems.\""},{"t":"Metropolis: Lux Obscura","p":["Nintendo Switch","Windows","PlayStation 4","PlayStation Vita","Xbox One"],"d":"Ktulhu Solutions","u":"Ktulhu Solutions/Sometimes You","g":"Adventure, match-three","r":"October 11, 2017","l":"https://en.wikipedia.org/wiki/Metropolis:_Lux_Obscura","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3nuz.jpg","s":"Metropolis Lux Obscura is a unique game with a film noir atmosphere, seductive wanton women, and dirty dangerous secrets. Gameplay is based on a motion comic with a non-linear plot mixed with MATCH3 puzzle fights. This city is rotten to the core. You can’t even tell night from day in this hell where big money runs everything. And the best way to prove you’re right is with brute force.\n\nJon Lockhart walked through the prison gates a free man, after spending years imprisoned as the supposed murderer of an old friend. He returned once more to the city where it all started intent on figuring out who it was that framed him for the murder and make them pay in blood for the crime. It'd take some work with the key witness dead, but that just meant he'd have to flush out every rat from hiding. Old friends and new enemies. Search for the truth, for loyalty and sanity - but all you can find here is redemption, betrayal and death.\n\nWelcome to Metropolis."},{"t":"Micro Machines World Series","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"June 30","l":"https://en.wikipedia.org/wiki/Micro_Machines_World_Series"},{"t":"Microsoft Ultimate Word Games","p":["Windows","iOS","Android"],"d":"Microsoft Casual Games","u":"Microsoft Studios","g":"Word puzzle","r":"June 7, 2017","l":"https://en.wikipedia.org/wiki/Microsoft_Ultimate_Word_Games"},{"t":"Middle-earth: Shadow of War","p":["Windows","PlayStation 4","Xbox One"],"g":"Action RPG, Hack and slash","r":"October 10","l":"https://www.igdb.com/games/middle-earth-shadow-of-war","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20pq.jpg","s":"Go behind enemy lines to forge your army, conquer Fortresses and dominate Mordor from within. Experience how the award winning Nemesis System creates unique personal stories with every enemy and follower, and confront the full power of the Dark Lord Sauron and his Ringwraiths in this epic new story of Middle-earth."},{"t":"Mighty Morphin Power Rangers: Mega Battle","p":["PlayStation 4","Xbox One"],"g":"Brawler","r":"January 17"},{"t":"Miitopia","p":["Nintendo 3DS"],"g":"RPG","r":"July 28","l":"https://en.wikipedia.org/wiki/Miitopia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6civ.jpg","s":"Since the dawn of ever, warriors have banded together to fight evil. Now… Mii characters based on your favorite people must unite to do turn-based battle and save Miitopia! Cast them in roles across the kingdom, manage friendships, and give them jobs with distinct stats, abilities, gear, and a custom look. Then behold as awesomeness unfolds! Guide your team of Mii characters on a quest to defeat the Dark Lord and restore the stolen faces of the citizens of Miitopia. As you watch with bated breath, Mii characters will mingle over food, camping, exercise, sleeping arrangements, and yes, combat! In these wild, yet traditional RPG battles, your party’s relationships affect the outcome. Enemies attack while you explore the world map, which is littered with hidden paths and treasures. Talk about a win-win!"},{"t":"Milkmaid of the Milky Way","p":["Windows","macOS","iOS"],"g":"Puzzle, Adventure","r":"January 5","l":"https://en.wikipedia.org/wiki/Milkmaid_of_the_Milky_Way"},{"t":"Million Arthur","p":[],"l":"https://en.wikipedia.org/wiki/Million_Arthur"},{"t":"Mindustry","p":["Windows","macOS","Linux","Android","iOS"],"d":"Anuken","g":"tower defense, 4X, real-time strategy, factory management","l":"https://en.wikipedia.org/wiki/Mindustry","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coabei.jpg","s":"Mindustry is a hybrid tower-defense sandbox factory game. Create elaborate supply chains of conveyor belts to feed ammo into your turrets, produce materials to use for building, and defend your structures from waves of enemies. Features include a map editor, numerous built-in maps, cross-platform multiplayer, and large-scale PvP unit battles."},{"t":"Minecraft","p":["Nintendo Switch"],"g":"Sandbox, Survival","r":"May 11","l":"https://en.wikipedia.org/wiki/Minecraft"},{"t":"Minecraft: Story Mode","p":["Nintendo Switch"],"g":"Graphic adventure, Interactive film","r":"August 22"},{"t":"Minecraft: Story Mode - Season Two","p":["Android","iOS","macOS","Windows","PlayStation 4","Xbox 360","Xbox One"],"d":"Telltale Games, Mojang Studios","u":"Telltale Games","g":"Point-and-click, Adventure","r":"July 11, 2017","l":"https://www.igdb.com/games/minecraft-story-mode-season-two","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vin.jpg","s":"Minecraft: Story Mode - Season Two continues Jesse's saga in a five-part, narrative-driven, episodic game series developed by Telltale in collaboration with Mojang and members of the Minecraft community. Though players' choices from the first season will carry over into season two, this new season will be accessible to both returning fans and newcomers alike. This second season will also include Telltale's unique multiplayer 'Crowd Play' feature, which allows friends and family to engage with the adventure together by helping to decide the direction of the story from any mobile device with an online connection.\n\nNow that Jesse and the gang have vanquished the Wither Storm, saved the world, and become totally super famous heroes, life has gotten a bit more...complicated. With more responsibilities and less time for adventure, old friendships have started to fade -- at least until Jesse's hand gets stuck in a creepy gauntlet that belongs to an ancient underwater temple. Together with old pals and new comrades alike, Jesse embarks on a brand new journey filled with tough choices, good times, and at least one temperamental llama."},{"t":"Mirage: Arcane Warfare","p":["Windows"],"d":"Torn Banner Studios","u":"Torn Banner Studios","g":"Action","r":"May 23, 2017","l":"https://en.wikipedia.org/wiki/Mirage:_Arcane_Warfare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mbg.jpg","s":"Obliterate your enemies with powerful magic or silence them with a sword in Mirage: Arcane Warfare, a multiplayer FPS from the creators of Chivalry: Medieval Warfare. Mirage is a skill-based game that lets you tear your enemies limb from limb with destructive magic and melee combat, while wielding complete control over every slash and spell."},{"t":"MLB The Show 17","p":["PlayStation 4"],"g":"Sports","r":"March 28","l":"https://en.wikipedia.org/wiki/MLB_The_Show_17"},{"t":"Monopoly for Nintendo Switch","p":["Nintendo Switch"],"r":"October 31","l":"https://en.wikipedia.org/wiki/Monopoly_for_Nintendo_Switch"},{"t":"Monster Hunter Stories","p":["Nintendo 3DS"],"g":"RPG","r":"September 8","l":"https://en.wikipedia.org/wiki/Monster_Hunter_Stories"},{"t":"Monster Jam: Crush It!","p":["Nintendo Switch"],"r":"October 31"},{"t":"Monster of the Deep: Final Fantasy XV","p":["PlayStation 4"],"d":"Square Enix Business Division 2","u":"Square Enix","g":"Simulation","r":"November 21, 2017","l":"https://en.wikipedia.org/wiki/Monster_of_the_Deep:_Final_Fantasy_XV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2x5i.jpg","s":"The acclaimed fishing feature of FINAL FANTASY XV has been revamped and revitalized for PlayStationVR. Join Noctis, Ignis, Prompto, Gladio, and other familiar faces in a picturesque virtual reality backdrop en route to a thrilling encounter with the menace that lurks in the depths.\n\nDive into the story mode for an exhilarating, action-packed showdown with the notorious Monster of the Deep, or take in the sights, sounds, and scenery of FINAL FANTASY XV as you kick back and cast off in the free fishing mode. Bounties and tournaments offer fresh new challenges as you customize your rods, reels, and lures to catch the big one!"},{"t":"Monument Valley 2","p":["iOS"],"g":"Puzzle","r":"June 5","l":"https://en.wikipedia.org/wiki/Monument_Valley_2"},{"t":"Monument Valley II","p":["Android","iOS","macOS"],"d":"Ustwo Games","u":"Ustwo Games","g":"Point-and-click, Platform, Puzzle, Strategy, Adventure, Indie","r":"May 30, 2017","l":"https://www.igdb.com/games/monument-valley-ii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaev4.jpg","s":"Guide a mother and her child as they embark on a journey through magical architecture, discovering illusionary pathways and delightful puzzles as you learn the secrets of the Sacred Geometry."},{"t":"Moonshot Galaxy","p":["PlayStation VR"],"r":"May 9"},{"t":"Mordheim: Warband Skirmish","p":["Android","iOS"],"d":"Legendary Games","g":"Tactical role-playing","r":"May 25, 2017","l":"https://en.wikipedia.org/wiki/Mordheim:_Warband_Skirmish","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ekw.jpg","s":"Legendary Game’s adaptation of Games Workshop’s classic table top game: Mordheim, set in the Warhammer world. Control a small warband picking through the ruins of the City of Mordheim clashing with other scavenging warbands and collecting Wyrdstone - valuable shards from the comet that destroyed the city.\n\nMulti player turn-based strategy right at your fingertips you’ll have the freedom to play how YOU want to play. Hide in the shadows and wait for the right moment to strike, get a vantage point and pick your targets off with ranged weapons, or bring the fight straight to your opponent in an up close and personal confrontation, the choice, is yours!\n\nFrom release three mercenary factions are available: Reiklanders, Middenheimers and Marienburgers each with different traits and play styles. Each represents one of the factions pitted against each other in a brutal civil war over who should sit in the throne as Emperor. Can you harvest more Wyrdstone from Mordheim than your rivals to fuel your master’s war effort?"},{"t":"Mortal Blitz","p":["PlayStation VR"],"r":"April 4"},{"t":"Mosaic (murder mystery)","p":[],"l":"https://en.wikipedia.org/wiki/Mosaic_(murder_mystery)"},{"t":"MotoGP 17","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"June 15","l":"https://en.wikipedia.org/wiki/MotoGP_17"},{"t":"Mr Love: Queen's Choice","p":["Android","iOS"],"g":"Role-playing (RPG), Simulator, Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Mr_Love:_Queen's_Choice","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1lj9.jpg","s":"Who will be your soul mate? Mr Love: Queen's Choice is a romance simulation game that gives you the opportunity to text, chat and even call the main characters while developing your own career as a media producer.\n\nIn a world filled with superpowers, fantasy, and surprise, you will experience a girl’s whole life and get deeply involved with 4 male characters, feeling their romance, love, mystery and conflict in a deep story spanning dozens of episodes."},{"t":"Mr. Shifty","p":["Linux","Windows","macOS","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Team Shifty","u":"tinyBuild","g":"Beat 'em up","r":"April 13, 2017","l":"https://en.wikipedia.org/wiki/Mr._Shifty","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co209u.jpg","s":"Quit creeping through shadows, stop surveilling security patterns, and ditch the fancy toys. An expert thief and master of infiltration, Mr. Shifty can get inside any place he wants with just the power of his fists…okay, teleporting helps.\n\nA speed-stealth, kung-fu brawler about a teleporting thief, Mr. Shifty combines fast top-down gameplay with the ferocity of '90s Hong Kong action cinema, coming to PC (Win/Mac), PS4, and Xbox One in 2017.\n\nPummel your way through 75 levels of heists, rescue missions, boss battles, and down-'n'-dirty brawls. Outsmart your opponents by luring them into traps and tricking them into shooting each other. Activate slow-motion to dodge when the gunfire gets too thick, and watch your back, because it only takes one bullet to bring you down.\n\nNewly announced from indie publisher tinyBuild GAMES, Mr. Shifty is the debut title from Team Shifty; a close-knit group of four developers from Brisbane, Australia, who previously worked as a team at Halfbrick for over five years and have collectively shipped 21 games for consoles and handheld."},{"t":"MU Legend","p":["Windows"],"d":"Webzen Games","g":"Fantasy","r":"March 23, 2017","l":"https://en.wikipedia.org/wiki/MU_Legend","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coazjb.jpg","s":"MU Legend is a dark fantasy hack-and-slash MMORPG that combines traditional dungeon crawler elements with action RPG mechanics. Players explore a vast world filled with both solo and cooperative content, including procedurally generated dungeons, Blood Castle challenges, and the Endless Tower. The game features four character classes with extensive skill customization options and area-of-effect abilities from the start. Combat systems support both PvE and PvP gameplay, offering 1v1 duels, 3v3 team battles, and 16-guild territory wars. Built on Unreal Engine 3, the game accommodates various PC specifications while maintaining the series' signature dark atmosphere established by its predecessors MU Online and MU Origin."},{"t":"MudRunner","p":["Windows","PlayStation 4","Xbox One"],"d":"Saber Interactive","u":"Focus Home Interactive","g":"Vehicle simulation","r":"October 31, 2017","l":"https://en.wikipedia.org/wiki/MudRunner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m95.jpg","s":"Like Spintires before it, Spintires: MudRunner puts players in the driver seat and dares them to take charge of incredible all-terrain vehicles, venturing across extreme Siberian landscapes with only a map and compass as guides! This edition comes complete with a brand new Sandbox Map joining the original game's 5 environments, a total graphical overhaul, a new Challenge mode with 9 new dedicated maps, 13 new vehicles and other comprehensive improvements."},{"t":"Musou Stars","p":["PlayStation 4","PlayStation Vita"],"g":"Hack and slash, Action","r":"March 30","l":"https://en.wikipedia.org/wiki/Musou_Stars"},{"t":"Muv Luv Alternative","p":["Windows"],"g":"Visual novel","r":"September 18","l":"https://en.wikipedia.org/wiki/Muv_Luv"},{"t":"MXGP3: The Official Motocross Videogame","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"r":"May 30"},{"t":"Naruto Shippuden: Ultimate Ninja Storm Legacy","p":["Windows","PlayStation 4","Xbox One"],"r":"August 25"},{"t":"NASCAR Heat 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"September 12","l":"https://en.wikipedia.org/wiki/NASCAR_Heat_2"},{"t":"NBA 2K18","p":["Windows","Nintendo Switch","PlayStation 3","PlayStation 4","Xbox 360","Xbox One"],"g":"Sports","r":"September 19","l":"https://en.wikipedia.org/wiki/NBA_2K18","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wil.jpg","s":"The highest rated annual sports title of this generation returns with NBA 2K18, featuring unparalleled authenticity and improvements on the court."},{"t":"NBA Live 18","p":["PlayStation 4","Xbox One"],"g":"Sports","r":"September 15","l":"https://en.wikipedia.org/wiki/NBA_Live_18"},{"t":"NBA Playgrounds","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Sports","r":"May 9","l":"https://en.wikipedia.org/wiki/NBA_Playgrounds"},{"t":"Need for Speed Payback","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing","r":"November 10","l":"https://en.wikipedia.org/wiki/Need_for_Speed_Payback","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co209y.jpg","s":"\"This explosive adventure is filled with intense heist missions, high stakes car battles, epic cop pursuits and jaw dropping set pieces. It’s blockbuster gameplay never before seen from the series, fueled by a gripping story of betrayal and revenge. With Need for Speed: Payback, it’s no longer just about being the first to cross the finish line or racing to prove to be the best, it’s about building the perfect ride, getting behind the wheel and playing out an action driving fantasy.\n\nSet in the underworld of Fortune Valley, players will drive as three distinct characters reunited by a quest for vengeance against The House, a nefarious cartel that rules the city’s casinos, criminals and cops. They will take on a variety of challenges and events as Tyler, the Racer; Mac, the Showman; and Jess, the Wheelman to earn the respect of the underground. Featuring the deepest customization from the series, players can truly craft a personalized and unique ride, or spend hours finding and tuning an abandoned derelict into a supercar. They can then push their cars to the limit and raise the stakes by betting on their own performance, where they can either multiply their winnings or risk losing it all.\""},{"t":"Nefarious","p":["Windows","macOS","Linux"],"d":"StarBlade","u":"Starblade, Digerati","g":"Action, platformer","r":"January 23, 2017","l":"https://en.wikipedia.org/wiki/Nefarious_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fbecr9efz3ogb3e4tntc.jpg","s":"Nefarious is a 2d-animated action platformer, where your objective on each stage is to kidnap a princess and then escape with them! Heroes will attempt to thwart you, and many things may not go quite as expected."},{"t":"Nekojishi","p":["Windows"],"g":"Visual novel","r":"November 12"},{"t":"Neptune Flux","p":["PlayStation VR"],"r":"August 8"},{"t":"Never Stop Sneakin'","p":["Nintendo Switch"],"g":"Action RPG, Hack and slash, Metroidvania","r":"December 14","l":"https://en.wikipedia.org/wiki/Never_Stop_Sneakin%27"},{"t":"New Frontier Days: Founding Pioneers","p":["Windows","Nintendo Switch"],"d":"Arc System Works","u":"Arc System Works","g":"Simulation","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/New_Frontier_Days:_Founding_Pioneers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co250r.jpg","s":"\"New Frontier Days ~Founding Pioneers~\" is a town-building simulation game, where you command your pioneers to colonize a new land."},{"t":"New Game!","p":[],"l":"https://en.wikipedia.org/wiki/New_Game!"},{"t":"Nex Machina","p":["Windows","PlayStation 4"],"g":"Shoot 'em up","r":"June 20","l":"https://en.wikipedia.org/wiki/Nex_Machina","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1twn.jpg","s":"From the collaboration between Housemarque (Resogun, Alienation, Matterfall), and Robotron and Smash TV legendary creator Eugene Jarvis comes Nex Machina, an explosive arcade experience created with competition in mind."},{"t":"NHL 18","p":["PlayStation 4","Xbox One"],"g":"Sports","r":"September 15","l":"https://en.wikipedia.org/wiki/NHL_18"},{"t":"Niche","p":["Linux","macOS","Windows"],"d":"Stray Fawn Studio","u":"Stray Fawn Studio","g":"Simulation","r":"September 21, 2017","l":"https://en.wikipedia.org/wiki/Niche_(video_game)"},{"t":"Nidhogg 2","p":["Windows","macOS","PlayStation 4"],"g":"Fighting","r":"August 15","l":"https://en.wikipedia.org/wiki/Nidhogg_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1hub.jpg","s":"Return of the wurm! The next installment of the epic award-winning dueling tug-of-war is coming! Destroy your opponents with all new moves and weapons across ten different arenas."},{"t":"Nier: Automata","p":["PlayStation 4","Windows"],"g":"Action RPG","r":"March 7","l":"https://www.igdb.com/games/nier-automata","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5pcj.jpg","s":"NieR: Automata tells the story of androids 2B, 9S and A2 and their battle to reclaim the machine-driven dystopia overrun by powerful machines."},{"t":"Night in the Woods","p":["Windows","macOS","Linux","PlayStation 4"],"g":"Adventure","r":"February 21","l":"https://en.wikipedia.org/wiki/Night_in_the_Woods","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ovg.jpg","s":"Night In The Woods is an adventure game heavily focused on story, characters and exploration, with some platforming to get around town. Mae's a cat so the roofs and ledges and powerlines are all her playground, and she's not the only one up there by a long shot. You'll also be doing various activities and interacting with the world in different ways, getting to know the townspeople, hanging out with friends, exploring Possum Springs inside and out, and venturing into the surrounding areas."},{"t":"Night Trap 25th Anniversary","p":["Windows","PlayStation 4"],"g":"Interactive film","r":"August 15","l":"https://en.wikipedia.org/wiki/Night_Trap"},{"t":"Nights of Azure","p":["Windows"],"g":"Action RPG","r":"February 7","l":"https://en.wikipedia.org/wiki/Nights_of_Azure"},{"t":"Nights of Azure 2: Bride of the New Moon","p":["Windows","Nintendo Switch","PlayStation 4"],"g":"Action RPG","r":"October 24"},{"t":"Nine Parchments","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"r":"December 5","l":"https://en.wikipedia.org/wiki/Nine_Parchments"},{"t":"Nioh","p":["PlayStation 4","Windows"],"g":"Action RPG, Hack and slash","r":"February 7","l":"https://en.wikipedia.org/wiki/Nioh","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20xg.jpg","s":"In Nioh, players will traverse war-torn Japan as William, a blonde-haired swordsman whose background as a fierce warrior and seasoned knowledge of the blade allows him to survive in the demon-plagued land of the samurai. Known as Yokai, these demons inhabit a number of dangerous locations and lie in wait in the shadows to ambush unsuspecting victims. Players will also face off with other samurai in supernatural sword battles and intense, multi-target engagements offering a level of difficulty that will truly test even the most hardened samurai’s skills, patience, and strategy.\n\nOffering a deep and original storyline that takes place during the Warring States Period of Japanese history alongside strategic sword-fighting action, Nioh will challenge players in a way that makes every mission and accomplishment feel earned and worthwhile."},{"t":"Obduction","p":["PlayStation 4"],"g":"Adventure, Puzzle","r":"August 29","l":"https://en.wikipedia.org/wiki/Obduction_(video_game)"},{"t":"Observer","p":["Windows","PlayStation 4","Xbox One","macOS","Linux"],"g":"Horror (psych)","r":"August 15","l":"https://en.wikipedia.org/wiki/Observer_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co256h.jpg","s":"Observer is a first person perspective horror game that focuses on a dark, atmospheric environment and deep story telling."},{"t":"Occultic;Nine","p":["Xbox One","PlayStation Vita","PlayStation 4"],"g":"Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Occultic;Nine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22rr.jpg","s":"Occultic;Nine is an Japanese visual novel that is based on a light novel of the same name. The game is descibed as a \"Paranormal Science Novel\". The story follows nine idiosyncratic individuals. Little incongruities that occur around these nine eventually lead to a larger, unimaginable event that may alter what is considered common sense in this world. Despite being by the same makers and sharing a similar naming scheme, Occultic;Nine is not a part of 5pb's Science Adventure series of adventure games."},{"t":"Oceanhorn: Monster of Uncharted Seas","p":["PlayStation Vita","Nintendo Switch"],"g":"Action-adventure","r":"May 17"},{"t":"Ode","p":["Windows"],"d":"Ubisoft Reflections","u":"Ubisoft","g":"Adventure, Music","r":"November 26, 2017","l":"https://en.wikipedia.org/wiki/Ode_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qvi.jpg","s":"\"Ode is an immersive, enchanting visual & musical experience through beautiful open worlds. Spread joy as you explore each sensory level, bringing the world to life by collecting and releasing fallen stars to create a harmonious musical garden full of colour and wonder.\"\n\n\"Ode IS UNLIKE ANY GAME YOU’VE PLAYED!\nUnlike most traditional games, ode is an experiential journey through music and light. With no HUD to guide you, no tutorial and no hints, ode allows you to explore the sensory worlds around you at your own pace and direction. Your only goal is to spread joy throughout the world!\n- Complete freedom to explore fantasy landscapes\n- Everything in the world reacts to you\n- Bring each world to life through light, sound and colour\""},{"t":"Ogre","p":["Windows"],"g":"Strategy, Indie","l":"https://en.wikipedia.org/wiki/Ogre_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26ya.jpg","s":"Ogre is a turn-based strategy game of mechanized warfare, requiring tactical decision making and strategic thinking. It is the official video game adaptation of the legendary tabletop wargame from Steve Jackson Games, developed by the award-winning Auroch Digital.\n\nHovercraft, tanks, infantry, and giant cybernetic tanks called Ogres take part in a seemingly endless world war. You take command and vie for supremacy on the irradiated battlefields of The Last War."},{"t":"Oikospiel","p":["macOS","Windows"],"d":"David Kanaga","g":"Adventure, Indie","r":"February 16, 2017","l":"https://en.wikipedia.org/wiki/Oikospiel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dy0.jpg","s":"Play as a German Shepherd named Pluto and explore the enchanted climates of planet Earth and the asteroid 433 Eros. Visit an Arctic Ocean wind farm, Kochiri Forest, a computer OS, a cluttered desk, a union-busting prairie in Kansas, a private jet, a flooded city at the North Pole, and many more fevered landscapes.\n\nWritten, assembled, and with an original score by David Kanaga, composer of Proteus, Panoramical and Dyad, Oikospiel's soundtrack is \"100 percent intertwined with the game\" (PC Gamer), featuring a lush variety of interactive musical experiences woven together into an operatic whole."},{"t":"OK Golf","p":["iOS"],"g":"Sports","r":"February 9","l":"https://en.wikipedia.org/wiki/OK_Golf"},{"t":"Old Man's Journey","p":["Android","iOS","macOS","Windows"],"d":"Broken Rules","u":"Broken Rules","g":"Puzzle, Adventure, Indie","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Old_Man's_Journey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22s9.jpg","s":"Old Man’s Journey, a soul-searching puzzle adventure, tells a story of life, loss, reconciliation, and hope. Entrenched in a beautifully sunkissed and handcrafted world, embark on a heartfelt journey interwoven with lighthearted and pressure-free puzzle solving.\n\nDuring this compact gameplay experience, you’ll be transported to a vibrant and wishful world, exploring life’s complexities through the old man’s eyes. Meditatively delightful and reflective, Old Man’s Journey invites you to immerse yourself in quiet and inquisitive puzzles, and experience the old man’s heartache, regret, and hope."},{"t":"Old Time Hockey","p":["Windows","PlayStation 4","Xbox One"],"g":"Sports","r":"March 28","l":"https://en.wikipedia.org/wiki/Old_Time_Hockey_(video_game)"},{"t":"Omega Quintet","p":["Windows"],"g":"RPG","r":"December 15","l":"https://en.wikipedia.org/wiki/Omega_Quintet"},{"t":"One Piece: Unlimited World Red Deluxe Edition","p":["Windows","PlayStation 4","Nintendo Switch"],"g":"Action-adventure","r":"August 25"},{"t":"Operation Abyss: New Tokyo Legacy","p":["Windows"],"g":"RPG, Dungeon crawl","r":"March 27"},{"t":"Operation Babel: New Tokyo Legacy","p":["Windows","PlayStation Vita"],"g":"RPG, Dungeon crawl","r":"May 16"},{"t":"Opus Magnum","p":["Windows"],"d":"Zachtronics","u":"Zachtronics","g":"Indie, Simulation","r":"December 8, 2017","l":"https://en.wikipedia.org/wiki/Opus_Magnum","i":"images/steam-558990.jpg","s":"Opus Magnum is the latest open-ended puzzle game from Zachtronics, the creators of SpaceChem, Infinifactory, and SHENZHEN I/O. Design and build machines that assemble potions, poisons, and more using the alchemical engineer’s most advanced tool: the transmutation engine!"},{"t":"Opus: Rocket of Whispers","p":["Android","iOS"],"d":"SIGONO","u":"SIGONO","g":"Adventure","r":"September 14, 2017","l":"https://en.wikipedia.org/wiki/Opus:_Rocket_of_Whispers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27nl.jpg","s":"Opus: Rocket of Whispers is a single-player third-person adventure set in the snowy post-apocalyptic wilderness of an unknown world, far in the future. Players will play as the last survivors of a nation that has an ancient tradition of cosmic worship, and belief that by launching space burials, those who've deceased will be able to return and rest among the stars. Throughout the game players will travel the snow covered landscape, scavenging for rocket parts and remnants of the past, so they may help the last surviving witch - religious figures who conduct the rituals of space burials - to launch one final burial. The game explores themes of purpose, pursuit and loneliness."},{"t":"Orcs Must Die! Unchained","p":["Windows","PlayStation 4"],"d":"Robot Entertainment","u":"Robot Entertainment","g":"Tower defense, action","r":"April 19, 2017","l":"https://en.wikipedia.org/wiki/Orcs_Must_Die!_Unchained","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22tc.jpg","s":"Wisecracking multiplayer action that uniquely blends the strategic depth of a MOBA with intense third-person combat as you fight in a wild battle for fortress supremacy.\n\nOrcs Must Die! Unchained is a high-octane PvP action game in which you storm the opposing fortress together with your friends and defend your own base. Your enemies are also sending their minions to your rift – construct a maze of traps and beat back everything they send at you. Grinding, roasting, slashing or good old-fashioned thumping – every dirty trick is at your disposal when both attacking and defending."},{"t":"Oriental Empires","p":["Windows"],"d":"R.T. Smith & John Carline","u":"Iceberg Interactive","g":"Turn-based strategy, 4X","r":"September 14, 2017","l":"https://en.wikipedia.org/wiki/Oriental_Empires","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qwe.jpg","s":"Turn based 4X strategy game, recreating the civilizations of ancient China. Develop your land, build great cities, raise huge armies and fight epic battles, with hundreds of soldiers fighting right on the game map. Advance your technologies, culture and religion to create one of mankind’s biggest empires."},{"t":"Our World Is Ended","p":["PlayStation Vita"],"d":"Red Entertainment","u":"5pb., PQube","g":"Visual Novel","r":"November 9, 2017","l":"https://en.wikipedia.org/wiki/Our_World_Is_Ended","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22tf.jpg","s":"Japanese visual novel for PS Vita published by Red Entertainment."},{"t":"Outcast – Second Contact","p":["Windows","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"September 28","l":"https://en.wikipedia.org/wiki/Outcast_(video_game)"},{"t":"Outlast 2","p":["Windows","macOS","PlayStation 4","Xbox One"],"g":"Survival horror","r":"April 25","l":"https://en.wikipedia.org/wiki/Outlast_2"},{"t":"Outlast II","p":["Xbox One","macOS","Windows","PlayStation 4"],"d":"Red Barrels","u":"Red Barrels","g":"Adventure, Indie","r":"April 25, 2017","l":"https://www.igdb.com/games/outlast-ii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20x8.jpg","s":"Outlast 2 is the sequel to the acclaimed survival horror game Outlast. Set in the same universe as the first game, but with different characters and a different setting, Outlast 2 is a twisted new journey into the depths of the human mind and its dark secrets. No conflict is ever black and white."},{"t":"Overcooked","p":["Nintendo Switch"],"g":"Simulation","r":"July 27","l":"https://en.wikipedia.org/wiki/Overcooked"},{"t":"Overgrowth","p":["Windows","macOS","Linux"],"d":"Wolfire Games","u":"Wolfire Games","g":"Action","r":"October 16, 2017","l":"https://en.wikipedia.org/wiki/Overgrowth_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6a37.jpg","s":"Feel like the star of a martial arts film in Overgrowth, as you jump, kick, throw, and slash your way to victory. Free the rabbits from their evil overlords in the main story, then play through the prequel story, and finally, try out nine years of mods developed by the community, or create your own!"},{"t":"Oxenfree","p":["Nintendo Switch"],"g":"Graphic adventure","r":"October 6","l":"https://en.wikipedia.org/wiki/Oxenfree"},{"t":"P.A.M.E.L.A.","p":["Windows"],"d":"NVYVE Studios","u":"NVYVE Studios","g":"First-person shooter, survival horror, role-playing, action, adventure","l":"https://en.wikipedia.org/wiki/P.A.M.E.L.A."},{"t":"Pacer","p":["Windows","PlayStation 4","Xbox One"],"d":"R8 Games","u":"R8 Games","g":"Racing","r":"May 31, 2017","l":"https://en.wikipedia.org/wiki/Pacer_(video_game)"},{"t":"Pako 2","p":["Windows","macOS"],"d":"Tree Men Games","u":"Tree Men Games","g":"Action, Racing","r":"November 16, 2017","l":"https://en.wikipedia.org/wiki/Pako_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24q2.jpg","s":"Arcade drive-by shooting action with heist game mechanics"},{"t":"Pankapu","p":["PlayStation 4","Xbox One"],"r":"September 19"},{"t":"Panty Party","p":["Windows"],"d":"Animu Game","u":"Cosen","g":"Action","r":"January 24, 2017","l":"https://en.wikipedia.org/wiki/Panty_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob2t1.jpg","s":"Panty Party is a fast-paced battle game. Fly as a panty in the street and in-between buildings. Search for the enemy panties and kick their bad ♥♥♥!"},{"t":"Paradigm","p":["Windows","macOS"],"g":"PCA","r":"April 5","l":"https://en.wikipedia.org/wiki/Paradigm_(video_game)"},{"t":"PaRappa the Rapper Remastered","p":["PlayStation 4"],"g":"Rhythm","r":"April 4","l":"https://en.wikipedia.org/wiki/PaRappa_the_Rapper"},{"t":"Party Panic","p":["Windows","macOS","Linux"],"r":"August 7"},{"t":"Party Planet","p":["Nintendo Switch"],"r":"December 12"},{"t":"Pastel Memories","p":[],"l":"https://en.wikipedia.org/wiki/Pastel_Memories"},{"t":"Patapon Remastered","p":["PlayStation 4"],"g":"Rhythm, God game","r":"August 1"},{"t":"Perception","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"The Deep End Games","u":"The Deep End Games, Feardemic","g":"Adventure","r":"May 30, 2017","l":"https://en.wikipedia.org/wiki/Perception_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nmy04bilf2gxtf90sxsd.jpg","s":"Perception is a first-person narrative horror adventure that tells the story of Cassie, a blind heroine who uses her extraordinary hearing and razor-sharp wits to unravel the mysteries of an abandoned estate that haunts her dreams."},{"t":"Persona 5","p":["PlayStation 4","PlayStation 3"],"d":"P-Studio","u":"Atlus","g":"RPG, Social sim","r":"April 4, 2017","l":"https://en.wikipedia.org/wiki/Persona_5"},{"t":"Phantom Dust Remaster","p":["Windows","Xbox One"],"g":"Action, RTS","r":"May 16","l":"https://en.wikipedia.org/wiki/Phantom_Dust"},{"t":"Picross S","p":["Nintendo Switch"],"g":"Puzzle","r":"September 28","l":"https://en.wikipedia.org/wiki/Picross_S"},{"t":"Pillars of Eternity: Complete Edition","p":["PlayStation 4","Xbox One"],"g":"RPG","r":"August 29","l":"https://en.wikipedia.org/wiki/Pillars_of_Eternity"},{"t":"Pinball FX 3","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Pinball","r":"September 26","l":"https://en.wikipedia.org/wiki/Pinball_FX_3"},{"t":"Pinball FX 3: Universal Classics Pinball","p":["Xbox One"],"d":"Zen Studios","u":"Zen Studios","r":"September 26, 2017","l":"https://en.wikipedia.org/wiki/Pinball_FX_3"},{"t":"Pinstripe","p":["Windows","iOS"],"g":"Puzzle, Adventure","r":"April 25","l":"https://en.wikipedia.org/wiki/Pinstripe_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wdvojtqymc24siasqjde.jpg","s":"Pinstripe is an emotionally charged adventure about Hell created entirely by a one-man team over the course of five years. Play as Teddy, an estranged ex-minister forced to venture through the frozen afterlife in search of Bo, his three year old daughter, and her perverse kidnapper. Discover the dark secrets of Teddy's past, and confront his sleazy, demonic nemesis, Mr. Pinstripe."},{"t":"Pixel Privateers","p":["Windows"],"d":"Quadro Delta","u":"Re-Logic","g":"Tactical role-playing game","r":"February 21, 2017","l":"https://en.wikipedia.org/wiki/Pixel_Privateers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/h7swf8oa8sjxqfhuukou.jpg","s":"Pixel Privateers is a Squad Based Tactical RPG “Loot ‘Em Up” that will send your team of mercenaries through a mysterious wormhole on a quest to gather technology for your employer. In a twist of fate, your journey becomes a one-way ticket – with an entire galaxy of worlds to explore, factions to encounter, and epic gear to collect."},{"t":"Planescape: Torment - Enhanced Edition","p":["Android","Windows","macOS","Linux"],"d":"Beamdog","u":"Beamdog","g":"Role-playing (RPG), Strategy, Adventure","r":"April 11, 2017","l":"https://www.igdb.com/games/planescape-torment-enhanced-edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kpe.jpg","s":"\"Discover an incredibly rich story and a unique setting unlike anything else in fantasy. Defeat strange and alien creatures, engage in rich dialogue, and explore the dark and dangerous Planescape setting in this 50+ hour RPG classic.\n\nMillions of Planescape: Torment fans have enjoyed the strange and dangerous city of Sigil and surrounding planes through the Nameless One's eyes. Now it’s your turn. This is Planescape: Torment like you’ve never seen before.\n\nEnhanced Edition - Key Features:\n- Enhanced Planescape: Chris Avellone, Lead Designer on Planescape Torment, has partnered with Beamdog to curate gameplay updates, bug fixes, and enhancements to best capture his original vision for the game.\n\n- Remastered Music: The full Planescape: Torment soundtrack has been remastered in-game to add more depth to Sigil and the multiverse.\n\n- 4K Interface: Sigil has never looked this good! The interface of Planescape: Torment has been rebuilt in high definition with tons of new convenience features.\n\n- A Planescape For Today: The Enhanced Edition includes modern features such as tab highlighting, area zooming, combat log, quickloot, and more!\""},{"t":"Planet of the Apes: Last Frontier","p":["PlayStation 4"],"d":"The Imaginati Studios","u":"FoxNext, The Imaginarium, Creative England","g":"Interactive fiction","r":"November 21, 2017","l":"https://en.wikipedia.org/wiki/Planet_of_the_Apes:_Last_Frontier","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21g8.jpg","s":"The game allows you to follow and interact with a new group of characters. The tale is a new one set in the North American Rocky Mountains during the timeline between ‘Dawn of Planet of the Apes’ and ‘War for Planet of the Apes.’ Explore your own morals and ethics as you drive the fortunes of an ape troop and band of human survivors. Your decisions will have real consequences as these two worlds collide amidst a stunning backdrop.\n\nAre You Ready to Choose?"},{"t":"Poi","p":["Windows"],"g":"Platformer","r":"February 1","l":"https://en.wikipedia.org/wiki/Poi_(video_game)"},{"t":"Pokkén Tournament DX","p":["Nintendo Switch"],"g":"Fighting","r":"September 22","l":"https://en.wikipedia.org/wiki/Pokk%C3%A9n_Tournament","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zji.jpg","s":"Pokkén Tournament is a fighting video game and the first Pokémon title for the Nintendo Switch console. Take direct control of one of 21 prized Pokémon fighters to defeat other Pokémon in arena fights. Call upon Support Pokémon to assist in the fight, then unleash your Pokémon's unique Burst Attack to climb atop the ranks. With all new modes and new ways to battle with friends, this is your chance to become champion of the Ferrum Region!"},{"t":"Pokémon Duel","p":["iOS","Android"],"g":"Digital tabletop","r":"January 24","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Duel"},{"t":"Pokémon Ultra Moon","p":["Nintendo 3DS"],"d":"Game Freak","u":"Nintendo of America, Nintendo, Nintendo of Europe, The Pokémon Company","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"November 17, 2017","l":"https://www.igdb.com/games/pokemon-ultra-moon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zjt.jpg","s":"\"Take on the role of a Pokémon Trainer and uncover new tales, and unravel the mystery behind the two forms reminiscent of the Legendary Pokémon. With new story additions and features this earns Pokémon Ultra Sun and Pokémon Ultra Moon the name \"Ultra!\" Another adventure is about to begin!\n\nNew Pokémon forms have been discovered in the Alola region in Pokémon Ultra Sun and Pokémon Ultra Moon! These forms are reminiscent of the Legendary Pokémon Solgaleo, Lunala, and Necrozma, first revealed in Pokémon Sun and Pokémon Moon. Head out on an epic journey as you solve the mystery behind these fascinating Pokémon! In this expanded adventure, get ready to explore more of the Alola region, catch more amazing Pokémon, and battle more formidable foes in Pokémon Ultra Sun and Pokémon Ultra Moon!\""},{"t":"Pokémon Ultra Sun","p":["Nintendo 3DS"],"d":"Game Freak","u":"Nintendo of Europe, Nintendo, The Pokémon Company, Nintendo of America","g":"Role-playing (RPG), Adventure","r":"November 17, 2017","l":"https://www.igdb.com/games/pokemon-ultra-sun","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zjs.jpg","s":"\"Take on the role of a Pokémon Trainer and uncover new tales, and unravel the mystery behind the two forms reminiscent of the Legendary Pokémon. With new story additions and features this earns Pokémon Ultra Sun and Pokémon Ultra Moon the name \"Ultra!\" Another adventure is about to begin!\n\nNew Pokémon forms have been discovered in the Alola region in Pokémon Ultra Sun and Pokémon Ultra Moon! These forms are reminiscent of the Legendary Pokémon Solgaleo, Lunala, and Necrozma, first revealed in Pokémon Sun and Pokémon Moon. Head out on an epic journey as you solve the mystery behind these fascinating Pokémon! In this expanded adventure, get ready to explore more of the Alola region, catch more amazing Pokémon, and battle more formidable foes in Pokémon Ultra Sun and Pokémon Ultra Moon!\""},{"t":"Pokémon Ultra Sun and Ultra Moon","p":["Nintendo 3DS"],"g":"RPG","r":"November 17","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Ultra_Sun_and_Ultra_Moon"},{"t":"Pokémon: Magikarp Jump","p":["iOS","Android"],"d":"Select Button","u":"The Pokémon Company","g":"Incremental game","r":"May 24, 2017","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon:_Magikarp_Jump","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1sb6.jpg","s":"Train your Magikarp to soar as high as possible in Pokémon Magikarp Jump! The lowly Magikarp now gets its time in the spotlight with this fun app for iPhone, iPad, and Android devices. Feed and develop your Magikarp to maximize the Pokémon's jump power to reach new heights. Then compete to see if your Magikarp is the best. Can your Magikarp rise to the level of League Champion?\n\nDuring your training, if Magikarp gets knocked out, or retires upon reaching Lv. 20, you'll start over with a new generation of Magikarp. But not all progress is lost—your new Pokémon will start off a little bit stronger than your last. Keep training every Magikarp until you can make it to the top of the in-game tournament ladder!\n\nWhile you're raising your Magikarp, keep an eye out for Pokémon that want to help you. For example, some Pokémon you encounter will give you food to keep your Magikarp nourished.\n\nWhen you do well in jumping tournaments, you can get commemorative photos of your achievement. You can share these photos online and with friends to show the world how well you've trained your Magikarp."},{"t":"Polybius","p":["PlayStation VR"],"r":"May 9"},{"t":"Poochy & Yoshi's Woolly World","p":["Nintendo 3DS"],"g":"Platformer","r":"February 3","l":"https://en.wikipedia.org/wiki/Poochy_%26_Yoshi%27s_Woolly_World"},{"t":"Portal Knights","p":["Nintendo Switch"],"g":"Action RPG, Survival","r":"November 23","l":"https://en.wikipedia.org/wiki/Portal_Knights","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jjh.jpg","s":"Leave the familiar world behind and step into the fantastic unknown with Portal Knights! Play with your friends in this action-packed crafting adventure across dozens of sandbox islands connected by ancient portals.\nNo one can remember how long it’s been since the peaceful world was torn apart by The Fracture, plummeting it into darkness. Is there any soul brave enough to reunite the shattered realm? Craft your adventure. Forge your hero. Become the ultimate Portal Knight!"},{"t":"Postknight","p":["Android","iOS"],"d":"Kurechii","u":"Kurechii","g":"RPG, Adventure","r":"February 9, 2017","l":"https://en.wikipedia.org/wiki/Postknight","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86wy.jpg","s":"Step into the shoes of a Postknight and experience and exciting RPG adventure on-the-go!\n\nHighlighting the best elements of a role-playing games, Postknight allows you to experience the best in bite-sized pieces. Play when you can, and let your postknight grow when you are not!\n\nPerfect for mobile players, Postknight provides quality content in reasonable sizes, adequate controls for your adventure, and rewards you when you have to take a break from the game too!\n\nUphold the postknight’s motto of delivering anything to anywhere! Meet recipients and others who will help you in your quest to rank up as a postknight and traverse the kingdom of Kurestal! Visit humble villages, breezy towns and grand cities for your deliveries."},{"t":"Power Rangers: Legacy Wars","p":["iOS","Android"],"d":"nWay","u":"nWay, Lionsgate Games","g":"Fighting, beat 'em up, action","r":"March 23, 2017","l":"https://en.wikipedia.org/wiki/Power_Rangers:_Legacy_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qzm.jpg","s":"You, the player, must use special Zeo Shards given to you by Zordon to beat Rita at her own game. Fight back with your own curated team of legendary Power Rangers and villains from the multiverse! Unlock new Rangers, upgrade your best fighters and create the best team to defeat Rita, and save the Morphin Grid. May the Power protect you!"},{"t":"Prey","p":["Windows","PlayStation 4","Xbox One"],"g":"Shooter, Puzzle, Role-playing (RPG), Adventure","r":"May 5","l":"https://en.wikipedia.org/wiki/Prey_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9aoh.jpg","s":"In Prey, you awaken aboard Talos I, a space station orbiting the moon in the year 2032. You are the key subject of an experiment meant to alter humanity forever – but things have gone terribly wrong. The space station has been overrun by hostile aliens and you are now being hunted. As you dig into the dark secrets of Talos I and your own past, you must survive using the tools found on the station, your wits, weapons, and mind-bending abilities."},{"t":"Pro Evolution Soccer 2018","p":["Windows","PlayStation 3","PlayStation 4","Xbox 360","Xbox One"],"g":"Sports","r":"September 12","l":"https://en.wikipedia.org/wiki/Pro_Evolution_Soccer_2018","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ug5.jpg","s":"Pro Evolution Soccer 2018 is a football simulation game developed and published by Konami in 2017. It features updated teams, players, and competitions with a focus on realistic gameplay and presentation. The game introduces improved ball control, dribbling mechanics, and enhanced player animations. Modes include Master League, Become a Legend, online multiplayer, and licensed tournaments such as the UEFA Champions League."},{"t":"Project CARS 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Racing (sim)","r":"September 22","l":"https://en.wikipedia.org/wiki/Project_CARS_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20mn.jpg","s":"Project CARS 2 is the next evolution in the award-winning racing series, featuring the most iconic cars under the most thrilling of conditions to deliver the “Ultimate Driver Journey” experience. Created by gamers, tested by world-class racing drivers, and the definitive choice of e-Sports pros – Project CARS 2 brings together the essence of motorsports racing in the most beautiful, authentically crafted, and technically advanced racing game on the planet."},{"t":"Project Nimbus: Code Mirai","p":["PlayStation 4"],"g":"Action, Shooter","r":"November 21"},{"t":"Psycho-Pass: Mandatory Happiness","p":["Windows"],"g":"Visual novel","r":"April 27"},{"t":"Psychonauts in the Rhombus of Ruin","p":["PlayStation 4"],"g":"Puzzle, Adventure","r":"February 21","l":"https://en.wikipedia.org/wiki/Psychonauts_in_the_Rhombus_of_Ruin"},{"t":"PUBG: Battlegrounds","p":["Windows"],"d":"PUBG Studios","u":"Krafton, Microsoft Studios, Tencent Games, Kakao Games","g":"Battle royale","r":"December 20, 2017","l":"https://en.wikipedia.org/wiki/PUBG:_Battlegrounds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaam4.jpg","s":"PUBG: Battlegrounds is a battle royale shooter that pits 100 players against each other in a struggle for survival. Gather supplies and outwit your opponents to become the last person standing."},{"t":"Puyo Puyo Tetris","p":["Nintendo Switch","PlayStation 4"],"g":"Puzzle","r":"April 25","l":"https://en.wikipedia.org/wiki/Puyo_Puyo_Tetris"},{"t":"Puzzle Fighter","p":["iOS","Android"],"d":"Capcom Vancouver","u":"Capcom","g":"Tile-matching, fighting","l":"https://en.wikipedia.org/wiki/Puzzle_Fighter_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27wy.jpg","s":"\"Experience the evolution of the beloved arcade classic Puzzle Fighter!\n\nAssemble a team of legendary characters from favorite Capcom franchises. Challenge players to thrilling real-time battles. Discover dozens of strategic abilities. Build up and destroy gems to unleash epic combos. Puzzle Fight your way to the top of the World Leaderboard!\""},{"t":"Puzzle Puppers","p":["Windows","Android","iOS"],"d":"Cardboard Keep","u":"Cardboard Keep","g":"Puzzle","r":"January 20, 2017","l":"https://en.wikipedia.org/wiki/Puzzle_Puppers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coav8m.jpg","s":"Stretch out cute dogs to their food bowls! Easy to learn, difficult to master with deceptively simple puzzles and mechanics."},{"t":"Pyre","p":["Windows","PlayStation 4"],"g":"Action RPG, Sports","r":"July 25","l":"https://en.wikipedia.org/wiki/Pyre_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ttv.jpg","s":"A party-based RPG/visual novel/sports game hybrid wherein the player, dubbed the Reader for their literacy by the group of scavengers who discovers them, is sent in exile to a lawless wasteland called the Downside and has to lead their ever-growing party of misfits to locations wherein many similar parties compete in Rites in order to attain freedom and be absolved of their crimes."},{"t":"R.B.I. Baseball 17","p":["Nintendo Switch"],"g":"Sports","r":"September 5","l":"https://en.wikipedia.org/wiki/R.B.I._Baseball_17"},{"t":"Raid: World War II","p":["Windows","PlayStation 4","Xbox One"],"g":"FPS, Tactical shooter","r":"September 26"},{"t":"Raiden V: Director's Cut","p":["Windows","PlayStation 4"],"g":"Shoot 'em up","r":"October 5","l":"https://en.wikipedia.org/wiki/Raiden_V"},{"t":"Rain World","p":["Windows","PlayStation 4"],"g":"Platformer","r":"March 28","l":"https://en.wikipedia.org/wiki/Rain_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24pm.jpg","s":"Rain World is a survival platformer set in an abandoned industrial environment ravaged by a shattered ecosystem. Bone-crushingly intense rains pound the surface, making life as we know it almost impossible. The creatures in this world hibernate most of the time, but in the few brief dry periods they go out in search of food."},{"t":"Rakuen","p":["Windows","macOS","Linux"],"g":"Adventure","r":"May 10","l":"https://en.wikipedia.org/wiki/Rakuen_(video_game)"},{"t":"Rangi","p":["Gear VR"],"d":"Funsoft","u":"Digigo","g":"Puzzle, virtual reality","r":"January 2017","l":"https://en.wikipedia.org/wiki/Rangi_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co242g.jpg","s":"Solve complex puzzles, explore hidden temples, escape deadly platforms and revel in the joy of flight as you restore the Musiki's stolen rhythms!"},{"t":"Ravenfield","p":["Windows","macOS","Linux"],"g":"First-person shooter","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Ravenfield_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24pg.jpg","s":"Ravenfield is a singleplayer battlefield style game. It started out as an experiment with ragdolls and AI, and will remain a slightly experimental, for-fun game project.\n\nWalk upon the Ravenfield with your BLUE allies! Take down those pesky REDs using helicopters, cars, guns, and active ragdoll physics."},{"t":"Rayman Legends Definitive Edition","p":["Nintendo Switch"],"g":"Platformer","r":"September 12","l":"https://en.wikipedia.org/wiki/Rayman_Legends"},{"t":"Re:Stage!","p":[],"l":"https://en.wikipedia.org/wiki/Re:Stage!"},{"t":"Reconstrucción","p":["Android","iOS"],"g":"Adventure","r":"February 7","l":"https://en.wikipedia.org/wiki/Reconstrucci%C3%B3n"},{"t":"ReCore Definitive Edition","p":["Windows","Xbox One"],"g":"Action-adventure, Platformer","r":"August 29","l":"https://en.wikipedia.org/wiki/ReCore"},{"t":"Redeemer","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Sobaka Studio","u":"Good Shepherd Entertainment, Buka Entertainment, Ravenscourt","g":"Beat 'em up, top-down shooter, hack and slash","r":"August 1, 2017","l":"https://en.wikipedia.org/wiki/Redeemer_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24p8.jpg","s":"REDEEMER is a Top-Down Action game where you will punch, hack and blast your way through enemies using fists, hammers, fire arms and even the environment."},{"t":"Redout","p":["PlayStation 4","Xbox One"],"g":"Racing","r":"August 29","l":"https://en.wikipedia.org/wiki/Redout_(video_game)"},{"t":"Reflex Arena","p":["Windows"],"d":"Turbo Pixel Studios","u":"Turbo Pixel Studios","g":"First-person shooter","r":"March 8, 2017","l":"https://en.wikipedia.org/wiki/Reflex_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r4a.jpg","s":"\"Reflex Arena is a return to roots, pure, fast, first person shooter. You will be pushed to your limits facing other contestants in a range of rich and diverse arena-base environments. Delivering a truly rewarding experience based purely on your skill and success. Train to unlock your genetic potential and bring it online for the ultimate proving ground and make your mark. There are no limitations in Reflex Arena, the true evolution of the classic arena shooter genre.\""},{"t":"Reigns: Her Majesty","p":["Android","iOS","Linux","macOS","Windows"],"d":"Nerial","u":"Devolver Digital","g":"Strategy","r":"December 6, 2017","l":"https://en.wikipedia.org/wiki/Reigns:_Her_Majesty","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4a5e.jpg","s":"Reigns: Her Majesty is the revolutionary sequel to the smash swipe 'em up hit Reigns. A cultural renaissance has bestowed the world with a new era of knowledge and enlightenment but greed and jealousy still conspire against the benevolent queen. Outwit and outlast those that would seek to depose you and your husband by swiping left or right, making just decisions on all manner of royal matters. Maintain the balance between the kingdom's most powerful factions, use mystical items from your inventory, and navigate the increasingly complex politics and personal relationships of your dynasty."},{"t":"Renai Bakumatsu Kareshi","p":[],"l":"https://en.wikipedia.org/wiki/Renai_Bakumatsu_Kareshi"},{"t":"Resident Evil 7: Biohazard","p":["Windows","PlayStation 4","Xbox One"],"g":"Survival horror","r":"January 24","l":"https://www.igdb.com/games/resident-evil-7-biohazard","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobtwh.jpg","s":"Resident Evil 7: Biohazard is the first game of the Resident Evil series to switch from 3rd-person to fully 1st-person perspective. A complete refresh of gameplay systems simultaneously propels the survival horror experience to another level. It is as much horror as it is survival, boosting up scare elements and minimizing downright shooting action. The game allows use of Sony's PSVR Headset to play in VR mode."},{"t":"Resident Evil: Revelations","p":["PlayStation 4","Xbox One","Nintendo Switch"],"g":"Survival horror","r":"August 31"},{"t":"Resident Evil: Revelations 2","p":["Nintendo Switch"],"g":"Survival horror","r":"November 28"},{"t":"Retro City Rampage DX","p":["Nintendo Switch"],"d":"Vblank Entertainment","u":"Vblank Entertainment","r":"August 3, 2017","l":"https://en.wikipedia.org/wiki/Retro_City_Rampage"},{"t":"Revenant Saga","p":["PlayStation 4","PlayStation 3","PlayStation Vita"],"r":"May 9","l":"https://en.wikipedia.org/wiki/Revenant_Saga"},{"t":"Rick and Morty: Virtual Rick-ality","p":["SteamVR","PlayStation VR","Oculus Rift","Windows"],"d":"Owlchemy Labs","u":"Adult Swim Games","g":"Adventure game","r":"April 20, 2017","l":"https://en.wikipedia.org/wiki/Rick_and_Morty:_Virtual_Rick-ality","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ou.jpg","s":"Rick and Morty have teleported into your living room for a cutting-edge VR adventure from Adult Swim Games and Owlchemy Labs (Job Simulator). Play as a Morty clone as you explore Rick's garage, the Smith household, and alien worlds.\n\nExperience life as a clone of Morty and all the trauma that comes with it. Step through portals to strange worlds, help Rick with his bizarre experiments, and use your hands in VR to pick up and play in an interaction-filled 3D Rick-ality. Follow Rick's directions (or don't!) to solve puzzles and complete missions in this fully voice acted adventure."},{"t":"Ride 2","p":["PlayStation 4","Xbox One"],"g":"Racing","r":"February 14","l":"https://en.wikipedia.org/wiki/Ride_2"},{"t":"Rime","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Puzzle","r":"May 26","l":"https://en.wikipedia.org/wiki/Rime_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h4w.jpg","s":"A third-person exploratory action/adventure title in which a boy ends up on a mysterious island and makes his way through its highly stylized environments, containing puzzles and slight navigation challenges, to get to the bottom of why he's ended up there and to reach the end of the road he's inadvertently begun to travel."},{"t":"Rise & Shine","p":["Windows","Xbox One"],"g":"Shooter, Platform, Puzzle, Adventure, Indie, Arcade","r":"January 13","l":"https://www.igdb.com/games/rise-and-shine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fxh5b0rjydf4ldfng8ze.jpg","s":"The game mixes pure shooting arcade with the use of different bullets to solve all the situations Rise will find on his path. Think of a more arcadey Another World, also with a very tight relationship between gameplay and story."},{"t":"Rising Storm 2: Vietnam","p":["Windows"],"g":"Tactical shooter, FPS","r":"May 30","l":"https://www.igdb.com/games/rising-storm-2-vietnam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hmu.jpg","s":"Rising Storm 2: Vietnam is a sequel to the stand-alone expansion pack to Rising Storm and focuses on the Vietnam War."},{"t":"Rivals of Aether","p":["Windows"],"g":"Fighting","r":"March 28","l":"https://en.wikipedia.org/wiki/Rivals_of_Aether","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobl61.jpg","s":"Rivals of Aether is an indie fighting game set in a world where warring civilizations summon the power of Fire, Water, Air, and Earth. Play with up to four players locally or up to two players online."},{"t":"Road Rage","p":["Windows","PlayStation 4","Xbox One"],"g":"Vehicular combat , Racing","r":"November 14","l":"https://en.wikipedia.org/wiki/Road_Rage_(2017_video_game)"},{"t":"Road Redemption","p":["Windows","macOS","Linux"],"d":"Redemption Road Games, Pixel Dash Studios","u":"Tripwire Interactive","g":"Vehicular combat, racing","r":"October 4, 2017","l":"https://en.wikipedia.org/wiki/Road_Redemption","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hlo.jpg","s":"Lead your motorcycle gang on an epic journey across the country in this brutal driving combat adventure. Earn money by completing races, assassinations, robberies, and other challenges in your path. As you collect loot, you'll upgrade your character, your bike, and your weapons."},{"t":"Robbie Swifthand and the Orb of Mysteries","p":["Windows","macOS"],"d":"Pixel Reign","u":"Pixel Reign, East2west Games, Kiss Publishing","g":"Platform","r":"December 5, 2017","l":"https://en.wikipedia.org/wiki/Robbie_Swifthand_and_the_Orb_of_Mysteries","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mm2.jpg","s":"Robbie Swifthand and the Orb of Mysteries! A hardcore 2D platformer that will mess with your mind and test your skills. Enter a Temple full of devious traps and of course, lots of treasure!"},{"t":"Robo Recall","p":["Windows"],"g":"FPS","r":"March 1","l":"https://en.wikipedia.org/wiki/Robo_Recall"},{"t":"Robocraft","p":["Windows","macOS","Linux","Xbox One"],"d":"Freejam Games","u":"Freejam Games","g":"Vehicular combat, third-person shooter","r":"August 24, 2017","l":"https://en.wikipedia.org/wiki/Robocraft","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coctqp.jpg","s":"Robocraft is a sandbox building and vehicular combat game where players get to create their own robots/vehicles and use them to fight others. The wide variety of components allows for many types of creations, including ground vehicles, planes and hover-tanks."},{"t":"Robonauts","p":["Nintendo Switch","PlayStation 4"],"d":"QubicGames","u":"QubicGames","g":"Shooting game","r":"September 15, 2017","l":"https://en.wikipedia.org/wiki/Robonauts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ym0.jpg","s":"Jump between planets, fight weird creatures, and save the galaxy alone or with a friend.\n\nRobonauts combines familiar arcade shooting gameplay with a unique possibility to switch gravity. Colorful graphics appeal to both younger and adult players while first-class music by Simon Viklund makes the adventure feel even more epic."},{"t":"Rock of Ages 2: Bigger & Boulder","p":["PlayStation 4","Windows","Xbox One"],"d":"ACE Team","u":"Atlus USA, Sega","g":"Tower defense, racing","r":"August 28, 2017","l":"https://en.wikipedia.org/wiki/Rock_of_Ages_2:_Bigger_&_Boulder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wgk.jpg","s":"The greatest \"giant rocks rolling through historical/artistic ages\" tower defense game is back with Rock of Ages II: Bigger and Boulder. With an emphasis on the chaotic new 2-vs-2 multiplayer, new time periods, and improved graphics, physics, and destructibility powered by Unreal Engine 4, players will need to be ready for some intense rocking and rolling."},{"t":"Rocket League","p":["Nintendo Switch"],"g":"Sports","r":"November 14","l":"https://en.wikipedia.org/wiki/Rocket_League"},{"t":"Rogue Hearts","p":["iOS","Android"],"d":"Ninetail Games","u":"Ninetail Games","g":"RPG","r":"August 8"},{"t":"Rogue Trooper Redux","p":["Windows","PlayStation 4","Xbox One"],"r":"October 17","l":"https://en.wikipedia.org/wiki/Rogue_Trooper"},{"t":"Romancing SaGa 2","p":["Windows","Nintendo Switch","PlayStation 4","PlayStation Vita","Xbox One"],"g":"RPG","r":"December 15","l":"https://en.wikipedia.org/wiki/Romancing_SaGa_2"},{"t":"Rugby 18","p":["PlayStation 4","Windows","Xbox One"],"d":"Eko Software","u":"Bigben Interactive","g":"Sports, simulation","r":"October 27, 2017","l":"https://en.wikipedia.org/wiki/Rugby_18","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27w8.jpg","s":"Live the intensity of the greatest matches with RUGBY 18. Play as the most prestigious teams and championships: Aviva Premiership Rugby, PRO14, National Teams... Master all the game phases, face other players online and build up your dream team in My Squad mode."},{"t":"Rugby League Live 4","p":["PlayStation 4","Xbox One","Windows"],"d":"Big Ant Studios","u":"Tru Blu Entertainment","g":"Sports","r":"July 28, 2017","l":"https://en.wikipedia.org/wiki/Rugby_League_Live_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4h39.jpg","s":"LET’S MAKE HISTORY - Rugby League Live 4 brings you the most intense and feature packed Rugby League experience ever."},{"t":"Ruiner","p":["Windows","PlayStation 4","Xbox One"],"g":"Shooter, Strategy, Adventure, Indie","r":"September 26","l":"https://www.igdb.com/games/ruiner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6knu.jpg","s":"Ruiner is a top-down action shooter created in the spirit of cult cyberpunk anime and game classics. Ruiner is quick and brutal but sophisticated gameplay, original world with mature storyline and unique visual style."},{"t":"Rumu","p":["Windows","Linux","macOS"],"d":"Robot House","u":"Hammerfall Publishing","g":"Point-and-click adventure","r":"December 12","l":"https://en.wikipedia.org/wiki/Rumu"},{"t":"Samurai Warriors: Spirit of Sanada","p":["Windows","PlayStation 4"],"g":"Hack and slash, Action","r":"May 26"},{"t":"Sansar","p":["Windows"],"l":"https://en.wikipedia.org/wiki/Sansar_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1sf0.jpg","s":"Welcome to Sansar, an oasis for self-expression, exploration, and live events in a virtual world, where players shape the narrative as it unfolds. Join us on a quest, or create your own. C’mon, your world is waiting. Play on desktop or in VR."},{"t":"Scanner Sombre","p":["macOS","Windows"],"d":"Introversion Software","u":"Introversion Software","g":"Exploration","r":"April 26, 2017","l":"https://en.wikipedia.org/wiki/Scanner_Sombre","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co222j.jpg","s":"Inspired by Gone Home and Dear Esther, Scanner Sombre is a cave exploration experience. With stunning visuals and a terrifying theme, it is the 6th major video game released by Introversion Software."},{"t":"School Girl/Zombie Hunter","p":["PlayStation 4"],"g":"TPS","r":"January 12","l":"https://en.wikipedia.org/wiki/School_Girl/Zombie_Hunter"},{"t":"SCP: Secret Laboratory","p":["Windows"],"d":"Northwood Studios","u":"Northwood Studios","g":"Survival horror, first-person shooter","r":"December 29, 2017","l":"https://en.wikipedia.org/wiki/SCP:_Secret_Laboratory","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobqc0.jpg","s":"Deep within a secure underground facility, a sudden containment breach allows many of the secured anomalies to escape from their chambers. Assist the Foundation in re-securing the facility, help the Insurgency in their goal to capture it, or wreak havoc as an SCP in a frantic bid to escape."},{"t":"Seasons After Fall","p":["PlayStation 4","Xbox One"],"g":"Puzzle-platformer","r":"May 16","l":"https://en.wikipedia.org/wiki/Seasons_After_Fall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1twv.jpg","s":"Seasons after Fall is a game about adventure and exploration, crafted with gorgeous two-dimensional visuals.\n\nThe spirits of the four seasons are gone. Something is definitely happening in the forest, something that never happened before. Is this true? Travel in search of the spirits to bring them back in their steles and use their power to explore the world of Seasons after Fall.\n\nYou are a wild fox embarked upon a perilous adventure, with mystical powers that allow you to manipulate the seasons, and the life of the forest. Powers that allow you to modify the environment by summoning one of the four seasons, whenever and wherever you wants.\n\nChanging the seasons will modify organic platforming elements that will move or expand based on which season you switch too, altering your relationship with the game and its characters. Seasons after Fall encourages the player to explore a gorgeous 2D graphical world, accompanied by an enchanting soundtrack recorded by a live string quartet. Travel in search of the Four Guardians of Seasons, and become the master of the seasons they protect.\n\nSummon winter to freeze a waterfall to pass, or call for Spring to feed a plant that will guide you to a previously inaccessible zone. Travel across forests, rivers and caves, and manipulate an ecosystem that is as disturbing as it is marvelous to unveil the secrets of this world."},{"t":"Secret World Legends","p":["Windows"],"r":"June 23","l":"https://en.wikipedia.org/wiki/Secret_World_Legends"},{"t":"Seiken Densetsu Collection","p":["Nintendo Switch"],"g":"Action RPG, Action-adventure, RTS","r":"June 1","l":"https://en.wikipedia.org/wiki/Seiken_Densetsu_Collection"},{"t":"Sekaiju to Fushigi no Dungeon 2","p":["Nintendo 3DS"],"g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Sekaiju_to_Fushigi_no_Dungeon_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30tb.jpg"},{"t":"Sengoku Night Blood","p":["Android"],"l":"https://en.wikipedia.org/wiki/Sengoku_Night_Blood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co713p.jpg","s":"Sengoku Night Blood was a Japanese free-to-play otome game, developed as a collaboration between Marvelous Entertainment, Kadokawa, and Idea Factory's Otomate. It was released in Japan on May 29, 2017, for Android and iOS devices. A 12-episode anime television series adaptation by Typhoon Graphics aired between October 3 and December 26, 2017. A Nintendo Switch port of the game was planned, but it was announced on October 24, 2019 that the Switch port was cancelled along with the mobile game being discontinued on December 25, 2019."},{"t":"Senko no Ronde 2","p":["Windows","PlayStation 4"],"g":"Fighting, Shooter","r":"September 6","l":"https://en.wikipedia.org/wiki/Senko_no_Ronde"},{"t":"Senran Kagura: Peach Beach Splash","p":["PlayStation 4"],"g":"TPS","r":"March 16"},{"t":"Serial Cleaner","p":["Linux","macOS","PlayStation 4","Windows","Xbox One","Nintendo Switch"],"d":"Draw Distance","u":"Curve Digital, Plug In Digital","g":"Stealth game","r":"July 14, 2017","l":"https://en.wikipedia.org/wiki/Serial_Cleaner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tve.jpg","s":"Serial Cleaner is a story-driven, fast-paced stealth/action game, characterized by a 1970s theme and aesthetics."},{"t":"Serious Sam VR: The Last Hope","p":["Windows"],"d":"Croteam VR","u":"Devolver Digital","g":"First-person shooter","r":"September 20, 2017","l":"https://en.wikipedia.org/wiki/Serious_Sam_VR:_The_Last_Hope"},{"t":"Serious Sam's Bogus Detour","p":["Linux","Windows"],"d":"Crackshell","u":"Devolver Digital","g":"Twin-stick shooter","r":"June 20, 2017","l":"https://en.wikipedia.org/wiki/Serious_Sam's_Bogus_Detour","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45wt.jpg","s":"Serious Sam’s Bogus Detour is an all-new action-adventure in the legendary Serious Sam saga from Hammerwatch developer Crackshell. Battle through beautiful Mediterranean locales, dangerous biological weapons labs and even high-tech moon bases as a one-man wrecking crew or in four-player online cooperative for maximum chaos! Dominate the chaotic Survival and Versus modes or make your own mods, modes, and even total conversions with the include game editor. Serious Sam’s Bogus Detour is the biggest little Serious Sam game ever made!"},{"t":"Seven: The Days Long Gone","p":["Windows"],"g":"RPG","r":"December 1"},{"t":"Shadow Warrior 2","p":["PlayStation 4","Xbox One"],"g":"FPS","r":"May 19","l":"https://en.wikipedia.org/wiki/Shadow_Warrior_2"},{"t":"Shantae: Half-Genie Hero","p":["Nintendo Switch"],"g":"Platformer, Metroidvania","r":"June 8"},{"t":"Shell Shockers","p":["Browser","Windows","macOS"],"u":"Blue Wizard Digital","g":"FPS, Shooter","r":"September 1, 2017","l":"https://en.wikipedia.org/wiki/Shell_Shockers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co90wo.jpg","s":"Shell Shockers is the world’s most popular egg-based multiplayer first person shooter io game! Take control of a heavily armed egg and battle real players across multiplayer maps in private or public arenas. The hit free to play FPS io game comes to your mobile device for eggciting free-range action!"},{"t":"Shiness: The Lightning Kingdom","p":["Windows","PlayStation 4","Xbox One"],"r":"April 18"},{"t":"Shovel Knight: Specter of Torment","p":["Nintendo Switch","Linux","macOS","Windows","Wii U","Nintendo 3DS","PlayStation 3","PlayStation 4","PlayStation Vita","Xbox One"],"d":"Yacht Club Games","u":"Yacht Club Games","g":"Platform","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Shovel_Knight:_Specter_of_Torment","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gsu.jpg","s":"This game is a free expansion included in the main game, Shovel Knight, and its updated title, Shovel Knight: Treasure Trove. The game will also be available as a standalone title on PC, PS4, Xbox One, and Nintendo Switch."},{"t":"Shovel Knight: Treasure Trove","p":["Nintendo Switch"],"d":"Yacht Club Games","u":"Yacht Club Games","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Shovel_Knight"},{"t":"Simulacra","p":["Android","iOS","Windows"],"d":"Kaigan Games","u":"Kaigan Games","g":"Horror","r":"October 26, 2017","l":"https://en.wikipedia.org/wiki/Simulacra_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24d0.jpg","s":"An interactive horror experience of exploring a missing woman’s phone."},{"t":"Sine Mora EX","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Shoot 'em up","r":"August 8","l":"https://en.wikipedia.org/wiki/Sine_Mora"},{"t":"SingStar Celebration","p":["PlayStation 4"],"r":"October 24","l":"https://en.wikipedia.org/wiki/SingStar_Celebration"},{"t":"SINoALICE","p":["Android","iOS"],"d":"Pokelabo","u":"Square Enix, Pokelabo","g":"Role-playing game","r":"June 6, 2017","l":"https://en.wikipedia.org/wiki/SINoALICE","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nvz.jpg","s":"A Japanese mobile game directed by Yoko Taro. It is developed by Pockelabo and published Square Enix."},{"t":"Skylanders: Imaginators","p":["Nintendo Switch"],"g":"Platformer, RPG","r":"March 3"},{"t":"Skylar & Plux: Adventure on Clover Island","p":["Windows","PlayStation 4","Xbox One"],"g":"Platformer","r":"May 19"},{"t":"Slice Dice and Rice","p":["PlayStation 4"],"r":"December 20"},{"t":"Slime Rancher","p":["Windows","macOS","Linux","Xbox One"],"g":"Life sim , Adventure","r":"August 1","l":"https://en.wikipedia.org/wiki/Slime_Rancher","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co73i2.jpg","s":"Slime Rancher is a charming, first-person, sandbox experience. Play as Beatrix LeBeau: a plucky, young rancher who sets out for a life a thousand light years away from Earth on the 'Far, Far Range.' Each day will present new challenges and risky opportunities as you attempt to amass a great fortune in the business of slime ranching. Collect colorful slimes, grow crops, harvest resources, and explore the untamed wilds through the mastery of your all-purpose vacpack."},{"t":"Snack World","p":[],"l":"https://en.wikipedia.org/wiki/Snack_World"},{"t":"Snake Pass","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Puzzle-platformer","r":"March 28","l":"https://en.wikipedia.org/wiki/Snake_Pass_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86dd.jpg","s":"Welcome to Snake Pass; a physical action-puzzle game that sees the player slither, curl and climb their way through increasingly challenging worlds filled with evermore intricate obstacles and fiendishly mind-bending objectives!\n\nSnake Pass is the wriggling brain-child of Seb Liese, who originally came to Sumo from Holland to work on the LittleBigPlanet team. His prototype of ‘real snake physics’ captured the entire studio’s imagination and we’re really proud of the results so far!"},{"t":"Sniper Elite 4","p":["Windows","PlayStation 4","Xbox One"],"g":"Tactical shooter, Stealth","r":"February 14","l":"https://en.wikipedia.org/wiki/Sniper_Elite_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24t8.jpg","s":"Sniper Elite 4 combines genre-defining ballistics, breathless emergent stealth, and gripping third person action across the largest and most diverse environments ever seen in a Sniper Elite game.\n\nSet in the aftermath of its award-winning predecessor, Sniper Elite 4 continues the series’ World War Two heritage by transporting players across the beautiful Italian peninsula, from sun-drenched Mediterranean coastal towns, to colossal Nazi mega structures, daunting forests and giddying mountain monasteries inspired by Monte Cassino.\n\nCovert agent and elite marksman Karl Fairburne must fight alongside the brave men and women of the Italian Resistance to help free their country from the yoke of Fascism, and defeat a terrifying new threat with the potential to halt the Allied fightback in Europe before it’s even begun.\n\nIf his mission fails, there will be no Operation Overlord, no D-Day landings, and no Victory in Europe."},{"t":"Sniper Ghost Warrior 3","p":["Windows","PlayStation 4","Xbox One"],"g":"Tactical shooter, Stealth","r":"April 25","l":"https://en.wikipedia.org/wiki/Sniper_Ghost_Warrior_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa11j.jpg","s":"Go behind enemy lines with the ultimate modern military shooter. Play as an American sniper dropped in Georgia, near Russian border. Choose your own path to accomplish your missions across an unforgiven open world."},{"t":"Snipperclips","p":["Nintendo Switch"],"g":"Puzzle","r":"March 3","l":"https://en.wikipedia.org/wiki/Snipperclips"},{"t":"Snipperclips: Cut It Out, Together!","p":["Nintendo Switch"],"d":"SFB Games","u":"Nintendo","g":"Platform, Puzzle","r":"March 3, 2017","l":"https://www.igdb.com/games/snipperclips-cut-it-out-together","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27vu.jpg","s":"Cut paper characters into new shapes to solve dynamic puzzles and play activities in a wonderfully creative and imaginative world!"},{"t":"Soldam: Drop, Connect, Erase","p":["Nintendo Switch","PlayStation 4"],"g":"Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Soldam:_Drop,_Connect,_Erase","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kuf.jpg","s":"Play one of the original tile-matching games from the 90’s. Dispatch Games brings back the Jaleco arcade classic with, Soldam: Drop, Connect, Erase. The game has been refreshed with updated graphics and gameplay, but retains its arcade charm with its catchy music and unique style that have been fan favorites for many years."},{"t":"Solstice Chronicles: MIA","p":["Windows","Nintendo Switch"],"d":"Ironward","g":"Twin-stick shooter","l":"https://en.wikipedia.org/wiki/Solstice_Chronicles:_MIA","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iz0.jpg","s":"Battle for survival against waves of Martian mutants in this tactical twist on twin-stick shooters. Using the skills of your drone companion, make fight-or-flight decisions that drastically alter the threats you face. Will your choices lead you to freedom... or your doom?"},{"t":"Something Something Soup Something","p":["Windows","macOS","Linux","Browser"],"d":"Stefano Gualeni","g":"Point and click","l":"https://en.wikipedia.org/wiki/Something_Something_Soup_Something","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9k5j.jpg","s":"Players are presented with 20 concoctions and are asked to determine whether they are soup or not."},{"t":"Songbringer","p":["Linux","macOS","Windows","Xbox One","PlayStation 4","iOS"],"d":"Wizard Fu Games","u":"Wizard Fu Games, Double Eleven","g":"Action role-playing","r":"September 1, 2017","l":"https://en.wikipedia.org/wiki/Songbringer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1szv.jpg","s":"Songbringer is a sci-fi, pixel, action-adventure game in which one journeys through procedurally-generated, Zelda-inspired worlds. Along the way one will uncover powerful artifacts and forge them anew. Those skilled with the nanosword will vanquish giants and save a planet from being overrun."},{"t":"Sonic Forces","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Platformer","r":"November 7","l":"https://en.wikipedia.org/wiki/Sonic_Forces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zr8.jpg","s":"Fight through a world destroyed by Dr. Eggman and a powerful new villain in Sonic Forces, the new fast-paced action platformer from the team that brought you Sonic Colors and Sonic Generations. Sonic Forces lets you speed through rolling ruined landscapes as Modern Sonic, catapult past perilous platforms as Classic Sonic, and use powerful new gadgets as your own Custom Hero Character."},{"t":"Sonic Mania","p":["Nintendo Switch","PlayStation 4","Xbox One","Windows"],"g":"Platformer","r":"August 15","l":"https://en.wikipedia.org/wiki/Sonic_Mania","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob1t0.jpg","s":"Sonic Mania is a side-scrolling platformer that pays homage to the original Sega Genesis Sonic the Hedgehog games. Players choose from Sonic, Tails, or Knuckles, each with unique abilities, and speed through 13 zones that include redesigned stages from past games alongside original levels. The game features special stages for collecting Chaos Emeralds, time attack with online leaderboards, and split-screen competitive multiplayer."},{"t":"Sonic Runners Adventure","p":["Android","Mobile phone","iOS"],"d":"Gameloft S.E.","u":"Gameloft","g":"Endless runner, platformer","r":"June 10, 2017","l":"https://en.wikipedia.org/wiki/Sonic_Runners_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ggt.jpg","s":"Sonic the Hedgehog and his friends are back in an action-packed runner game!\n\nCatch speed fever as you relive the Sonic legend. Run, jump, dash or fly across the road and through exciting platformer levels. Unlock new characters including Tails, Knuckles and more, each with their own unique abilities you can power up. Rush to save Sonic's universe by fighting Dr. Eggman across 4 iconic locations."},{"t":"Sorcer Striker","p":["PlayStation 4"],"g":"Scrolling shooter","r":"November 2","l":"https://en.wikipedia.org/wiki/Sorcer_Striker"},{"t":"South Park: Phone Destroyer","p":["iOS","Android"],"d":"Ubisoft RedLynx","u":"Ubisoft","g":"Real-time strategy, action, collectible card game","r":"November 9, 2017","l":"https://en.wikipedia.org/wiki/South_Park:_Phone_Destroyer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27vn.jpg","s":"South Park: Phone Destroyer combines real-time strategy, collectible cards and South Park characters as you’ve never seen them before to create a new brand of mobile role-playing game."},{"t":"South Park: The Fractured but Whole","p":["Windows","PlayStation 4","Xbox One"],"g":"RPG","r":"October 17","l":"https://www.igdb.com/games/south-park-the-fractured-but-whole","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1v8w.jpg","s":"Players will once again assume the role of the New Kid, and join South Park favorites Stan, Kyle, Kenny and Cartman in a new hilarious and outrageous adventure. This time, players will delve into the crime-ridden underbelly of South Park with Coon and Friends.\n\nThis dedicated group of crime fighters was formed by Eric Cartman whose superhero alter-ego, The Coon, is half man, half raccoon. As the New Kid, players will join Mysterion, Toolshed, Human Kite, Mosquito, Mint Berry Crunch and a host of others to battle the forces of evil while Coon strives to make his team the most beloved superheroes in history."},{"t":"Space Pirate Trainer","p":["Windows"],"d":"I-Illusions","g":"Shooter, Arcade","r":"October 12, 2017","l":"https://en.wikipedia.org/wiki/Space_Pirate_Trainer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xrs.jpg","s":"Space Pirate Trainer is the official trainer for wannabe space pirates on the HTC Vive. Pick up your blasters, put on your sneakers, and dance your way into the Space Pirate Trainer hall of fame."},{"t":"Spacelords","p":["Windows","PlayStation 4","Xbox One"],"d":"MercurySteam","u":"MercurySteam","g":"Action-adventure","r":"September 22, 2017","l":"https://en.wikipedia.org/wiki/Spacelords","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24tk.jpg","s":"Embark on an epic sci-fi, free-to-play adventure. Spacelords is a brand-new take on the shooter genre. Through its 4 vs 1 campaign, you experience both sides of the story: Join the Raiders in their fight to free the legendary Broken Planet, or switch sides and fight as the Antagonist alongside the invading"},{"t":"Spaceplan","p":["Android","iOS","macOS","Windows"],"d":"Jake Hollands","u":"Devolver Digital","g":"Simulator, Adventure, Indie","r":"May 3, 2017","l":"https://en.wikipedia.org/wiki/Spaceplan","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24tl.jpg","s":"SPACEPLAN is an experimental piece of interaction based partly on a total misunderstanding of Stephen Hawking’s A Brief History of Time. Use manual clicks and the passage of time to create and launch potato-based devices and probes from your nondescript satellite orbiting a mysterious planet. Unlock the mysteries of the galaxy or just kill some time in what the astrophysics community is calling the ‘best narrative sci-fi clicker game of all times’."},{"t":"Spark the Electric Jester","p":["Windows"],"d":"Feperd Games","u":"Feperd Games","g":"Platform","r":"April 10, 2017","l":"https://en.wikipedia.org/wiki/Spark_the_Electric_Jester","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24tq.jpg","s":"Spark the electric jester is an action/platformer video game heavily based on best classics from the 16-bit era from both sides of the aisle.\nYou play as Spark, an electric jester frustrated by the loss of his job! On one beautiful day, robots decided to take over the world. Seeing as Spark’s job was taken by a robot, he decided this was the perfect opportunity for his revenge! Spark will have to travel through the world and be engulfed in high-speed thrills and tons of action against the robots and the one who has taken his job."},{"t":"SpellForce 3","p":["Windows"],"g":"RTS, RPG","r":"December 7","l":"https://en.wikipedia.org/wiki/SpellForce_3"},{"t":"Spelunker Party!","p":["Windows","Nintendo Switch"],"g":"Platformer","r":"October 19","l":"https://en.wikipedia.org/wiki/Spelunker_(video_game)#Legacy"},{"t":"Spirit Hunter: Death Mark","p":["PlayStation Vita"],"g":"Adventure, Visual novel","r":"June 1"},{"t":"Splasher","p":["Windows"],"g":"Platformer","r":"February 7","l":"https://en.wikipedia.org/wiki/Splasher_(video_game)"},{"t":"Splatoon 2","p":["Nintendo Switch"],"g":"TPS","r":"July 21","l":"https://en.wikipedia.org/wiki/Splatoon_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8r9.jpg","s":"Splatoon 2 is a multiplayer third-person shooter in which players control characters known as Inklings and use colored ink to attack opponents and clear goals. Inklings can alternate between humanoid form, during which they can fire ink with their weapons, and squid form, which allows them to swim through ink of their own color in order to move quickly and replenish ink supplies."},{"t":"Stack Jump","p":["iOS","Android"],"d":"Voodoo","g":"Action","r":"July 27, 2017","l":"https://en.wikipedia.org/wiki/Stack_Jump","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc62o.jpg","s":"How high can you climb?\n\nJump to stack blocks and build the biggest tower imaginable!\n\nImprove your highscore in endless mode, complete the 36 challenges and unlock all 20 characters!"},{"t":"Standoff 2","p":["Android","iOS"],"d":"Axlebolt","u":"Axlebolt","g":"First-person shooter","r":"April 17, 2017","l":"https://en.wikipedia.org/wiki/Standoff_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobc42.jpg","s":"Standoff 2 is a free-to-play first-person action shooter with over 300 million installs worldwide. Immerse yourself in the engaging world of tactical battles and dynamic firefights in the free-to-play multiplayer shooter genre."},{"t":"Star Fox 2","p":["Super Nintendo Entertainment System"],"g":"Shoot 'em up, RTS","r":"September 29","l":"https://en.wikipedia.org/wiki/Star_Fox_2"},{"t":"Star Trek: Bridge Crew","p":["HTC Vive","Meta Quest","PlayStation VR"],"g":"Action-adventure","r":"May 30"},{"t":"Star Wars Battlefront II","p":["Windows","PlayStation 4","Xbox One"],"g":"FPS, TPS","r":"November 17","l":"https://en.wikipedia.org/wiki/Star_Wars_Battlefront_II_(2017_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wi7.jpg","s":"Star Wars Battlefront II is a first- and third-person shooter set across all three eras of the Star Wars saga. Players engage in large-scale ground and space battles using class-based soldiers, reinforcements, vehicles, and iconic heroes or villains from the franchise. Multiplayer modes span maps drawn from locations across the films, while a single-player campaign follows an original story set between Return of the Jedi and The Force Awakens. The game launched in 2017 amid a major loot box controversy that led to the removal of microtransactions and a complete overhaul of its progression system, after which it received years of free content updates that substantially expanded its offerings."},{"t":"Star Wars: Force Arena","p":["Android","iOS"],"d":"Netmarble Monster","u":"Netmarble","g":"Strategy","r":"January 12, 2017","l":"https://en.wikipedia.org/wiki/Star_Wars:_Force_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rev.jpg","s":"In Star Wars™: Force Arena you will lead a powerful team of iconic Star Wars™ characters, including new favorites from Rogue One™: A Star Wars™ Story, into real-time, adrenaline-fueled battles against other players from around the globe! Players must form a powerful squad from a roster of over 80 upgradable characters and units to emerge victorious in the quest for galactic dominance. \n \n● BATTLE or join forces with other players from around the globe in real-time 1v1 or 2v2 PvP arena battles. \n \n● LEAD a team of iconic Star Wars™ characters including Han Solo, Darth Vader, and even new Rogue One™: A Star Wars™ Story characters such as Jyn Erso or Grand Moff Tarkin! \n \n● COLLECT character cards and upgrade your favorites to create the ideal Rebel or Imperial squad while leveraging powerful character duos that boost your effectiveness in battle. \n \n● COMPETE to earn rewards, special characters and bonus items by participating in events as you climb to the top of the leaderboards on your journey for galactic dominance!"},{"t":"StarBlood Arena","p":["PlayStation VR"],"r":"April 11"},{"t":"StarCraft: Remastered","p":["Windows"],"g":"RTS","r":"August 14","l":"https://www.igdb.com/games/starcraft-remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wal.jpg","s":"StarCraft: Remastered is a reverently crafted modernization of Blizzard Entertainment’s original sci-fi real-time strategy game. StarCraft: Remastered will offer a full graphical overhaul of the original StarCraft and the StarCraft: Brood War expansion, bringing a modern look and feel to the timeless classic with widescreen UHD support for up to 4K resolution.\n\nStarCraft: Remastered will include all of StarCraft’s and Brood War’s campaign missions with enhanced storytelling via new comic-book style interludes. While this rejuvenated version of StarCraft is locked and loaded for the modern era, the gameplay and balance have been precisely preserved, for an experience that will feel identical to veteran players.\n\n4K Ultra HD Graphics and Upgraded Audio: StarCraft: Remastered will include high-resolution unit models, buildings, doodads, and tilesets, as well as high-fidelity music and sound effects to bring the original game into the modern era, while retaining the classic StarCraft style.\n\nSame Timeless Gameplay: The gameplay balance and idiosyncrasies have been painstakingly preserved from the original game. Mutalisk stacking, magic-boxing, unit pathfinding, control-group limitations, and more will all remain intact, allowing veteran players to enjoy playing and watching high-level competitive matches as before.\n\nIncludes Original and Expansion Campaigns: Return to the planetary battlefields of the war-torn Koprulu Sector and command the forces of the terran, zerg, and protoss across more than 50 story-driven single-player missions.\n\nFall in Love Again: Relive the epic saga of some of gaming’s most memorable and beloved heroes and villains, including Marshal Jim Raynor, Lieutenant Sarah Kerrigan, and Praetor Fenix.\n\nEnhanced Storytelling: Original cinematics will be improved to 1080p resolution, while mission interludes and introductions will feature new comic-book style illustrations.\n\nBlizzard’s Gaming Network Brings a Bevy of Features: In addition to accurate matchmaking and enhanced ladder functionality, players will also be able to stay in touch with and chat with friends playing other Blizzard games. The classic functionality of named custom games and custom game lobbies will be retained, for the familiarity of long-time StarCraft players.\n\nLocalized in 13 Languages: English, German, French, Brazilian Portuguese, Spanish (LatAm), Spanish (European), Polish, Italian, Russian, Korean, Simplified Chinese, Traditional Chinese, and Japanese."},{"t":"StarCrawlers","p":["Windows","macOS","Linux"],"d":"Juggernaut Games","u":"Juggernaut Games","g":"Role-playing","r":"May 24, 2017","l":"https://en.wikipedia.org/wiki/StarCrawlers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24tz.jpg","s":"\"StarCrawlers is a modern take on a classic cRPG dungeon crawler set in a gritty spacepunk universe. Build a crew of renegade adventurers on the fringes of space, taking jobs from megacorps to hunt bounties, sabotage rivals and conduct corporate espionage.\""},{"t":"Stardew Valley","p":["Nintendo Switch"],"g":"Simulation, RPG","r":"October 5","l":"https://en.wikipedia.org/wiki/Stardew_Valley"},{"t":"Starpoint Gemini Warlords","p":["Windows"],"d":"Little Green Men Games","u":"Iceberg Interactive","g":"Space trading and combat simulator, role-playing, 4X","r":"May 23, 2017","l":"https://en.wikipedia.org/wiki/Starpoint_Gemini_Warlords","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z40.jpg","s":"A unique blend of space sim, RPG and 4X games. Conduct research and construction in your own gigantic space station, command your war fleets and heroic companions to invade enemy territory, build up your stronghold, trade, mine, salvage and remind your enemies why they fear you."},{"t":"Stars in Shadow","p":["Windows"],"d":"Ashdar Games","u":"Iceberg Interactive","g":"Turn-based strategy","r":"January 19, 2017","l":"https://en.wikipedia.org/wiki/Stars_in_Shadow","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24u1.jpg","s":"Stars in Shadow is a turn-based 4X strategy game and a vivid tribute to the genre classics. Compete with alien factions to explore and colonize nearby starsystems, build fleets to defend against rivals, negotiate or conquer them. Win by unifying the galaxy, through diplomacy or force."},{"t":"Stash: No Loot Left Behind","p":["Windows"],"d":"FrogDice","u":"FrogDice","g":"Turn-based, RPG","r":"September 7, 2017","l":"https://en.wikipedia.org/wiki/Stash:_No_Loot_Left_Behind"},{"t":"Statik","p":["PlayStation VR"],"r":"April 24"},{"t":"SteamWorld Dig 2","p":["Nintendo Switch","Windows","macOS","Linux","PlayStation 4","PlayStation Vita"],"g":"Platformer, Action-adventure, Metroidvania","r":"September 21","l":"https://en.wikipedia.org/wiki/SteamWorld_Dig_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24u8.jpg","s":"SteamWorld Dig 2 takes you on a platform mining adventure forged in Metroidvania flames. When an old trading town is struck by mysterious earthquakes, it’s up to a lone steambot and her unlikely companion to uncover what trembling terrors lie beneath.\n\nDig your way underground and explore vivid worlds riddled with treasure, secrets and traps.\n\nCombat dangerous enemies at every turn of the underworld’s twisted paths, including shadowy creatures and the haunted remains of an ancient electrical threat.\n\nUpgrade your gear to forge deeper into the earth and take on bigger challenges.\n\nSwing across large chasms with your Hookshot and fly through caves with the Jet Engine!\n\nAnd finally, learn the truth about your long lost friend…"},{"t":"SteamWorld Heist: Ultimate Edition","p":["Nintendo Switch"],"d":"Image & Form","u":"Image & Form","r":"December 28, 2017","l":"https://en.wikipedia.org/wiki/SteamWorld_Heist"},{"t":"Steel Division: Normandy 44","p":["Windows"],"d":"Eugen Systems","u":"Paradox Interactive","g":"Real-time strategy","r":"May 23, 2017","l":"https://en.wikipedia.org/wiki/Steel_Division:_Normandy_44","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24u9.jpg","s":"Steel Division: Normandy 44 is a Tactical Real-Time Strategy (RTS) game, developed by Eugen Systems, the creators of titles like Wargame and R.U.S.E. This new game puts players in command of detailed, historically accurate tanks, troops, and vehicles at the height of World War II. Players can measure their tactical skills against several opponents in big multiplayer battles or against enemies in a challenging single-player campaign. Steel Division: Normandy 44 allows players to take control over legendary military divisions from six different countries, such as the American 101st Airborne, the German armored 21st Panzer or the 3rd Canadian Division, during the invasion of Normandy in 1944."},{"t":"StepManiaX","p":["Arcade"],"d":"Step Revolution","g":"Music, Exergaming","r":"June 10, 2017","l":"https://en.wikipedia.org/wiki/StepManiaX"},{"t":"Stick Fight: The Game","p":["Windows","macOS","Nintendo Switch","PlayStation","Xbox","Android"],"d":"Landfall","u":"Landfall","g":"Action, fighting","r":"September 28, 2017","l":"https://en.wikipedia.org/wiki/Stick_Fight:_The_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86z5.jpg","s":"Stick Fight is a physics-based couch/online fighting game where you battle it out as the iconic stick figures from the golden age of the internet"},{"t":"Stories Untold","p":["macOS","Windows"],"d":"No Code","u":"Devolver Digital","g":"Adventure, puzzle","r":"February 27, 2017","l":"https://en.wikipedia.org/wiki/Stories_Untold_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45ws.jpg","s":"Stories Untold is a compilation tape of four episodes from the now cancelled series of the same name, including a remaster of the original pilot episode “The House Abandon”."},{"t":"Story of Seasons: Trio of Towns","p":["Nintendo 3DS"],"g":"Farming , RPG","r":"February 28"},{"t":"Strafe","p":["Windows"],"g":"FPS","r":"May 9","l":"https://en.wikipedia.org/wiki/Strafe_(video_game)"},{"t":"Style Savvy: Styling Star","p":["Nintendo 3DS"],"g":"Simulation","r":"December 25"},{"t":"Styx: Shards of Darkness","p":["Windows","PlayStation 4","Xbox One"],"g":"Stealth","r":"March 14","l":"https://www.igdb.com/games/styx-shards-of-darkness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24zt.jpg","s":"Embark upon a stealthy adventure with new enemies, new environments, and a plethora of new mechanics aimed at refining the abilities and movement of Styx; grappling around corners, climbing ropes, and using his trusty knife as a zip-wire. Shards of Darkness aims to offer unparalleled freedom of movement, along with refined stealth and assassination mechanics, expanding and improving on the strengths of Styx: Master of Shadows"},{"t":"Subsurface Circular","p":["Windows","macOS","iOS"],"d":"Mike Bithell Games","u":"Mike Bithell Games","g":"Text adventure","r":"August 17, 2017","l":"https://en.wikipedia.org/wiki/Subsurface_Circular","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mt7.jpg","s":"When the truth is buried, go underground. Step into this new take on text-based adventure from the award-winning team behind Thomas Was Alone and Volume. A short story that hands you the fate of the world above, as a detective looking for answers on the Subsurface Circular."},{"t":"Sudden Strike 4","p":["Windows","macOS","Linux","PlayStation 4"],"g":"RTT","r":"August 11","l":"https://en.wikipedia.org/wiki/Sudden_Strike_4"},{"t":"Summon Night 6: Lost Borders","p":["PlayStation 4","PlayStation Vita"],"g":"Tactical RPG","r":"October 31","l":"https://en.wikipedia.org/wiki/Summon_Night_6"},{"t":"Sundered","p":["Windows","PlayStation 4"],"g":"Platform, Adventure, Indie","r":"July 28","l":"https://www.igdb.com/games/sundered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/aq6qahkwjzwgdppbydcc.jpg","s":"Sundered is a horrifying fight for survival and sanity, a hand­-drawn epic from the ​creators of ​Jotun. You play Eshe, a wanderer in a ruined world, trapped in ever­-changing caverns teeming with eldritch horrors. Harness the power of corrupted relics to defeat gigantic bosses, at the cost of your humanity."},{"t":"Super Blood Hockey","p":["Windows"],"d":"Loren Lemcke","u":"Loren Lemcke","g":"Sports game","r":"August 17, 2017","l":"https://en.wikipedia.org/wiki/Super_Blood_Hockey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1krz.jpg","s":"Relive the golden age of arcade sports gaming with Super Blood Hockey — A violent homage to classic 8-bit and 16-bit ice hockey games.\n\nCustomize your line up and take to the ice, using fast-paced skills and bone-crunching brutality to dominate. Prove your hockey prowess in a deadly global tournament or against friends in 4-player local multiplayer. Build and manage your own squad in Franchise Mode - with the right diet and performance enhancing drugs your team can be season champions!\n\nKey Features\n\nUse superior skating, positioning, strategy and blood-splattering violence\n\nTake on the world in a global tournament, where failure results in execution\n\nVaried challenges and scenarios, including Turbo Mode and 12 vs 12 Mega Rumble\n\nPaint the ice with the blood of your friends in 4-player local multiplayer\n\nFranchise Mode: Create, recruit and manage your own custom team of inmates in a futuristic world of dystopic blood sports\n\nEnjoy the retro beats of an original soundtrack by chiptunist Shawn Daley"},{"t":"Super Bomberman R","p":["Nintendo Switch"],"g":"Action, Maze","r":"March 3","l":"https://en.wikipedia.org/wiki/Super_Bomberman_R","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2klt.jpg","s":"\"Since its release in 1985, Bomberman has been a familiar party-battle game for many years. Now, Bomberman is coming back as \"SUPER BOMBERMAN R\" to Nintendo Switch.\n\nIn SUPER BOMBERMAN R, the simple rule remains the same: operate the main character (Bomberman), place bombs, and battle with enemies and rivals, but it's coming back in a modern style with 3D stages and photo-real graphics. You can enjoy battles with rivals from all over the world.\n\nThere is \"Battle\" mode for maximum of 8 players, and single play \"Story\" mode (cooperative play for 2 players is possible as well) where players clear each stage one by one, with a big volume of 50 stages. Also, there is a new rule where the condition to clear the stage is not just by wiping out all the enemies. This simple but strategic game with new rules and 3D stages is fun for everyone, from children to adults.\""},{"t":"Super CloudBuilt","p":["Windows","PlayStation 4","Xbox One"],"r":"July 25"},{"t":"Super Hydorah","p":["Windows","Xbox One","PlayStation 4","PlayStation Vita"],"d":"Locomalito","u":"Abylight Studios","g":"Side-scrolling shoot 'em up","r":"September 20, 2017","l":"https://en.wikipedia.org/wiki/Super_Hydorah","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24uv.jpg","s":"Super Hydorah is a nonlinear horizontal shoot’ em up designed to offer a challenging experience, sublimating the richness of traditional shmup classics. Face the menace of the Meroptians aboard the Delta Force, alone or with your friends in this game with direct action and nostalgic art."},{"t":"Super Lucky's Tale","p":["Windows","Xbox One"],"g":"Platformer","r":"November 7","l":"https://en.wikipedia.org/wiki/Super_Lucky%27s_Tale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22o8.jpg","s":"Super Lucky’s Tale is a delightful, playground platformer for all ages that follows Lucky, the ever-optimistic and lovable hero, on his quest to find his inner strength and help his beloved sister rescue the Book of Ages from the nefarious Jinx. Head back to the era of classic platformers with challenges players of all skill levels and all ages can enjoy."},{"t":"Super Mario Odyssey","p":["Nintendo Switch"],"d":"Nintendo EPD","u":"Nintendo","g":"Platformer, Action-adventure","r":"October 27, 2017","l":"https://en.wikipedia.org/wiki/Super_Mario_Odyssey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mxf.jpg","s":"Explore incredible places far from the Mushroom Kingdom as you join Mario and his new ally Cappy on a massive, globe-trotting 3D adventure. Use amazing new abilities, like the power to capture and control objects, animals, and enemies to collect Power Moons so you can power up the Odyssey airship and save Princess Peach from Bowser’s wedding plans!"},{"t":"Super Mario Run","p":["Android"],"g":"Endless runner","r":"March 22","l":"https://en.wikipedia.org/wiki/Super_Mario_Run"},{"t":"Super Robot Wars V","p":["PlayStation 4","PlayStation Vita"],"d":"B.B. Studio","u":"Bandai Namco Entertainment","g":"Tactical role-playing","r":"February 23, 2017","l":"https://en.wikipedia.org/wiki/Super_Robot_Wars_V","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wjl.jpg","s":"Super Robot Wars V is a tactical role-playing game developed by B.B. Studio and published by Bandai Namco Entertainment for the PlayStation 4 and PlayStation Vita. Released as part of Super Robot Wars' 25th anniversary, it is the eighth standalone entry to the series since Super Robot Wars NEO, with the game's continued focus on the massive crossover between different mecha anime series released in Japan. It is released in Asia on February 23, 2017."},{"t":"Superbeat: Xonic","p":["PlayStation 4","Xbox One","Nintendo Switch"],"g":"Music, Rhythm","r":"June 6"},{"t":"Superdimension Neptune VS Sega Hard Girls","p":["Windows"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Sega_Hard_Girls#Video_game"},{"t":"Supreme Ruler The Great War","p":["Windows","macOS"],"d":"BattleGoat Studios","u":"BattleGoat Studios","g":"Strategy","r":"August 1, 2017","l":"https://en.wikipedia.org/wiki/Supreme_Ruler_The_Great_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24v1.jpg","s":"Real-Time Strategy/Wargame. BattleGoat Studios invites you to travel back to 1914 and select from more than 50 playable regions at the onset of World War I, as European powers struggle to survive and new technologies transform warfare."},{"t":"Surviv.io","p":["Browser"],"d":"Justin Kim, Nick Clark, Kongregate","g":"Battle royale","r":"October 11, 2017","l":"https://en.wikipedia.org/wiki/Surviv.io","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2vbj.jpg","s":"2D battle royal packed into an intense 3-5 minute experience. No lobbies, no lengthy drop sequences. In surviv.io, you're always in the fight!\n\nChoose the mode that fits your mood. Go it alone in solo mode, battle with a partner in duos, or field a four-person team in squads.\n\nLoot, loot everywhere. Famous firearms, melee weapons, throwables, medical items, armor, scopes, and backpacks to hold it all. Raid an air drop to get the rarest loot!\nTired of looting the same set of static locations every game?\n\nsurviv.io features something no other Battle Royale offers: a completely new map in each game. Every rock, tree, building, bunker, and river spawns in a randomly chosen place using our intelligent map generation tech.\n\nThe surviv.io dev team is dedicated to keeping the game fresh and exciting. We believe in frequent updates and open communication with the community. Join us on Discord and say hello!"},{"t":"Sword Art Online: Integral Factor","p":["Android","iOS"],"d":"Asobimo","u":"Bandai Namco Entertainment","g":"MMORPG","r":"December 2, 2017","l":"https://en.wikipedia.org/wiki/Sword_Art_Online:_Integral_Factor","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ri9.jpg","s":"Sword Art Online: Integral Factor is a new online RPG for mobile devices."},{"t":"Sword of the Vagrant","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"O.T.K Games","u":"SakuraGame, Rainy Frog LLC","g":"Hack and slash, role-playing video game","r":"June 9, 2017","l":"https://en.wikipedia.org/wiki/Sword_of_the_Vagrant"},{"t":"Syberia","p":["Nintendo Switch"],"g":"Graphic adventure","r":"October 20","l":"https://en.wikipedia.org/wiki/Syberia_(video_game)"},{"t":"Syberia II","p":["Nintendo Switch"],"g":"Graphic adventure","r":"November 30","l":"https://en.wikipedia.org/wiki/Syberia_II"},{"t":"Syberia III","p":["PlayStation 4","Xbox One"],"g":"Graphic adventure","r":"April 25","l":"https://en.wikipedia.org/wiki/Syberia_III"},{"t":"Syrian Warfare","p":["Windows","Steam"],"d":"Cats Who Play","u":"Cats Who Play","g":"Real-time tactics","r":"February 21, 2017","l":"https://en.wikipedia.org/wiki/Syrian_Warfare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24vf.jpg","s":"Real Time Strategy with a high degree of realism. The game is based on a true story."},{"t":"Tacoma","p":["Windows","macOS","Linux","Xbox One"],"g":"Adventure","r":"August 2","l":"https://en.wikipedia.org/wiki/Tacoma_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tge.jpg","s":"Tacoma is a sci-fi narrative adventure set aboard a high-tech space station in the year 2088. Explore every detail of how the station's crew lived and worked, finding the clues that add up to a gripping story of trust, fear, and resolve in the face of disaster."},{"t":"Taiko Drum Master: Drum Session","p":["PlayStation 4"],"r":"October 26"},{"t":"Taisho × Alice","p":[],"l":"https://en.wikipedia.org/wiki/Taisho_%C3%97_Alice"},{"t":"Take On Mars","p":["Windows"],"d":"Bohemia Interactive","u":"Bohemia Interactive","g":"Simulation","r":"February 9, 2017","l":"https://en.wikipedia.org/wiki/Take_On_Mars"},{"t":"Tales of Berseria","p":["Windows","PlayStation 4"],"g":"Action RPG","r":"January 24","l":"https://en.wikipedia.org/wiki/Tales_of_Berseria"},{"t":"Tanki X","p":["Windows","macOS"],"d":"AlternativaPlatform","u":"AlternativaPlatform","g":"Action, vehicular combat","r":"April 20, 2017","l":"https://en.wikipedia.org/wiki/Tanki_X","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9jy0.jpg","s":"Tanki X is a multiplayer tank-action game that's out to prove that when it comes to tanks, there's more than just thick shells and firepower. Get ready to strap on your seatbelt because you're in for some serious adrenaline!"},{"t":"Tannenberg","p":["Windows","macOS","Linux"],"g":"FPS","r":"November 16","l":"https://en.wikipedia.org/wiki/Tannenberg_(video_game)"},{"t":"Tasokare Hotel","p":["Android","iOS"],"g":"Point-and-click, Visual Novel","l":"https://en.wikipedia.org/wiki/Tasokare_Hotel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4sb3.jpg","s":"Tasokare Hotel is a free-to-play adventure game for iOS and Android that follows Neko Tsukahara, a high school student who awakens in a mysterious hotel between the worlds of the living and the dead with no memory of her identity. As she works as a hotel staff member, players navigate a blend of visual novel storytelling, point-and-click exploration to find clues in guest rooms, and interrogation segments where collected evidence is used to reveal the truth behind each guest's past. The game's progression is structured around a ticket system that grants five free story chapters daily, supplemented by a room-cleaning mini-game to earn experience points needed to unlock further content. Known for its atmospheric twilight setting and jazz-influenced soundtrack, the game also features a multi-ending story including a \"True End\" and several branching \"Bad Ends\"."},{"t":"Team Kirby Clash Deluxe","p":["Nintendo 3DS"],"g":"Action, Platformer","r":"April 12","l":"https://en.wikipedia.org/wiki/Team_Kirby_Clash_Deluxe"},{"t":"Tear: Owari to Hajimari no Shizuku","p":["PlayStation 4"],"r":"October 15"},{"t":"Tekken 7","p":["Windows","PlayStation 4","Xbox One"],"g":"Fighting","r":"June 2","l":"https://en.wikipedia.org/wiki/Tekken_7","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w4f.jpg","s":"Experience the epic conclusion of the Mishima clan and unravel the reasons behind each step of their ceaseless fight. Powered by Unreal Engine 4, Tekken 7 features stunning story-driven cinematic battles and intense duels that can be enjoyed with friends and rivals alike through innovative fight mechanics."},{"t":"Terminator Genisys: Future War","p":["iOS","Android"],"d":"Plarium","u":"Plarium","g":"Strategy, massively multiplayer online","r":"May 18, 2017","l":"https://en.wikipedia.org/wiki/Terminator_Genisys:_Future_War","s":"It is time for a war that will define humanity forever. Will you fight to survive Skynet’s unceasing assault, or will you help bring about the end of the self-destructive creatures that thought themselves the masters of the world?\n\nAs members of the human Resistance, the stakes couldn’t be higher. Skynet’s primary core is down, but secondary protocols have been activated all across the globe, and they are as determined as ever to destroy humanity. So, protect what’s yours at all costs!\n\nIf you join the forces of Skynet, though, you have one goal. Your systems are damaged, your forces depleted, but your mission is clear: eliminate the human race. Rebuild what was destroyed, bring your core up to full capacity, and bring war to the world once again.\n\nWhichever side you choose, you’ll need to sustain your war machine. Build up infrastructure to help gather resources, mobilize units, and research new technologies.\n\nTechnology and research can turn basic infantry into powerful combatants. It will take the most cutting-edge tech to overcome your foes, so explore an advanced and customizable tech tree to make sure your edge is fit to cut with.\n\nYour forces will also need guidance. Your Leaders have sophisticated skill trees you’ll need to master if you’re going to get the most out of every soldier and combat unit.\n\nThe human resistance has fractured while Skynet’s forces override each other, constantly trying to gain an advantage. So, your natural allies could also be your greatest enemies. Take your forces, gather those who can truly aid you, and crush your foes on the field of battle."},{"t":"That's You!","p":["PlayStation 4"],"g":"Party","r":"July 4","l":"https://en.wikipedia.org/wiki/That%27s_You!"},{"t":"Thaumistry: In Charm's Way","p":["Windows","macOS","Linux","Android","iOS"],"g":"Interactive fiction","r":"October 7, 2017","l":"https://en.wikipedia.org/wiki/Thaumistry:_In_Charm's_Way","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1j0h.jpg","s":"Thaumistry: In Charm's Way is an all-new comedy text adventure from award-winning Infocom and Legend Entertainment author Bob Bates."},{"t":"The Alliance Alive","p":["Nintendo 3DS"],"g":"RPG","r":"March 30","l":"https://en.wikipedia.org/wiki/The_Alliance_Alive"},{"t":"The Binding of Isaac: Afterbirth+","p":["Nintendo Switch"],"g":"Roguelike","r":"March 3","l":"https://www.igdb.com/games/the-binding-of-isaac-afterbirth-plus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1to9.jpg","s":"The Binding of Isaac: Afterbirth+ is a dungeon-crawling shoot-'em-up that's literally a different game each and every time you play it! The randomly generated maps are built with over 11,000 unique room configurations, each populated with a nearly endless variety of enemies, items, challenges and secrets!"},{"t":"The Caligula Effect","p":["PlayStation Vita"],"g":"RPG","r":"May 2","l":"https://en.wikipedia.org/wiki/The_Caligula_Effect"},{"t":"The Case Book of Arne","p":[],"l":"https://en.wikipedia.org/wiki/The_Case_Book_of_Arne"},{"t":"The Chase: Ultimate Edition","p":[],"l":"https://en.wikipedia.org/wiki/The_Chase:_Ultimate_Edition"},{"t":"The Culling","p":["Linux","Windows","Xbox One"],"d":"Xaviant","u":"Xaviant","g":"Action, battle royale","r":"October 5, 2017","l":"https://en.wikipedia.org/wiki/The_Culling_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rky.jpg","s":"In a remote island paradise, 16 contestants have 20 minutes to explore, scavenge items, craft weapons, build traps, and hunt and kill each other. Only one will be crowned the winner. Do you have the guts to survive? Prepare for the most focused, brutal, and adrenaline-filled battle royale game you've ever seen!"},{"t":"The Darkside Detective","p":["Linux","macOS","Windows"],"d":"Spooky Doorway","u":"Akupara Games","g":"Point-and-click adventure","r":"July 27, 2017","l":"https://en.wikipedia.org/wiki/The_Darkside_Detective","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23bz.jpg","s":"Join The Darkside Detective, Francis McQueen, as he investigates the bizarre, the supernatural and those missing cat cases that keep getting dropped on his desk."},{"t":"The Disney Afternoon Collection","p":["Windows","PlayStation 4","Xbox One"],"g":"Action, Platformer","r":"April 18","l":"https://en.wikipedia.org/wiki/The_Disney_Afternoon_Collection"},{"t":"The Elder Scrolls V: Skyrim","p":["Nintendo Switch","PlayStation VR"],"g":"Action RPG","r":"November 17"},{"t":"The Elder Scrolls: Legends","p":["Windows","iOS","macOS","Android"],"d":"Dire Wolf Digital, Sparkypants Studios","u":"Bethesda Softworks","g":"Collectible card","r":"March 9, 2017","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls:_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3woi.jpg","s":"The Elder Scrolls: Legends is a strategy card game that explores the series' characters, creatures, deities, and lore. Whether you have 10 minutes or five hours, Legends provides a variety of gameplay modes and challenges that are easy-to-learn but difficult to master. Built with all levels of players in mind, Legends offers accessible gameplay for beginners who want to get started quickly, and the game's depth keeps expert players engaged. With a wide variety of deck types and strategies, no two games are ever the same."},{"t":"The End Is Nigh","p":["Windows","Nintendo Switch"],"g":"Platformer, Adventure","r":"July 12","l":"https://en.wikipedia.org/wiki/The_End_Is_Nigh_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n38.jpg","s":"The End Is Nigh is a sprawling adventure platformer where the player takes control of Ash, one of few 'things' that have 'survived' the \"end of the world.\"\nFollow Ash as he flops his way through a future of pain and suffering. Feel his stress levels rise as you throw him into an endless swarm of decaying, mutant creatures and help aid his final epic quest... to simply make a friend."},{"t":"The Escapists 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Strategy, RPG","r":"August 22","l":"https://en.wikipedia.org/wiki/The_Escapists_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uvu.jpg","s":"The Escapists 2 is the forthcoming sequel to the sandbox prison-escape game which will include, in a first for the series, drop in/drop out play for up to four players in both local and online play."},{"t":"The Evil Within 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Survival horror","r":"October 13","l":"https://en.wikipedia.org/wiki/The_Evil_Within_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5wgu.jpg","s":"The Evil Within 2 is the latest evolution of survival horror. Detective Sebastian Castellanos has lost it all. But when given a chance to save his daughter, he must descend once more into the nightmarish world of STEM.\n\nHorrifying threats emerge from every corner as the world twists and warps around him. Will Sebastian face adversity head on with weapons and traps, or sneak through the shadows to survive."},{"t":"The Expression Amrilato","p":["Windows","Android"],"g":"Simulator, Quiz/Trivia, Adventure, Indie, Visual Novel","l":"https://en.wikipedia.org/wiki/The_Expression_Amrilato","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocwbi.jpg","s":"In \"The Expression Amrilato\", the main character is lost in an alternate world where Juliamo (which in the real world is Esperanto, an existing constructed language.) is the official spoken language.\nTherefore, while enjoying a story between cute girls, you can also learn the Esperanto language!\nThe text in this game has been officially supervised by the National Esperanto Association in Japan."},{"t":"The First Tree","p":["macOS","Windows","Linux"],"d":"David Wehle","u":"David Wehle","g":"Adventure","r":"September 14, 2017","l":"https://en.wikipedia.org/wiki/The_First_Tree","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1jy1.jpg","s":"A beautiful, 3rd-person exploration game centered around two parallel stories: a fox trying to find her missing family, and a young couple dealing with a tragedy in their own. Uncover artifacts from the young couple's life as they too become intertwined in the fox's journey towards The First Tree."},{"t":"The Franz Kafka Videogame","p":["Windows","iOS"],"d":"Denis Galanin","u":"Daedalic Entertainment","g":"Adventure, puzzle","r":"April 6, 2017","l":"https://en.wikipedia.org/wiki/The_Franz_Kafka_Videogame","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23ce.jpg","s":"The Franz Kafka Videogame is an original puzzle/adventure game inspired by the writings of Franz Kafka. The protagonist named K., gets a sudden offer of employment and this event changes his life forcing him to make a distant voyage. To his surprise, the world beyond his homeland appears to be not as normal as he would think. Together with K., you will experience an atmosphere of absurdity, surrealism, and total uncertainty."},{"t":"The Game Paradise: CruisinMix","p":["Windows","PlayStation 4"],"g":"Scrolling shooter","r":"November 30","l":"https://en.wikipedia.org/wiki/Game_Tengoku"},{"t":"The Golf Club 2","p":["Windows","PlayStation 4","Xbox One"],"g":"Sports","r":"June 27","l":"https://en.wikipedia.org/wiki/The_Golf_Club"},{"t":"The Great Ace Attorney 2: Resolve","p":["Nintendo 3DS"],"d":"Capcom","u":"Capcom","g":"Adventure, visual novel","r":"August 3, 2017","l":"https://en.wikipedia.org/wiki/The_Great_Ace_Attorney_2:_Resolve","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob9su.jpg","s":"The Great Ace Attorney 2: Resolve is the eleventh installment of the Ace Attorney series of text adventure video games.\nNew gameplay mechanics introduced to the series include Dance of Deduction, in which Ryunosuke must deduce mistakes and oversights in Herlock's overboard logic and uncover new facts, and Summation Examination, in which players must point out discrepancies among jurors' arguments to make their defendant's case and ultimately secure a \"Not Guilty\" verdict."},{"t":"The House of Da Vinci","p":["Android","iOS","Windows","macOS"],"d":"Blue Brain Games","u":"Blue Brain Games","g":"Puzzle, adventure","r":"June 22, 2017","l":"https://en.wikipedia.org/wiki/The_House_of_Da_Vinci","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23co.jpg","s":"Enter The House of Da Vinci, a new must-try 3D puzzle adventure game. Solve mechanical puzzles, discover hidden objects, escape from rooms and dive into the authentic atmosphere of the Renaissance. Use all your wits to find out what's behind your master's disappearance."},{"t":"The Idolmaster SideM","p":[],"l":"https://en.wikipedia.org/wiki/The_Idolmaster_SideM"},{"t":"The Infectious Madness of Doctor Dekker","p":["Windows","macOS"],"d":"D'Avekki Studios","u":"D'Avekki Studios","g":"Adventure, interactive film","r":"May 19, 2017","l":"https://en.wikipedia.org/wiki/The_Infectious_Madness_of_Doctor_Dekker","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23ct.jpg","s":"\"The Infectious Madness of Doctor Dekker is a horror themed murder mystery FMV game where you play as a therapist questioning patients. The game features the simplest of interfaces, over 1600 HD video responses, six main characters, and a randomly chosen murderer at the start of the game (which determines your story path).\""},{"t":"The Jackbox Party Pack","p":["Nintendo Switch"],"d":"Jackbox Games","u":"Jackbox Games","g":"Party","r":"August 17","l":"https://en.wikipedia.org/wiki/The_Jackbox_Party_Pack_(video_game)"},{"t":"The Jackbox Party Pack 2","p":["Nintendo Switch"],"d":"Jackbox Games","u":"Jackbox Games","g":"Party","r":"August 17","l":"https://en.wikipedia.org/wiki/The_Jackbox_Party_Pack_2"},{"t":"The Jackbox Party Pack 3","p":["Nintendo Switch"],"d":"Jackbox Games","u":"Jackbox Games","g":"Party","r":"April 13","l":"https://en.wikipedia.org/wiki/The_Jackbox_Party_Pack_3"},{"t":"The Jackbox Party Pack 4","p":["Windows","macOS","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Jackbox Games","u":"Jackbox Games","g":"Party","r":"October 17","l":"https://en.wikipedia.org/wiki/The_Jackbox_Party_Pack_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4zeo.jpg","s":"The biggest and fourthiest addition to this storied party game franchise features the blanking fun sequel Fibbage 3 and its new game mode, Fibbage: Enough About You; the web-based frame game Survive the Internet; the spooky date-a-thon Monster Seeking Monster; the deranged debate match Bracketeering; and the one-up art game Civic Doodle. Use your phones or tablets as controllers and play with up to 16 players, plus an audience of up to 10,000!"},{"t":"The Legend of Heroes: Trails in the Sky the 3rd","p":["Windows"],"g":"RPG","r":"May 3"},{"t":"The Legend of Heroes: Trails of Cold Steel III","p":["PlayStation 4"],"g":"RPG","r":"September 28"},{"t":"The Legend of Zelda: Breath of the Wild","p":["Nintendo Switch","Wii U"],"d":"Nintendo EPD","u":"Nintendo","g":"Action-adventure","r":"March 3, 2017","l":"https://www.igdb.com/games/the-legend-of-zelda-breath-of-the-wild","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3p2d.jpg","s":"The Legend of Zelda: Breath of the Wild is the first 3D open-world game in the Zelda series. Link can travel anywhere and be equipped with weapons and armor found throughout the world to grant him various bonuses. Unlike many games in the series, Breath of the Wild does not impose a specific order in which quests or dungeons must be completed. While the game still has environmental obstacles such as weather effects, inhospitable lands, or powerful enemies, many of them can be overcome using the right method. A lot of critics ranked Breath of the Wild as one of the best video games of all time."},{"t":"The Lego Ninjago Movie Video Game","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Action-adventure","r":"September 22","l":"https://en.wikipedia.org/wiki/The_Lego_Ninjago_Movie_Video_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co253j.jpg","s":"Find your inner ninja with the all-new LEGO Ninjago Movie Video Game! Play as your favorite ninjas, Lloyd, Jay, Kai, Cole, Zane, Nya and Master Wu to defend Ninjago City from the evil Lord Garmadon and his Shark Army. Master the art of Ninja-gility by wall-running, high-jumping and battling the foes of Ninjago to rank up and upgrade the ninja’s combat skills. Only in the LEGO Ninjago Movie Video Game will you experience the film across 8 action packed locations each with its own unique Challenge Dojo. And with the Battle Maps, play against friends and family in competitions for up to four players!"},{"t":"The Long Dark","p":["Linux","macOS","Windows","PlayStation 4","Xbox One"],"d":"Hinterland Studio","u":"Hinterland Studio","g":"Survival","r":"August 1, 2017","l":"https://en.wikipedia.org/wiki/The_Long_Dark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vga.jpg","s":"Welcome to The Long Dark, the innovative exploration-survival experience Wired magazine calls \"the pinnacle of an entire genre\". The game is a thoughtful, exploration-survival experience that challenges solo players to think for themselves as they explore an expansive frozen wilderness in the aftermath of a geomagnetic disaster. There are no zombies but only you, the cold, and all the threats Mother Nature can muster."},{"t":"The Long Journey Home","p":["Windows"],"d":"Daedalic Entertainment","u":"Daedalic Entertainment","g":"Adventure","r":"May 30, 2017","l":"https://en.wikipedia.org/wiki/The_Long_Journey_Home_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsoh.jpg","s":"The Long Journey Home combines the endless freedom of space with a new open questing system that always leaves you in command. Deliver the stranded Glukkt to his homeworld as he asks, or to your new slaver friends? Attempt to make allies with everyone, or pin your hopes on the tougher races, and hope they never turn on you? Jump by jump, make hard decisions and live with the consequences, in a universe that is never the same twice."},{"t":"The Lord of the Rings Online: Mordor","p":["Windows"],"d":"Standing Stone Games","u":"Daybreak Game Company","g":"Massively multiplayer online role-playing","r":"July 31, 2017","l":"https://en.wikipedia.org/wiki/The_Lord_of_the_Rings_Online:_Mordor"},{"t":"The Lost Child","p":["PlayStation 4","PlayStation Vita"],"r":"August 24"},{"t":"The Mage's Tale","p":["Windows","Oculus Rift"],"d":"inXile Entertainment","u":"inXile Entertainment","g":"Role-playing","r":"June 20, 2017","l":"https://en.wikipedia.org/wiki/The_Mage's_Tale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xwu.jpg","s":"Welcome, apprentice of the mystic arts! The corrupt wizard Gaufroi has kidnapped your master, Mage Alguin, and you are the only one who has any hope of saving him. You may be an apprentice now, but to save your master, you will need to explore ten deadly dungeons, decipher mind-bending puzzles, avoid terrifying traps, and vanquish hordes of vicious monsters.\nUntil you are able to wield every elemental power in the palm of your hand, evil remains ascendant! It is your turn now to sling gouts of flame, javelins of ice, arcs of lightning, and swirling tempests! Don your wizard's robe and begin your Mage's Tale!"},{"t":"The Mooseman","p":["Windows","macOS","Linux"],"d":"Morteshka","u":"Sometimes You","g":"Adventure game","r":"February 17, 2017","l":"https://en.wikipedia.org/wiki/The_Mooseman","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23dn.jpg","s":"Long-long time ago the world was created out of an egg-shell by a god named Yen. In the murky depths of the endless ocean the Lower World was born. The Middle World was made for the men to dwell, and the Upper World was were the ancient gods would reside. Multitude of spirits dwells among the layers of creation, guarding their secrets in the dark. Embark on a journey through all the worlds of ancient myth, find artefacts of Chud' tribes and solve all the mysteries of finno-ugric tales. You are the Mooseman and you have the ability to see all that is hidden to the mortal eye. You are about to visit three layers of this universe - the first one is the Lower World where ancient spirits dwell."},{"t":"The Mummy Demastered","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"g":"Metroidvania","r":"October 24","l":"https://en.wikipedia.org/wiki/The_Mummy_Demastered"},{"t":"The Norwood Suite","p":["macOS","Windows"],"d":"Cosmo D","u":"Alliance","g":"Adventure game","r":"October 2, 2017","l":"https://en.wikipedia.org/wiki/The_Norwood_Suite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1txc.jpg","s":"The sequel to Off-Peak, The Norwood Suite is a surreal first-person adventure game by Cosmo D. Journey to the secluded Hotel Norwood, where odd characters, forgotten secrets, and head-nodding music await."},{"t":"The Pillars of The Earth Book 1: From The Ashes","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"r":"August 15","l":"https://en.wikipedia.org/wiki/The_Pillars_of_the_Earth#Video_Game"},{"t":"The Sexy Brutale","p":["Windows","PlayStation 4","Xbox One"],"g":"Puzzle, Adventure, Indie","r":"April 11","l":"https://en.wikipedia.org/wiki/Tequila_Works","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23dx.jpg","s":"Set during a single, endlessly-looping day within \"The Sexy Brutale\" - a stately English mansion converted into a bizarre casino and named by the enigmatic Marquis - players take on the role of elderly priest Lafcadio Boone. To progress, Boone must hide, watch and learn the colorful stories of the other guests at the ball in order to save them from grisly deaths at the hands of the mansion’s staff."},{"t":"The Shrouded Isle","p":["macOS","Windows"],"d":"Kitfox Games","u":"Kitfox Games","g":"Management simulation","r":"August 4, 2017","l":"https://en.wikipedia.org/wiki/The_Shrouded_Isle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rjj.jpg","s":"The Shrouded Isle is a cult village management simulator. Your people look to you for leadership. Five families vie for power as the storms roll in and things beneath the waves threaten to wake. Feed and house your village while ensuring the ancient, dark traditions are followed and the appropriate sacrifices are made."},{"t":"The Signal from Tölva","p":["Windows"],"r":"April 10","l":"https://en.wikipedia.org/wiki/Big_Robot"},{"t":"The Silver Case","p":["PlayStation 4"],"g":"Adventure, Visual novel","r":"April 18","l":"https://en.wikipedia.org/wiki/The_Silver_Case"},{"t":"The Sims 4","p":["PlayStation 4","Xbox One"],"g":"Simulation","r":"November 17","l":"https://en.wikipedia.org/wiki/The_Sims_4"},{"t":"The Sims 4: Cats & Dogs","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Cats_&_Dogs"},{"t":"The Sims 4: Parenthood","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Parenthood"},{"t":"The Sims 4: Vampires","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Vampires"},{"t":"The Solus Project","p":["PlayStation 4","PlayStation VR"],"g":"Survival horror","r":"September 18","l":"https://en.wikipedia.org/wiki/The_Solus_Project"},{"t":"The Surge","p":["Windows","PlayStation 4","Xbox One"],"g":"Action RPG","r":"May 16","l":"https://en.wikipedia.org/wiki/The_Surge_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1odu.jpg","s":"The Surge is a sci-fi spin on Dark Souls, from the Lords of the Fallen team.\nA catastrophic event has knocked you out during the first day on the job... you wake up equipped with a heavy-grade exoskeleton, in a destroyed section of the complex. Robots gone haywire, insane augmented co-workers and rogue AI - everything wants you dead.\nDefy deadly enemies and huge bosses in tight, visceral melee combat. Target and slice specific limbs off your foes, with a next-gen loot system where you loot what you dismember. Equip, upgrade and craft new weapons and armors sliced from enemies, and make yourself stronger through a fresh take on leveling-up."},{"t":"The Tearoom","p":["Linux","macOS","Windows"],"d":"Robert Yang","g":"Simulator, Indie","r":"June 28, 2017","l":"https://en.wikipedia.org/wiki/The_Tearoom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co482v.jpg","s":"A historical public bathroom simulator about anxiety, police surveillance, and sucking off another dude's gun."},{"t":"The Walking Dead: Season Three — Episode 3","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"March 28"},{"t":"The Walking Dead: Season Three — Episode 4","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"April 25"},{"t":"The Walking Dead: Season Three — Episode 5","p":["Windows","macOS","PlayStation 4","Xbox One","iOS","Android"],"g":"Graphic adventure","r":"May 30"},{"t":"The Wardrobe","p":["Windows","PlayStation 4","Nintendo Switch"],"d":"C.I.N.I.C. Games","u":"Gamera Interactive","g":"Graphic adventure","r":"February 15, 2017","l":"https://en.wikipedia.org/wiki/The_Wardrobe_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3101.jpg","s":"The Wardrobe is a visually-rich 2D point and click adventure game inspired by the great '90s classics. The game has a strong sense of humour, but isn't shy about dealing with mature and non-politically correct themes."},{"t":"Thea: The Awakening","p":["PlayStation 4","Xbox One"],"r":"May 31"},{"t":"TheHunter: Call of the Wild","p":["Windows","PlayStation 4","Xbox One"],"d":"Expansive Worlds","u":"Avalanche Studios","g":"Shooter, Simulator, Sport, Strategy, Adventure","r":"February 16, 2017","l":"https://www.igdb.com/games/thehunter-call-of-the-wild","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u14.jpg","s":"Never before have you experienced a hunting game like theHunter: Call of the Wild. Plunge into an atmospheric open world, teeming with life: from the majestic true-to-life animals to the rustling of leaves above you as you stalk your prey. You can decide to hunt on your own or join up and hunt together with friends. Just remember, you are not just a visitor in this world, you are a living and breathing part of it. As you finally spot the majestic crown of your first red deer through the brush, the feeling is indescribable."},{"t":"Thimbleweed Park","p":["Windows","macOS","Linux","Xbox One"],"g":"PCA","r":"March 30","l":"https://en.wikipedia.org/wiki/Thimbleweed_Park","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wq3.jpg","s":"Thimbleweed Park is the curious story of two washed up detectives investigating a dead body found in the river just outside of town. It's a game where you switch between five playable characters while uncovering the dark, satirical and bizarre world of Thimbleweed Park."},{"t":"This Is the Police","p":["Nintendo Switch"],"g":"Adventure, Strategy","r":"October 24","l":"https://en.wikipedia.org/wiki/This_Is_the_Police"},{"t":"Thumper","p":["Nintendo Switch"],"g":"Rhythm","r":"May 18","l":"https://en.wikipedia.org/wiki/Thumper_(video_game)"},{"t":"Thunderbird Strike","p":["Windows","Android","iOS"],"d":"Elizabeth LaPensée","g":"Adventure, Indie","l":"https://en.wikipedia.org/wiki/Thunderbird_Strike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4k5p.jpg","s":"In the 2D sidescroller Thunderbird Strike, fly from the Tar Sands to the Great Lakes as a thunderbird protecting Turtle Island with searing lightning against the snake that threatens to swallow the lands and waters whole."},{"t":"Ticket to Earth","p":["iOS","macOS","Windows","Android"],"d":"Robot Circus","u":"Robot Circus","g":"Tactical role-playing, puzzle","r":"March 15, 2017","l":"https://en.wikipedia.org/wiki/Ticket_to_Earth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24n3.jpg","s":"Ticket to Earth is a unique fusion of turn-based tactics, tile-matching puzzle, and story-driven RPG. This epic sci-fi saga of betrayal and insurrection unites four unlikely heroes, defending a desperate group of colonists abandoned by their wealthy masters."},{"t":"Time Recoil","p":["PlayStation 4"],"r":"September 12"},{"t":"Tiny Barbarian DX","p":["Nintendo Switch"],"r":"October 10"},{"t":"Tiny Metal","p":["Windows","Nintendo Switch","PlayStation 4"],"g":"TBT","r":"December 21","l":"https://en.wikipedia.org/wiki/Tiny_Metal"},{"t":"Titanfall: Assault","p":["iOS","Android"],"d":"Particle City, Respawn Entertainment","u":"Nexon","g":"Real-time strategy","r":"August 10, 2017","l":"https://en.wikipedia.org/wiki/Titanfall:_Assault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rp6.jpg","s":"\"Join the fight for The Frontier in this fast and fluid real-time strategy game. Combine towering Titans and agile Pilots to build an unstoppable force.\n\nPut your skills to the test as you assemble the ultimate deck of Pilots and Titans paired into heroic duos. Collect and upgrade dozens of cards including tactical Burn Cards providing powerful battlefield support. Strategize your way to victory over enemy forces in epic PvP battles and compete for glory and rewards on the leaderboards.\n\nCombine and conquer. Unite and destroy. And lead your forces to victory in The Frontier War.\""},{"t":"To the Moon","p":["iOS","Android"],"g":"Adventure","r":"May 12","l":"https://en.wikipedia.org/wiki/To_the_Moon_(video_game)"},{"t":"Tokyo 42","p":["Windows","Xbox One"],"g":"Action","r":"May 31","l":"https://en.wikipedia.org/wiki/Tokyo_42"},{"t":"Tokyo Dark","p":["Windows"],"d":"Cherrymochi","u":"Square Enix Collective, Unties","g":"Point-and-click adventure","r":"September 7, 2017","l":"https://en.wikipedia.org/wiki/Tokyo_Dark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s6p.jpg","s":"Tokyo Dark is an anime-style horror adventure game combining point and click and visual novel genres. The story follows Detective Itou across Tokyo, searching for the truth behind her partner's strange disappearance. Featuring puzzles, stat management, and difficult decisions, Tokyo Dark puts the narrative in the hands of the player. Players' decisions change their character, opening or locking options and leading to multiple endings."},{"t":"Tokyo Tattoo Girls","p":["Windows","PlayStation Vita"],"g":"Strategy","r":"November 14","l":"https://en.wikipedia.org/wiki/Tokyo_Tattoo_Girls"},{"t":"Tokyo Xanadu","p":["PlayStation Vita"],"g":"Action RPG","r":"June 30","l":"https://en.wikipedia.org/wiki/Tokyo_Xanadu"},{"t":"Tokyo Xanadu eX+","p":["Windows","PlayStation 4"],"g":"Action RPG","r":"December 8","l":"https://en.wikipedia.org/wiki/Tokyo_Xanadu_eX%2B"},{"t":"Tom Clancy's Ghost Recon Wildlands","p":["Windows","PlayStation 4","Xbox One"],"g":"Tactical shooter","r":"March 7","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Ghost_Recon_Wildlands","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ku7.jpg","s":"Create a team with up to 3 friends in Tom Clancy's Ghost Recon Wildlands and enjoy the ultimate military shooter experience set in a massive, dangerous, and responsive open world."},{"t":"Toontown Rewritten","p":["Windows","macOS","Linux"],"g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","l":"https://en.wikipedia.org/wiki/Toontown_Rewritten","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9sbj.jpg","s":"Toontown Rewritten is a free-to-play revival of Disney's Toontown Online. Toontown is a massively multiplayer online game built for kids, teens, and adults of all ages. Create your own Toon and join the never-ending battle against the \"Cogs\", who want to turn Toontown into their latest business venture."},{"t":"Tooth and Tail","p":["Windows","PlayStation 4"],"g":"RTS","r":"September 12","l":"https://en.wikipedia.org/wiki/Tooth_and_Tail"},{"t":"Torment: Tides of Numenera","p":["Windows","PlayStation 4","Xbox One"],"g":"RPG","r":"February 28","l":"https://www.igdb.com/games/torment-tides-of-numenera","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ni.jpg","s":"Torment: Tides of Numenera is a game set in the world of Monte Cook's new tabletop RPG setting, Numenera. Torment continues the thematic legacy of Planescape: Torment, the critically acclaimed role-playing game from 1999 that's considered by many to be a hallmark for storytelling in computer RPGs. With Torment, we're creating a rich role-playing experience that explores similar deep, personal themes."},{"t":"Total War: Warhammer II","p":["Windows"],"g":"TBS, RTT","r":"September 28","l":"https://www.igdb.com/games/total-war-warhammer-ii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9rsu.jpg","s":"Total War: Warhammer II is a strategy game of titanic proportions. Choose from four unique, varied factions and wage war your way; mounting a campaign of conquest to save or destroy a vast and vivid fantasy world. This is a game of two halves: one a turn-based open-world campaign, and the other intense, tactical real-time battles across the fantastical landscapes of the New World."},{"t":"Touhou Kobuto V: Burst Battle","p":["Nintendo Switch","PlayStation 4","PlayStation Vita"],"g":"Bullet hell , Shoot 'em up, Fighting","r":"October 10","l":"https://en.wikipedia.org/wiki/Touhou_Project#Reception_and_fanworks"},{"t":"Toukiden 2","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"March 21","l":"https://en.wikipedia.org/wiki/Toukiden_2"},{"t":"Travel Frog","p":["iOS","Android"],"d":"Hit-Point","u":"Hit-Point","g":"Virtual pet, incremental game","r":"November 24, 2017","l":"https://en.wikipedia.org/wiki/Travel_Frog","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7h8k.jpg","s":"A mobile game about a frog who goes on various trips to distant places, sending postcards during their journey and bringing back souvenirs."},{"t":"Tricky Towers","p":["Xbox One"],"g":"Puzzle","r":"September 15","l":"https://en.wikipedia.org/wiki/Tricky_Towers"},{"t":"Troll and I","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Action-adventure","r":"March 21","l":"https://en.wikipedia.org/wiki/Troll_and_I"},{"t":"TumbleSeed","p":["macOS","Nintendo Switch","PlayStation 4","Windows"],"u":"aeiowu","g":"Action","r":"May 2, 2017","l":"https://en.wikipedia.org/wiki/TumbleSeed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24m1.jpg","s":"TumbleSeed is a deceptively deep roguelike about balancing a seed up a dangerous and ever-changing mountain."},{"t":"Twin Star Exorcists","p":["PlayStation Vita"],"r":"January 26","l":"https://en.wikipedia.org/wiki/Twin_Star_Exorcists"},{"t":"TypeShift","p":["Browser","iOS","Android"],"d":"Zach Gage","u":"Zach Gage","g":"Word, puzzle","r":"March 18, 2017","l":"https://en.wikipedia.org/wiki/TypeShift","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24xy.jpg","s":"From the creator of SpellTower, comes a new and completely original word game!\nAnagrams meets Word Search, with a sprinkle of Crosswords."},{"t":"Ultimate Epic Battle Simulator","p":["Windows"],"d":"Brilliant Game Studios","u":"Brilliant Game Studios","g":"Strategy","r":"June 2, 2017","l":"https://en.wikipedia.org/wiki/Ultimate_Epic_Battle_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rrx.jpg","s":"Here is a sandbox like no other. Create massive battles with absolutely no limits. Want to see 10,000 chickens fight an army of Romans?? Sure, why not. Want to see a company of WW2 U.S soldiers fight 11,000 Medieval soldiers?? There are simply no limits to the carnage you can achieve in UEBS."},{"t":"Ultimate Marvel vs. Capcom 3","p":["Windows","Xbox One"],"g":"Fighting","r":"March 7","l":"https://en.wikipedia.org/wiki/Ultimate_Marvel_vs._Capcom_3"},{"t":"Ultra Street Fighter II","p":["Nintendo Switch"],"d":"Capcom","u":"Capcom","g":"Fighting","r":"May 26, 2017","l":"https://en.wikipedia.org/wiki/Ultra_Street_Fighter_II"},{"t":"Ultra Street Fighter II: The Final Challengers","p":["Nintendo Switch"],"g":"Fighting","r":"May 26"},{"t":"Unbox: Newbies Adventure","p":["Nintendo Switch"],"r":"October 11"},{"t":"Uncharted: The Lost Legacy","p":["PlayStation 4"],"g":"Action-adventure, TPS, Platformer","r":"August 22","l":"https://www.igdb.com/games/uncharted-the-lost-legacy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tp9.jpg","s":"Uncharted: The Lost Legacy is a single-player action-adventure game played from a third-person perspective, and a standalone expansion in the Uncharted series. Players guide treasure hunter Chloe Frazer through towns, ruins, and temples across the Western Ghats of India, using firearms, melee combat, and stealth against hostile forces. Gameplay combines gunfights, climbing and platforming, environmental puzzles, and vehicle sections across larger, more open environments than earlier entries. It also grants access to the multiplayer component of Uncharted 4."},{"t":"Undertale","p":["PlayStation 4","PlayStation Vita"],"d":"8-4","u":"8-4","g":"RPG","r":"August 15, 2017","l":"https://en.wikipedia.org/wiki/Undertale"},{"t":"Unexplored","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Ludomotion","u":"Ludomotion","g":"Roguelike, action role-playing","r":"February 22, 2017","l":"https://en.wikipedia.org/wiki/Unexplored","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/chmhd8adcv38pxk1lol4.jpg","s":"Unexplored is an accessible yet challenging roguelite action rpg, featuring a fantastic level generator, and a surprising amount of content and depth. Explore dangerous dungeons, solve mysterious puzzles and engage hundreds of foes, big and small, in intense melee combat."},{"t":"Unforgiving: A Northern Hymn","p":["Windows"],"d":"Angry Demon Studio","u":"Angry Demon Studio","g":"Survival horror","r":"November 27, 2017","l":"https://en.wikipedia.org/wiki/Unforgiving:_A_Northern_Hymn"},{"t":"Unholy Night: The Darkness Hunter","p":["Super Nintendo Entertainment System"],"d":"Foxbat Corporation, Nu-Gaia","u":"BlazePro, Retroism, JoshProd","g":"Fighting","r":"April 8, 2017","l":"https://en.wikipedia.org/wiki/Unholy_Night:_The_Darkness_Hunter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uue.jpg","s":"The city of Darkness, Hunt or to be Hunted!\n\nThe story is between Human beings (here call them:“Hunter”) in the world-wide battle with Vampire and Wolf-man (here call them “The Darkness Clan”).\n\n-Dark world image\nWith a brand new dark and cool world view for all fans of traditional 2D fighting game. In addition, this product will bring new audiences in with a sharp image that never been found in console fighting games.\n\n-Different kind of attack move\nEach character has totally eight different kind of Special Attacks (Special Move) and Super Special Attacks (Super Special Move), all are usefully in the Battle.\n\n-Original fighting game\nYou can use the manipulate characters to enjoy the variety of special attacks and combos. In addition, we aim in the original fighting game while using fully power of hardware, such as demonstration and game graphic etc…"},{"t":"Universal Paperclips","p":["Browser","iOS","Android"],"g":"Incremental, Clicker","r":"October 9, 2017","l":"https://en.wikipedia.org/wiki/Universal_Paperclips","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co263i.jpg","s":"Universal Paperclips is a browser game were the player takes on the role of an AI tasked with creating paperclips."},{"t":"Unturned","p":["Windows","macOS","Linux"],"d":"Smartly Dressed Games","u":"505 Games","g":"Survival","r":"July 7, 2017","l":"https://en.wikipedia.org/wiki/Unturned","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaary.jpg","s":"You're a survivor in the zombie infested ruins of society, and must work with your friends and forge alliances to remain among the living."},{"t":"Urban Empire","p":["Windows"],"r":"January 20","l":"https://en.wikipedia.org/wiki/Kalypso_Media"},{"t":"Use Your Words","p":["Windows","macOS","PlayStation 4","Xbox One","Wii U","Nintendo Switch"],"d":"Smiling Buddha Games","u":"Screenwave Media","g":"Party","r":"April 4, 2017","l":"https://en.wikipedia.org/wiki/Use_Your_Words","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zdw0pddl9ccod1nss8my.jpg","s":"Grab a few friends and get ready to laugh. Use Your Words is the party game for funny people and their unfunny friends!\n\nUse Your Words is a game that invites players to respond to a variety of mini-games and prompts with the funniest answers they can think of! Players play using their phones and tablets as controllers, making game-play seamless and quick to pick up. Players who get stumped can use one of the hidden \"House Answers\" to lay a trap for their fellow players once it's time for everyone to vote for their favorite.\n\nWhether you're a total novice or a world-famous comedian, we guarantee hours of non-stop hilarity. So, grab a few friends and get ready to laugh along with Use Your Words!"},{"t":"Utawarerumono: Mask of Deception","p":["PlayStation 4","PlayStation Vita"],"g":"Tactical RPG, Visual novel","r":"May 23","l":"https://en.wikipedia.org/wiki/Utawarerumono"},{"t":"Utawarerumono: Mask of Truth","p":["PlayStation 4","PlayStation Vita"],"g":"RTS, Visual novel, Eroge","r":"September 5","l":"https://en.wikipedia.org/wiki/Utawarerumono","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w6v.jpg","s":"The epic story of Utawarerumono comes to an end in Mask of Truth, as the fate of the world will be determined by warring nations. The game features exciting SRPG battles, a colorful cast of new/familiar faces that will determine the fate of their world, a rousing original soundtrack, and the dramatic conclusion to the journey of Haku. After the events of Mask of Deception, Haku is destined to rally the nation of Ennakamuy to fight against the evil forces that now control the Yamato throne."},{"t":"Valkyria Revolution","p":["PlayStation 4","PlayStation Vita","Xbox One"],"g":"Action RPG","r":"January 19","l":"https://en.wikipedia.org/wiki/Valkyria_Revolution"},{"t":"Valkyrie Drive: Bhikkhuni","p":["Windows"],"r":"May 20"},{"t":"Vampire: The Masquerade – We Eat Blood","p":["Windows","macOS","Linux","Android","iOS"],"g":"Interactive fiction","r":"February 15"},{"t":"Vanquish","p":["Windows"],"g":"Action, TPS","r":"May 25","l":"https://en.wikipedia.org/wiki/Vanquish_(video_game)"},{"t":"Vikings: Wolves of Midgard","p":["Windows","PlayStation 4","Xbox One","Linux","macOS"],"d":"Games Farm","u":"Kalypso Media","g":"Action role-playing","r":"March 24, 2017","l":"https://en.wikipedia.org/wiki/Vikings:_Wolves_of_Midgard","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24l3.jpg","s":"Vikings: Wolves of Midgard takes you to the Shores of Midgard, a world based upon the mythology and history of the Vikings, but with a fantasy twist. Battle the fearsome Jotan, hordes of terrifying undead monstrosities and the beasts of Ragnarok, as you strive to survive the growing cold of Fimbulwinter."},{"t":"Viktor, a Steampunk Adventure","p":["Windows"],"d":"Studio Spektar","u":"Studio Spektar","g":"Point-and-click adventure","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Viktor,_a_Steampunk_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24l2.jpg","s":"\"Viktor, a Steampunk Adventure\" is a comedy adventure game set in a cartoonish steampunk world. The story follows Viktor, a wild boar who tries to cope with the loss of his job by going on a quest to become a new Emperor of Austria-Hungary."},{"t":"Voodoo Vince: Remastered","p":["Windows","Xbox One"],"g":"Platformer","r":"April 18","l":"https://en.wikipedia.org/wiki/Voodoo_Vince"},{"t":"VR Kanojo","p":["Windows"],"d":"Illusion","u":"Illusion","g":"Social simulation","r":"February 28, 2017","l":"https://en.wikipedia.org/wiki/VR_Kanojo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coby82.jpg","s":"Looking for a unique VR experience? Well, look no further! In VR Kanojo, you can hang out with the lovely girl-next-door, Sakura Yuuhi. You'll practically feel her breath on your cheek and the warmth of her fingers on your arm as you laugh and talk the day away. Better yet, VR controllers simulate your hands in-game, letting you interact with her more directly. Just imagine all the possibilities! Oh yeah! And you can customize Sakura's appearance with a variety of different outfits too. Sound like fun? You bet it is! So, thanks for buying VR Kanojo, and we hope you enjoy your time with Sakura Yuuhi!"},{"t":"VRChat","p":["SteamVR","Windows"],"d":"VRChat Inc.","u":"VRChat Inc.","g":"Simulator, Sport, Adventure","r":"February 1, 2017","l":"https://www.igdb.com/games/vrchat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobuhu.jpg","s":"In VRChat there is something around every corner that will delight, thanks to the power of true user generated content. Jump into hundreds of awe-inspiring environments and meet unique avatars every day. Watch a movie on the moon. Ride the Titanic. Step into a new world every time you come online. In VRChat, you are one of us. Enjoy your stay."},{"t":"Vroom in the Night Sky","p":["Nintendo Switch"],"d":"Poisoft","u":"Poisoft","g":"Racing","r":"March 3, 2017","l":"https://en.wikipedia.org/wiki/Vroom_in_the_Night_Sky","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7xi9.jpg","s":"A fantasy motorcycle game by Poisoft that launches on Nintendo Switch."},{"t":"Walden, a game","p":["Windows","macOS"],"g":"Walking sim , Serious , Educational","r":"July 4","l":"https://en.wikipedia.org/wiki/Walden,_a_game"},{"t":"WarFriends","p":["Android","iOS"],"d":"About Fun","u":"EA Chillingo","g":"Third-person shooter","r":"January 17, 2017","l":"https://en.wikipedia.org/wiki/WarFriends"},{"t":"Warhammer 40,000: Dawn of War III","p":["Windows"],"g":"RTS","r":"April 27","l":"https://www.igdb.com/games/warhammer-40000-dawn-of-war-iii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1weo.jpg","s":"In Dawn of War III you will have no choice but to face your foes when a catastrophic weapon is found on the mysterious world of Acheron.\n\nWith war raging and the planet under siege by the armies of greedy Ork warlord Gorgutz, ambitious Eldar seer Macha, and mighty Space Marine commander Gabriel Angelos, supremacy must ultimately be suspended for survival."},{"t":"Warhammer 40,000: Sanctus Reach","p":["Windows"],"d":"Straylight Entertainment","u":"Slitherine Software","g":"Turn-based strategy","r":"January 19, 2017","l":"https://en.wikipedia.org/wiki/Warhammer_40,000:_Sanctus_Reach","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ki.jpg","s":"Warhammer 40,000: Sanctus Reach is a 3D turn-based strategy game like you've never seen before: fast, immediate, deep, impressive to look at and incredibly fun! Fight through a dark era of carnage and endless war and lead the Space Wolves in a struggle to defend the last bastion of mankind."},{"t":"Warriors All-Stars","p":["Windows","PlayStation 4"],"g":"Hack and slash, Action","r":"August 29","l":"https://en.wikipedia.org/wiki/Warriors_All-Stars"},{"t":"We Are Chicago","p":["Windows"],"d":"Culture Shock Games","u":"Culture Shock Games","g":"Simulator, Adventure, Indie","r":"February 9, 2017","l":"https://en.wikipedia.org/wiki/We_Are_Chicago","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zepa1ofvzygbfgto4gbh.jpg","s":"We Are Chicago strives to portray the harsh realities associated with growing up on the south and west side of Chicago.\nIn this first person 3D narrative-driven adventure game you are thrown into the life of Aaron who is only a week away from his high school graduation when suddenly his best friend Robert has stopped showing up to school.\nPlayers will need to uncover what's going on, who Aaron's real friends are, and who they can trust while relying on the community around them to help. They'll explore Aaron's life and relationships to find out the truth and uncover what really matters."},{"t":"We Were Here","p":["SteamVR","macOS","Windows"],"d":"Total Mayhem Games","u":"Total Mayhem Games","g":"Puzzle, Adventure, Indie","r":"February 3, 2017","l":"https://www.igdb.com/games/we-were-here","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cod680.jpg","s":"Lost and separated in an abandoned castle set in a frozen wasteland. Your only possession left is a walkie-talkie, with a familiar voice on the other end. Can the both of you find your way out in time?"},{"t":"West of Loathing","p":["Windows","macOS","Linux"],"g":"RPG","r":"August 10","l":"https://en.wikipedia.org/wiki/West_of_Loathing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1v3g.jpg","s":"Say howdy to West of Loathing - a single-player slapstick, stick-figure comedy adventure role-playing game set in the wild west of the Kingdom of Loathing universe. Traverse snake-infested gulches, punch skeletons wearing cowboy hats, grapple with demon cows, and investigate a wide variety of disgusting spittoons."},{"t":"What Remains of Edith Finch","p":["Xbox One","Windows","PlayStation 4"],"d":"Giant Sparrow","u":"Annapurna Interactive","g":"Adventure","r":"July 19, 2017","l":"https://en.wikipedia.org/wiki/What_Remains_of_Edith_Finch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rbj.jpg","s":"What Remains of Edith Finch is a collection of short stories about a cursed family in Washington State.\n\nEach story offers a chance to experience the life of a different family member with stories ranging from the early 1900s to the present day. The gameplay and tone of the stories are as varied as the family members themselves. The only constants are that each is played from a first-person perspective and that each story ends with that family member's death. It's a game about what it feels like to be humbled and astonished by the vast and unknowable world around us.\n\nYou'll follow Edith Finch as she explores the history of her family and tries to figure out why she's the last Finch left alive."},{"t":"White Day: A Labyrinth Named School","p":["Windows","PlayStation 4"],"g":"Survival horror","r":"August 22"},{"t":"Wikipedia – The Text Adventure","p":["Browser"],"d":"Kevan Davis","u":"Kevan Davis","g":"Interactive fiction","l":"https://en.wikipedia.org/wiki/Wikipedia_%E2%80%93_The_Text_Adventure"},{"t":"Wilson's Heart","p":["Windows"],"d":"Twisted Pixel Games","u":"Oculus","g":"Adventure game","r":"April 25, 2017","l":"https://en.wikipedia.org/wiki/Wilson's_Heart_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28ob.jpg","s":"Wilson's Heart is an immersive first-person psychological thriller set in a 1940's hospital that has undergone a haunting transformation. In this original VR adventure, you become Robert Wilson, a patient who awakens to the shocking discovery that his heart has been replaced with a mysterious device."},{"t":"Windjammers","p":["PlayStation 4","PlayStation Vita"],"g":"Sports","r":"August 29","l":"https://en.wikipedia.org/wiki/Windjammers_(video_game)"},{"t":"Winning Post 8 2017","p":["Windows","PlayStation 4","PlayStation 3","PlayStation Vita"],"r":"March 2","l":"https://en.wikipedia.org/wiki/Winning_Post_8_2017"},{"t":"Wipeout Omega Collection","p":["PlayStation 4"],"g":"Racing","r":"June 6","l":"https://en.wikipedia.org/wiki/Wipeout_Omega_Collection"},{"t":"Wolfenstein II: The New Colossus","p":["Windows","PlayStation 4","Xbox One"],"g":"Action-adventure, FPS","r":"October 27","l":"https://www.igdb.com/games/wolfenstein-ii-the-new-colossus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21c5.jpg","s":"Wolfenstein II: The New Colossus is the eleventh installment of the Wolfenstein series and a sequel to the 2014's Wolfenstein: The New Order. The game follows the main protagonist, William Joseph \"B.J.\" Blazkowicz, in his efforts to ignite a Second American Revolution.\n\nThe game is played from a first-person perspective and most of its levels are navigated on foot. The story is arranged in chapters, which players complete in order to progress. A binary choice in the prologue alters the game's entire storyline; some characters and small plot points are replaced throughout the timelines. The game features a variety of weapons, most of which can be dual wielded. A cover system is also present."},{"t":"Wonder Boy: The Dragon's Trap","p":["Nintendo Switch","PlayStation 4","Xbox One"],"g":"Platformer, Action-adventure","r":"April 18","l":"https://www.igdb.com/games/wonder-boy-the-dragons-trap","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z4q.jpg","s":"A modern version of cult classic Wonder Boy: The Dragon's Trap! A close collaboration between Lizardcube, DotEmu and legendary series creator Ryuichi Nishizawa, based on Westone Bit Entertainment's original masterpiece.\n\nHow many more transformations can one hopeful body survive as it turns into a Lizard, a Mouse, a Piranha, a Lion, and a Hawk... The six different forms of our shape-shifting hero make up the cast of this non-stop action-adventure platformer!"},{"t":"Wonderful Everyday","p":["Windows"],"g":"Visual novel","r":"August 31","l":"https://en.wikipedia.org/wiki/Wonderful_Everyday"},{"t":"Wordscapes","p":["iOS","Android"],"d":"PeopleFun","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Wordscapes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4k6e.jpg","s":"Get the incredibly addicting word game that everyone is talking about! Starts off easy but gets challenging fast. Can you beat the game?\n\nThis modern game combines the best of word searching and crosswords for tremendous brain challenging fun!\n\nNever experience a dull moment once you have this most addicting word puzzle game!\n\n► Escape from boredom and stimulate your mind by visiting the beautiful destinations of Wordscapes!\n► Over 3,700 puzzles!\n► Starts easy and becomes challenging!\n\nWordscapes is the latest top rated word game from the makers of Word Chums, Spell Blitz and MixTwo."},{"t":"World Conqueror 4","p":["Android","iOS","Windows"],"d":"EasyTech","u":"EasyTech","g":"Turn-based strategy","r":"August 24, 2017","l":"https://en.wikipedia.org/wiki/World_Conqueror_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ogb0cu4xzjbrzvn1amg2.jpg","s":"World Conqueror 4 is the newest-released game by EASYTECH in 2017."},{"t":"World of Darkness Preludes: Vampire and Mage","p":["Windows","macOS","Linux","Android","iOS"],"d":"White Wolf Entertainment, Fula Fisken","u":"White Wolf Entertainment, Asmodee","g":"Interactive fiction","r":"February 16, 2017","l":"https://en.wikipedia.org/wiki/World_of_Darkness_Preludes:_Vampire_and_Mage"},{"t":"World of Goo","p":["Nintendo Switch"],"g":"Puzzle","r":"March 3","l":"https://en.wikipedia.org/wiki/World_of_Goo"},{"t":"World to the West","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"r":"May 5"},{"t":"Worlds Adrift","p":["Windows"],"d":"Bossa Studios","u":"Bossa Studios","g":"MMO sandbox","l":"https://en.wikipedia.org/wiki/Worlds_Adrift","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rkj.jpg","s":"A thousand years ago, a cataclysmic event shattered a world into floating islands scattered across an endless skyline. Civilizations tumbled, societies collapsed, and all seemed lost.\n\nFrom the rubble emerged ragtag bands of nomads, who fly cobbled-together skyships from island to island, scavenging for resources to keep moving. These are the players of Worlds Adrift: Explorers of a new world and seekers of ancient knowledge.\n\nWithin the coveted ruins of the past, cryptic and forgotten fragments of the technologies developed by civilizations who built much, and over saw the collapse of it all. Harnessing such forgotten knowledge, players build greater and more powerful skyships that carry them further, past the crushing wind walls, through devastating lightning storms, to entirely undiscovered islands holding the mysteries of an earlier age."},{"t":"WRC 7","p":["Windows","PlayStation 4","Xbox One"],"d":"Kylotonn","u":"Bigben Interactive","g":"Racing","r":"September 15, 2017","l":"https://en.wikipedia.org/wiki/WRC_7","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wga.jpg","s":"Take on the WRC’s 13 rallies and their faithfully reproduced environments. Embody the best drivers in the Championship behind the wheels of their new cars. On your own or online, take on the Epic Stages, face weekly challenges, and live the WRC experience like a pro!"},{"t":"WWE 2K17","p":["Windows"],"g":"Sports","r":"February 7","l":"https://en.wikipedia.org/wiki/WWE_2K17"},{"t":"WWE 2K18","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Sports","r":"October 17","l":"https://en.wikipedia.org/wiki/WWE_2K18","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24jt.jpg","s":"This latest entry in 2k Sports WWE series boasts a next generation graphics engine, the largest roster of any WWE game before it with the rosters updated gimmick sets and show stylings to closely resembles the current TV product, and the first WWE 2k only be released on current generation hardware.\n\nSeth Rollins was revealed to be the cover star, and the game's slogan is \"Be Like No One.\""},{"t":"X-Morph: Defense","p":["Windows","PlayStation 4"],"r":"August 30"},{"t":"XCOM 2: War of the Chosen","p":["PlayStation 4","Windows","Xbox One","Linux","macOS"],"d":"Firaxis Games","u":"2K","g":"Turn-based tactics","r":"August 29, 2017","l":"https://en.wikipedia.org/wiki/XCOM_2:_War_of_the_Chosen"},{"t":"Xenia","p":["Windows"],"r":"September 1"},{"t":"Xenoblade Chronicles 2","p":["Nintendo Switch"],"g":"Action RPG","r":"December 1","l":"https://en.wikipedia.org/wiki/Xenoblade_Chronicles_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8r2.jpg","s":"The next adventure is on the Nintendo Switch console set on the backs of colossal, living Titans. Discover each Titan's diverse regions, culture, wildlife, equipment, and hidden secrets. Find, bond with, and command weaponized life forms known as Blades to earn abilities and enhance them. Uncover the history of Alrest and the mystery of its endless ocean of clouds."},{"t":"XING: The Land Beyond","p":["Windows","PlayStation 4","PlayStation VR"],"r":"September 18"},{"t":"Yakuza 0","p":["PlayStation 4"],"g":"Action-adventure","r":"January 24","l":"https://en.wikipedia.org/wiki/Yakuza_0"},{"t":"Yakuza Kiwami","p":["PlayStation 4"],"g":"Action-adventure","r":"August 29","l":"https://en.wikipedia.org/wiki/Yakuza_Kiwami"},{"t":"Yakuza Kiwami 2","p":["PlayStation 4"],"g":"Action-adventure","r":"December 7","l":"https://en.wikipedia.org/wiki/Yakuza_Kiwami_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob1qc.jpg","s":"Yakuza Kiwami 2 is a remake of Yakuza 2, and is an action-adventure game set in an open world environment and played from a third-person perspective. Combat is based on that previously seen in Yakuza 6. A new \"Majima Saga\" story scenario features recurring series anti-hero Goro Majima as a playable character."},{"t":"Yo! Noid 2: Enter the Void","p":["Windows","macOS"],"d":"Dustin Bragg","g":"Platform","r":"August 1, 2017","l":"https://en.wikipedia.org/wiki/Yo!_Noid_2:_Enter_the_Void"},{"t":"Yo-Kai Watch 2: Psychic Specters","p":["Nintendo 3DS"],"g":"RPG","r":"September 29","l":"https://en.wikipedia.org/wiki/Yo-kai_Watch_2"},{"t":"Yo-kai Watch Busters 2: Secret of the Legendary Treasure Bambalaya","p":["Nintendo 3DS"],"d":"Digital Works Entertainment","u":"Level-5","g":"Role-playing","r":"December 16, 2017","l":"https://en.wikipedia.org/wiki/Yo-kai_Watch_Busters_2:_Secret_of_the_Legendary_Treasure_Bambalaya"},{"t":"Yomawari: Midnight Shadows","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Survival horror","r":"October 24"},{"t":"Yonder: The Cloud Catcher Chronicles","p":["Windows","PlayStation 4"],"g":"Adventure","r":"July 18"},{"t":"Yooka-Laylee","p":["Windows","macOS","PlayStation 4","Xbox One","Nintendo Switch"],"g":"Platformer","r":"April 11","l":"https://en.wikipedia.org/wiki/Yooka-Laylee","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z4v.jpg","s":"Explore huge, beautiful worlds, meet (and beat) an unforgettable cast of characters and horde a vault-load of shiny collectibles as buddy-duo Yooka (the green one) and Laylee (the wisecracking bat with the big nose) embark on an epic adventure to thwart corporate creep Capital B and his devious scheme to absorb all the world’s books… and convert them into pure profit!"},{"t":"Your Turn to Die -Death Game by Majority-","p":["Windows"],"u":"0up Games","g":"Adventure","r":"August 28, 2017","l":"https://en.wikipedia.org/wiki/Your_Turn_to_Die_-Death_Game_by_Majority-","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co65s3.jpg","s":"Your Turn To Die: Death Game By Majority is a multi-ending horror adventure game. Your decision will directly affect the story and final outcome!"},{"t":"Youtubers Life","p":["Windows","macOS","Android","Linux","iOS","PlayStation 4","Xbox One","Nintendo Switch"],"d":"U-Play online","u":"U-Play online and Raiser Games","g":"Life simulation, business simulation","r":"February 2, 2017","l":"https://en.wikipedia.org/wiki/Youtubers_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fem4lolwiafnbgliaims.jpg","s":"Youtubers Life is the ultimate vlogger tycoon/life-sim videogame. The main aim of this title is to become the world’s greatest youtuber in history. To achieve it, you will have to edit videos, get in touch with other video bloggers and try that fame doesn’t overload you. Create your own online video channel and upload videos to increase your fanbase, but keep an eye on your daily tasks while you don’t lose track of your social life! You'll have to deal with fans, friends, family and time management! Increase your popularity so you can move to a new place and manage your own video content creators network company."},{"t":"Ys Origin","p":["PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"February 21","l":"https://en.wikipedia.org/wiki/Ys_Origin"},{"t":"Ys Seven","p":["Windows"],"g":"Action RPG","r":"August 30","l":"https://en.wikipedia.org/wiki/Ys_Seven"},{"t":"Ys VIII: Lacrimosa of Dana","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Action RPG","r":"September 12","l":"https://www.igdb.com/games/ys-viii-lacrimosa-of-dana","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co234k.jpg","s":"Ys returns with a brand new adventure for the first time in 8 years! Adol awakens shipwrecked and stranded on a cursed island. There, he and the other shipwrecked passengers he rescues form a village to challenge fearsome beasts and mysterious ruins on the isolated island."},{"t":"Zero Escape: The Nonary Games","p":["Windows","PlayStation 4","PlayStation Vita"],"g":"Adventure","r":"March 24","l":"https://en.wikipedia.org/wiki/Zero_Escape"},{"t":"Zwei: The Ilvard Insurrection","p":["Windows"],"g":"Action RPG","r":"October 31"},{"t":"Ōkami HD","p":["Windows","PlayStation 4","Xbox One"],"d":"Capcom","u":"Capcom","g":"Action-adventure","r":"December 12, 2017","l":"https://en.wikipedia.org/wiki/%C5%8Ckami#High-definition_remaster","i":"images/steam-587620.jpg","s":"Experience the critically acclaimed masterpiece with its renowned Sumi-e ink art style in breathtaking high resolution."}];
